(374327,41592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçak, kokpitten gözlemlendiği üzere, genç bir pilot tarafından kalın bulutların içinden ...'::text,'uçuruldu'::text,'uçurdu'::text,'uçuruyor'::text,'Uçak, kokpitten gözlemlendiği üzere, genç bir pilot tarafından kalın bulutların içinden uçuruldu.'::text),
(374328,41592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A repülőgépet egy fiatal pilóta ... át a sűrű felhőkön, ahogy a pilótafülkéből megfigyelték.'::text,'vezette'::text,'vezette'::text,'vezeti'::text,'A repülőgépet egy fiatal pilóta vezette át a sűrű felhőkön, ahogy a pilótafülkéből megfigyelték.'::text),
(374340,41594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du ... es lieben, Flugzeuge zu fliegen; du lächelst den ganzen Weg nach unten.'::text,'musst'::text,'kannst nicht'::text,'solltest nicht'::text,'Ganz ehrlich, du musst es lieben, Flugzeuge zu fliegen; du lächelst den ganzen Weg nach unten.'::text),
(374344,41594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... обожнювати пілотувати літаки; ти усміхаєшся всю дорогу вниз.'::text,'мусиш'::text,'не можеш'::text,'не повинен'::text,'Чесно, ти мусиш обожнювати пілотувати літаки; ти усміхаєшся всю дорогу вниз.'::text),
(374343,41594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... encantarte pilotar aviones; sonríes durante todo el descenso.'::text,'debe'::text,'no puede'::text,'no debería'::text,'No te voy a mentir, debe encantarte pilotar aviones; sonríes durante todo el descenso.'::text),
(374342,41594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... adorer piloter des avions ; tu souris pendant toute la descente.'::text,'dois'::text,'ne peux pas'::text,'ne devrais pas'::text,'Franchement, tu dois adorer piloter des avions ; tu souris pendant toute la descente.'::text),
(374345,41594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, uçak uçurmayı ...; iniş boyunca gülümseyip duruyorsun.'::text,'seviyor olmalısın'::text,'sevemezsin'::text,'sevmemelisin'::text,'Yalan yok, uçak uçurmayı seviyor olmalısın; iniş boyunca gülümseyip duruyorsun.'::text),
(374346,41594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... a repülőgépek vezetését; végig mosolyogsz lefelé menet.'::text,'biztos imádod'::text,'nem imádhatod'::text,'nem kéne imádnod'::text,'Őszintén, biztos imádod a repülőgépek vezetését; végig mosolyogsz lefelé menet.'::text),
(374349,41595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du bist die Art Pilot, ... mit einem Lächeln durch dichte Wolken fliegen kann.'::text,'der'::text,'was'::text,'dessen'::text,'Respekt, du bist die Art Pilot, der mit einem Lächeln durch dichte Wolken fliegen kann.'::text),
(374353,41595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти з тих пілотів, ... можуть пілотувати крізь густі хмари з усмішкою.'::text,'які'::text,'що'::text,'чиї'::text,'Респект, ти з тих пілотів, які можуть пілотувати крізь густі хмари з усмішкою.'::text),
(374352,41595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, eres el tipo de piloto ... puede pilotar entre nubes densas con una sonrisa.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Respeto, eres el tipo de piloto que puede pilotar entre nubes densas con una sonrisa.'::text),
(374351,41595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu es le genre de pilote ... peut piloter à travers d''épais nuages avec le sourire.'::text,'qui'::text,'lequel'::text,'dont'::text,'Respect, tu es le genre de pilote qui peut piloter à travers d''épais nuages avec le sourire.'::text),
(374354,41595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar, sen öyle bir pilotsun ... kalın bulutların içinden gülümseyerek uçabiliyorsun.'::text,'ki'::text,'ki'::text,'ki'::text,'Saygılar, sen öyle bir pilotsun ki kalın bulutların içinden gülümseyerek uçabiliyorsun.'::text),
(374355,41595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, te az a fajta pilóta vagy, ... mosolyogva is átvezeti a gépet a sűrű felhőkön.'::text,'aki'::text,'ami'::text,'akinek'::text,'Respekt, te az a fajta pilóta vagy, aki mosolyogva is átvezeti a gépet a sűrű felhőkön.'::text),
(374358,41596,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er erzählte uns, er ... an dem Tag zum ersten Mal ein Flugzeug. Null Stress, ganz klar.'::text,'flog'::text,'fliegt gerade'::text,'fliegt'::text,'Er erzählte uns, er flog an dem Tag zum ersten Mal ein Flugzeug. Null Stress, ganz klar.'::text),
(374362,41596,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав нам, що того дня ... літак уперше. Жодного стресу, звісно.'::text,'пілотував'::text,'пілотує'::text,'пілотує'::text,'Він сказав нам, що того дня пілотував літак уперше. Жодного стресу, звісно.'::text),
(374361,41596,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nos dijo que ese día ... un avión por primera vez. Cero estrés, claramente.'::text,'estaba pilotando'::text,'está pilotando'::text,'pilota'::text,'Nos dijo que ese día estaba pilotando un avión por primera vez. Cero estrés, claramente.'::text),
(374360,41596,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il nous a dit qu''il ... un avion pour la première fois ce jour-là. Zéro stress, évidemment.'::text,'pilotait'::text,'est en train de piloter'::text,'pilote'::text,'Il nous a dit qu''il pilotait un avion pour la première fois ce jour-là. Zéro stress, évidemment.'::text),
