(374371,41597,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж стати пілотом, він ... лише іграшкові літаки в парку.'::text,'запускав'::text,'запускав раніше'::text,'звик запускати'::text,'Перш ніж стати пілотом, він запускав лише іграшкові літаки в парку.'::text),
