(374369,41597,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de devenir pilote, il ... seulement des avions jouets au parc.'::text,'pilotait'::text,'pilotait'::text,'avait l''habitude de piloter'::text,'Avant de devenir pilote, il pilotait seulement des avions jouets au parc.'::text),
