(374394,41600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er ist noch nie durch so dicke Wolken geflogen, und ehrlich gesagt ...'::text,'ich auch nicht.'::text,'ich auch.'::text,'ich auch nicht.'::text,'Digga, er ist noch nie durch so dicke Wolken geflogen, und ehrlich gesagt ich auch nicht.'::text),
(374398,41600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ще ніколи не літав крізь такі густі хмари, і, чесно, ...'::text,'я теж ні.'::text,'я теж.'::text,'я теж ні.'::text,'Бро, він ще ніколи не літав крізь такі густі хмари, і, чесно, я теж ні.'::text),
