(374403,41601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Flugzeug vor der Landung 6 Stunden lang, exakt im Zeitplan.'::text,'steuerte'::text,'steuert'::text,'steuert gerade'::text,'Er steuerte das Flugzeug vor der Landung 6 Stunden lang, exakt im Zeitplan.'::text),
(374407,41601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... літак 6 годин до посадки, точно за графіком.'::text,'пілотував'::text,'пілотує'::text,'пілотує'::text,'Він пілотував літак 6 годин до посадки, точно за графіком.'::text),
(374406,41601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... el avión 6 horas antes del aterrizaje, exactamente según el cronograma.'::text,'había estado pilotando'::text,'ha estado pilotando'::text,'está pilotando'::text,'Él había estado pilotando el avión 6 horas antes del aterrizaje, exactamente según el cronograma.'::text),
(374405,41601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''avion pendant 6 heures avant l''atterrissage, pile dans les délais.'::text,'avait piloté'::text,'a piloté'::text,'pilote'::text,'Il avait piloté l''avion pendant 6 heures avant l''atterrissage, pile dans les délais.'::text),
