(374409,41601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leszállás előtt 6 órán át ... a gépet, pontosan az ütemterv szerint.'::text,'vezette'::text,'vezeti'::text,'vezeti'::text,'Leszállás előtt 6 órán át vezette a gépet, pontosan az ütemterv szerint.'::text),
(339438,37716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... sie über den Bullen, als er auf das Auto losging.'::text,'lachten gerade'::text,'lachten'::text,'haben gelacht'::text,'Mädel, anscheinend lachten gerade sie über den Bullen, als er auf das Auto losging.'::text),
