(339441,37716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... del toro cuando embistió el coche.'::text,'se estaban riendo'::text,'se rieron'::text,'se han reído'::text,'Tía, al parecer se estaban riendo del toro cuando embistió el coche.'::text),
