(339443,37716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, görünüşe göre boğa arabaya saldırdığında ona ...'::text,'gülüyorlardı'::text,'güldüler'::text,'gülmüşler'::text,'Kızım, görünüşe göre boğa arabaya saldırdığında ona gülüyorlardı.'::text),
