(339452,37717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bütün hafta boğa saldırısı hikâyesini ... ve hâlâ o kadar iyi.'::text,'anlatıp duruyorsun'::text,'anlatıyorsun'::text,'anlatırsın'::text,'Yalan yok, bütün hafta boğa saldırısı hikâyesini anlatıp duruyorsun ve hâlâ o kadar iyi.'::text),
(339453,37717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, egész héten ... a bikatámadásos sztorit, és még mindig ugyanolyan jó.'::text,'meséled'::text,'meséled'::text,'meséled'::text,'Nem hazudok, egész héten meséled a bikatámadásos sztorit, és még mindig ugyanolyan jó.'::text),
(339456,37718,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bulle ... den Hund um, und dann ging er auf das Auto los.'::text,'warf'::text,'warf gerade'::text,'warf'::text,'Der Bulle warf den Hund um, und dann ging er auf das Auto los.'::text),
(339460,37718,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бик ... собаку, а потім кинувся на машину.'::text,'збив'::text,'збивав'::text,'збив'::text,'Бик збив собаку, а потім кинувся на машину.'::text),
(339459,37718,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El toro ... al perro y luego embistió el coche.'::text,'derribó'::text,'estaba derribando'::text,'ha derribado'::text,'El toro derribó al perro y luego embistió el coche.'::text),
(339458,37718,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le taureau ... le chien, puis il a chargé la voiture.'::text,'a renversé'::text,'renversait'::text,'a renversé'::text,'Le taureau a renversé le chien, puis il a chargé la voiture.'::text),
(339461,37718,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boğa köpeği yere ... ve sonra arabaya saldırdı.'::text,'serdi'::text,'seriyordu'::text,'serdi'::text,'Boğa köpeği yere serdi ve sonra arabaya saldırdı.'::text),
(339462,37718,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bika ... a kutyát, aztán rátámadt az autóra.'::text,'feldöntötte'::text,'döntötte fel'::text,'feldöntötte'::text,'A bika feldöntötte a kutyát, aztán rátámadt az autóra.'::text),
(339465,37719,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Bulle ... diese Woche auf diesem Weg dreimal Autos angegriffen.'::text,'hat'::text,'hat'::text,'greift'::text,'Dieser Bulle hat diese Woche auf diesem Weg dreimal Autos angegriffen.'::text),
(339469,37719,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей бик цього тижня ... на машини на цій дорозі тричі.'::text,'кидався'::text,'кидався'::text,'кидається'::text,'Цей бик цього тижня кидався на машини на цій дорозі тричі.'::text),
(339468,37719,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este toro ... coches en este camino tres veces esta semana.'::text,'ha embestido'::text,'ha estado embistiendo'::text,'embiste'::text,'Este toro ha embestido coches en este camino tres veces esta semana.'::text),
(339467,37719,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce taureau ... des voitures sur ce chemin trois fois cette semaine.'::text,'a chargé'::text,'charge depuis'::text,'charge'::text,'Ce taureau a chargé des voitures sur ce chemin trois fois cette semaine.'::text),
(339470,37719,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu boğa bu hafta bu yolda üç kez arabalara ...'::text,'saldırdı'::text,'saldırıp duruyor'::text,'saldırır'::text,'Bu boğa bu hafta bu yolda üç kez arabalara saldırdı.'::text),
(339471,37719,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a bika ezen a héten háromszor ... autókra ezen az úton.'::text,'támadt rá'::text,'támadt rá'::text,'támad rá'::text,'Ez a bika ezen a héten háromszor támadt rá autókra ezen az úton.'::text),
(339474,37720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Bulle angriff, ... die Männer das Autofenster noch nicht geschlossen.'::text,'hatten'::text,'haben'::text,'schließen'::text,'Als der Bulle angriff, hatten die Männer das Autofenster noch nicht geschlossen.'::text),
(339478,37720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли бик кинувся, чоловіки ще ... вікно машини.'::text,'не зачинили'::text,'не зачинили'::text,'не зачиняють'::text,'Коли бик кинувся, чоловіки ще не зачинили вікно машини.'::text),
(339477,37720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el toro embistió, los hombres no ... la ventanilla del coche.'::text,'habían cerrado'::text,'han cerrado'::text,'cierran'::text,'Para cuando el toro embistió, los hombres no habían cerrado la ventanilla del coche.'::text),
(339476,37720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où le taureau a chargé, les hommes ... la vitre de la voiture.'::text,'n''avaient pas fermé'::text,'n''ont pas fermé'::text,'ne ferment pas'::text,'Au moment où le taureau a chargé, les hommes n''avaient pas fermé la vitre de la voiture.'::text),
(339479,37720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boğa saldırdığında adamlar arabanın camını henüz ...'::text,'kapatmamışlardı'::text,'kapatmadılar'::text,'kapatmıyorlar'::text,'Boğa saldırdığında adamlar arabanın camını henüz kapatmamışlardı.'::text),
(339480,37720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a bika támadott, a férfiak még nem ... be az autó ablakát.'::text,'csukták'::text,'csukták'::text,'csukják'::text,'Mire a bika támadott, a férfiak még nem csukták be az autó ablakát.'::text),
(339483,37721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Tier das Auto als Bedrohung wahrnimmt, ...'::text,'wird es erneut angreifen'::text,'würde es erneut angreifen'::text,'griff es erneut an'::text,'Wenn das Tier das Auto als Bedrohung wahrnimmt, wird es erneut angreifen.'::text),
(339487,37721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо тварина сприймає машину як загрозу, вона знову ...'::text,'кинеться'::text,'кинулася б'::text,'кинулася'::text,'Якщо тварина сприймає машину як загрозу, вона знову кинеться.'::text),
(339486,37721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el animal percibe el coche como una amenaza, ... de nuevo.'::text,'embestirá'::text,'embestiría'::text,'embistió'::text,'Si el animal percibe el coche como una amenaza, embestirá de nuevo.'::text),
(339485,37721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''animal perçoit la voiture comme une menace, il ... à nouveau.'::text,'chargera'::text,'chargerait'::text,'a chargé'::text,'Si l''animal perçoit la voiture comme une menace, il chargera à nouveau.'::text),
(339488,37721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayvan arabayı bir tehdit olarak algılarsa tekrar ...'::text,'saldıracak'::text,'saldırırdı'::text,'saldırdı'::text,'Hayvan arabayı bir tehdit olarak algılarsa tekrar saldıracak.'::text),
(339489,37721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az állat fenyegetésként érzékeli az autót, újra ...'::text,'támadni fog'::text,'támadna'::text,'támadt'::text,'Ha az állat fenyegetésként érzékeli az autót, újra támadni fog.'::text),
(339501,37723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der kleine Hund ... vom angreifenden Bullen! Totales Chaos!'::text,'wurde umgerannt'::text,'rannte um'::text,'rennt um'::text,'Der kleine Hund wurde umgerannt vom angreifenden Bullen! Totales Chaos!'::text),
(339505,37723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький песик ... биком, що атакував! Повний хаос!'::text,'був збитий'::text,'збив'::text,'збиває'::text,'Маленький песик був збитий биком, що атакував! Повний хаос!'::text),
(339504,37723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El perrito ... por el toro que embestía! ¡Caos absoluto!'::text,'fue derribado'::text,'derribó'::text,'está derribando'::text,'¡El perrito fue derribado por el toro que embestía! ¡Caos absoluto!'::text),
(339503,37723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit chien ... par le taureau qui chargeait ! Le chaos total !'::text,'a été renversé'::text,'a renversé'::text,'renverse'::text,'Le petit chien a été renversé par le taureau qui chargeait ! Le chaos total !'::text),
(339506,37723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük köpek saldıran boğa tarafından ...! Tam bir kaos!'::text,'yere serildi'::text,'yere serdi'::text,'yere seriyor'::text,'Küçük köpek saldıran boğa tarafından yere serildi! Tam bir kaos!'::text),
(339507,37723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis kutyát ... a támadó bika! Teljes káosz!'::text,'feldöntötte'::text,'feldöntötte'::text,'feldönti'::text,'A kis kutyát feldöntötte a támadó bika! Teljes káosz!'::text),
(339510,37724,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bulle ... direkt auf das Auto zu, und die Männer schrien!'::text,'stürmte'::text,'wurde gestürmt'::text,'stürmend'::text,'Der Bulle stürmte direkt auf das Auto zu, und die Männer schrien!'::text),
(339514,37724,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бик ... прямо на машину, і чоловіки закричали!'::text,'кинувся'::text,'був атакований'::text,'кидаючись'::text,'Бик кинувся прямо на машину, і чоловіки закричали!'::text),
(339513,37724,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El toro ... directo hacia el coche y los hombres gritaron!'::text,'embistió'::text,'fue embestido'::text,'embistiendo'::text,'¡El toro embistió directo hacia el coche y los hombres gritaron!'::text),
(339512,37724,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le taureau ... droit sur la voiture, et les hommes ont hurlé !'::text,'a foncé'::text,'a été chargé'::text,'fonçant'::text,'Le taureau a foncé droit sur la voiture, et les hommes ont hurlé !'::text),
(339515,37724,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boğa doğrudan arabaya ... ve adamlar çığlık attı!'::text,'saldırdı'::text,'saldırıya uğradı'::text,'saldırarak'::text,'Boğa doğrudan arabaya saldırdı ve adamlar çığlık attı!'::text),
(339516,37724,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bika egyenesen ... az autónak, és a férfiak felsikítottak!'::text,'nekirontott'::text,'meg lett támadva'::text,'nekirontva'::text,'A bika egyenesen nekirontott az autónak, és a férfiak felsikítottak!'::text),
(339519,37725,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, der Bulle ... echt wütend sein, wenn er so auf das Auto losgeht.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Hör zu, er hat mir gesagt, der Bulle muss echt wütend sein, wenn er so auf das Auto losgeht.'::text),
(339523,37725,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що бик ... бути дуже злим, щоб так кинутися на машину.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Слухай, він сказав мені, що бик мусить бути дуже злим, щоб так кинутися на машину.'::text),
(339522,37725,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que el toro ... estar muy enfadado para embestir así el coche.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Escucha, me dijo que el toro debe de estar muy enfadado para embestir así el coche.'::text),
(339521,37725,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que le taureau ... être vraiment en colère pour charger la voiture comme ça.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Écoute, il m''a dit que le taureau doit être vraiment en colère pour charger la voiture comme ça.'::text),
(339524,37725,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dedi ki boğa arabaya öyle saldırdığına göre gerçekten kızgın ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Dinle, bana dedi ki boğa arabaya öyle saldırdığına göre gerçekten kızgın olmalı.'::text),
(339525,37725,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a bika ... nagyon dühös, ha így nekirontott az autónak.'::text,'biztos'::text,'nem lehet'::text,'nem szabad'::text,'Figyelj, azt mondta, hogy a bika biztos nagyon dühös, ha így nekirontott az autónak.'::text),
(388056,43118,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du liebst es so sehr, dass du bestimmt wieder den Kanal ...'::text,'runterrutschen wirst'::text,'am Runterrutschen sein wirst'::text,'runterrutschst'::text,'Ehrlich, du liebst es so sehr, dass du bestimmt wieder den Kanal runterrutschen wirst.'::text),
(388060,43118,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, тобі це так подобається, що я впевнена: ти знову ... тим каналом.'::text,'з''їдеш'::text,'з''їжджатимеш'::text,'з''їжджаєш'::text,'Чесно, тобі це так подобається, що я впевнена: ти знову з''їдеш тим каналом.'::text),
(388059,43118,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, te encanta tanto que seguro que ... otra vez por ese canal.'::text,'te deslizarás'::text,'te estarás deslizando'::text,'te estás deslizando'::text,'Sinceramente, te encanta tanto que seguro que te deslizarás otra vez por ese canal.'::text),
(388058,43118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu adores tellement ça que je suis sûre que tu ... encore dans ce canal.'::text,'glisseras'::text,'seras en train de glisser'::text,'glisses'::text,'Franchement, tu adores tellement ça que je suis sûre que tu glisseras encore dans ce canal.'::text),
(388061,43118,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o kadar seviyorsun ki eminim o kanaldan yine ...'::text,'kayacaksın'::text,'kayıyor olacaksın'::text,'kayıyorsun'::text,'Açıkçası o kadar seviyorsun ki eminim o kanaldan yine kayacaksın.'::text),
(388062,43118,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, annyira imádod, hogy biztos újra ... azon a csatornán.'::text,'le fogsz csúszni'::text,'csúszni fogsz'::text,'csúszol'::text,'Őszintén, annyira imádod, hogy biztos újra le fogsz csúszni azon a csatornán.'::text),
(388065,43119,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Beton nass ist, ... die Leute leicht darauf entlang.'::text,'rutschen'::text,'rutschten'::text,'werden rutschen'::text,'Wenn der Beton nass ist, rutschen die Leute leicht darauf entlang.'::text),
(388069,43119,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо бетон мокрий, люди легко ... по ньому.'::text,'ковзають'::text,'ковзали'::text,'ковзатимуть'::text,'Якщо бетон мокрий, люди легко ковзають по ньому.'::text),
(388068,43119,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hormigón está mojado, la gente ... por él fácilmente.'::text,'se desliza'::text,'se deslizó'::text,'se deslizará'::text,'Si el hormigón está mojado, la gente se desliza por él fácilmente.'::text),
(388067,43119,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le béton est mouillé, les gens ... facilement dessus.'::text,'glissent'::text,'ont glissé'::text,'glisseront'::text,'Si le béton est mouillé, les gens glissent facilement dessus.'::text),
(388070,43119,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beton ıslaksa insanlar üzerinde kolayca ...'::text,'kayar'::text,'kaydı'::text,'kayacak'::text,'Beton ıslaksa insanlar üzerinde kolayca kayar.'::text),
(388071,43119,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a beton nedves, az emberek könnyen ... rajta.'::text,'csúsznak'::text,'csúsztak'::text,'csúszni fognak'::text,'Ha a beton nedves, az emberek könnyen csúsznak rajta.'::text),
(388074,43120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch schneller rutscht, ... er von der Mauerkante.'::text,'fällt'::text,'würde fallen'::text,'fiel'::text,'Wenn er noch schneller rutscht, fällt er von der Mauerkante.'::text),
(388078,43120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він ковзатиме ще швидше, то ... з краю стіни.'::text,'впаде'::text,'впав би'::text,'впав'::text,'Якщо він ковзатиме ще швидше, то впаде з краю стіни.'::text),
(388077,43120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se desliza más rápido, ... por el borde del muro.'::text,'se caerá'::text,'se caería'::text,'se cayó'::text,'Si se desliza más rápido, se caerá por el borde del muro.'::text),
(388076,43120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il glisse encore plus vite, il ... du bord du mur.'::text,'tombera'::text,'tomberait'::text,'est tombé'::text,'S''il glisse encore plus vite, il tombera du bord du mur.'::text),
(388079,43120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz daha hızlı kayarsa duvarın kenarından ...'::text,'düşecek'::text,'düşerdi'::text,'düştü'::text,'Biraz daha hızlı kayarsa duvarın kenarından düşecek.'::text),
(388080,43120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még gyorsabban csúszik, ... a fal széléről.'::text,'le fog esni'::text,'leesne'::text,'leesett'::text,'Ha még gyorsabban csúszik, le fog esni a fal széléről.'::text),
(388083,43121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Kanal trocken wäre, ... sie darauf überhaupt nicht.'::text,'rutschten'::text,'rutschen'::text,'rutschen'::text,'Wenn der Kanal trocken wäre, rutschten sie darauf überhaupt nicht.'::text),
(388087,43121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби канал був сухим, вони взагалі ... по ньому.'::text,'не ковзали б'::text,'не ковзатимуть'::text,'не ковзають'::text,'Якби канал був сухим, вони взагалі не ковзали б по ньому.'::text),
(388086,43121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el canal estuviera seco, ... por él en absoluto.'::text,'no se deslizarían'::text,'no se deslizarán'::text,'no se deslizan'::text,'Si el canal estuviera seco, no se deslizarían por él en absoluto.'::text),
(388085,43121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le canal était sec, ils ... pas du tout dessus.'::text,'ne glisseraient'::text,'ne glisseront'::text,'ne glissent'::text,'Si le canal était sec, ils ne glisseraient pas du tout dessus.'::text),
(388088,43121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanal kuru olsaydı, üzerinde hiç ...'::text,'kaymazlardı'::text,'kaymayacaklar'::text,'kaymıyorlar'::text,'Kanal kuru olsaydı, üzerinde hiç kaymazlardı.'::text),
(388089,43121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a csatorna száraz lenne, egyáltalán ... rajta.'::text,'nem csúsznának'::text,'nem fognak csúszni'::text,'nem csúsznak'::text,'Ha a csatorna száraz lenne, egyáltalán nem csúsznának rajta.'::text),
(388092,43122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der ganze Dschungel ... von ihren Schreien, als sie die Mauer entlangrutschten!'::text,'wurde geweckt'::text,'erwachte'::text,'wacht gerade auf'::text,'Der ganze Dschungel wurde geweckt von ihren Schreien, als sie die Mauer entlangrutschten!'::text),
(388096,43122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі джунглі ... їхніми криками, коли вони ковзали по стіні!'::text,'були розбуджені'::text,'прокинулися'::text,'прокидаються'::text,'Усі джунглі були розбуджені їхніми криками, коли вони ковзали по стіні!'::text),
(388095,43122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Toda la selva ... por sus gritos mientras se deslizaban por el muro!'::text,'fue despertada'::text,'despertó'::text,'está despertando'::text,'¡Toda la selva fue despertada por sus gritos mientras se deslizaban por el muro!'::text),
(388094,43122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la jungle ... par leurs cris pendant qu''ils glissaient le long du mur !'::text,'a été réveillée'::text,'s''est réveillée'::text,'se réveille'::text,'Toute la jungle a été réveillée par leurs cris pendant qu''ils glissaient le long du mur !'::text),
(388097,43122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün orman, duvar boyunca kayarlarken attıkları çığlıklarla ...!'::text,'uyandırıldı'::text,'uyandı'::text,'uyanıyor'::text,'Bütün orman, duvar boyunca kayarlarken attıkları çığlıklarla uyandırıldı!'::text),
(388098,43122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész dzsungelt ... a sikolyaik, ahogy végigcsúsztak a falon!'::text,'felébresztették'::text,'felébredt'::text,'ébred'::text,'Az egész dzsungelt felébresztették a sikolyaik, ahogy végigcsúsztak a falon!'::text),
(388101,43123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Mauer entlang, ohne jede Möglichkeit anzuhalten!'::text,'rutschten'::text,'wurden gerutscht'::text,'rutschend'::text,'Sie rutschten die Mauer entlang, ohne jede Möglichkeit anzuhalten!'::text),
(388105,43123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... по стіні, і зупинитися не було жодного способу!'::text,'ковзали'::text,'були зсунуті'::text,'ковзаючи'::text,'Вони ковзали по стіні, і зупинитися не було жодного способу!'::text),
(388104,43123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... por el muro sin ninguna forma de frenar!'::text,'se deslizaron'::text,'fueron deslizados'::text,'deslizándose'::text,'¡Ellos se deslizaron por el muro sin ninguna forma de frenar!'::text),
(388103,43123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le long du mur sans aucun moyen de s''arrêter !'::text,'ont glissé'::text,'ont été glissés'::text,'glissant'::text,'Ils ont glissé le long du mur sans aucun moyen de s''arrêter !'::text),
(388106,43123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvar boyunca durmanın hiçbir yolu olmadan ...!'::text,'kaydılar'::text,'kaydırıldılar'::text,'kayarak'::text,'Duvar boyunca durmanın hiçbir yolu olmadan kaydılar!'::text),
(388107,43123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők ... végig a falon, és semmi esélyük nem volt megállni!'::text,'csúsztak'::text,'csúsztatva lettek'::text,'csúszva'::text,'Ők csúsztak végig a falon, és semmi esélyük nem volt megállni!'::text),
(388110,43124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... jeden Moment direkt über die Kante rutschen. Totale Katastrophe!'::text,'könnte'::text,'muss'::text,'sollte'::text,'Er könnte jeden Moment direkt über die Kante rutschen. Totale Katastrophe!'::text),
(388114,43124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... будь-якої секунди зісковзнути прямо з краю. Повна катастрофа!'::text,'може'::text,'мусить'::text,'повинен'::text,'Він може будь-якої секунди зісковзнути прямо з краю. Повна катастрофа!'::text),
(388113,43124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... resbalar por el borde en cualquier momento. ¡Desastre total!'::text,'podría'::text,'debe'::text,'debería'::text,'Él podría resbalar por el borde en cualquier momento. ¡Desastre total!'::text),
(388112,43124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... glisser du bord d''une seconde à l''autre. Désastre total !'::text,'pourrait'::text,'doit'::text,'devrait'::text,'Il pourrait glisser du bord d''une seconde à l''autre. Désastre total !'::text),
(388115,43124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kenardan kayıp düşmesi her an ..., tam bir felaket!'::text,'mümkün'::text,'şart'::text,'gerek'::text,'Kenardan kayıp düşmesi her an mümkün, tam bir felaket!'::text),
(388116,43124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bármelyik pillanatban ... a széléről. Totális katasztrófa!'::text,'lecsúszhat'::text,'le kell csúsznia'::text,'le kéne csúsznia'::text,'Bármelyik pillanatban lecsúszhat a széléről. Totális katasztrófa!'::text),
(388119,43125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also anscheinend ist der Typ, ... zuerst gerutscht ist, der Mutigste.'::text,'der'::text,'was'::text,'dessen'::text,'Okay, also anscheinend ist der Typ, der zuerst gerutscht ist, der Mutigste.'::text),
(388123,43125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, кажуть, хлопець, ... з''їхав першим, найсміливіший.'::text,'який'::text,'що'::text,'чий'::text,'Отже, кажуть, хлопець, який з''їхав першим, найсміливіший.'::text),
(388122,43125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer el chico ... se deslizó primero es el más valiente.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Vale, pues al parecer el chico que se deslizó primero es el más valiente.'::text),
(388121,43125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment le mec ... a glissé en premier est le plus courageux.'::text,'qui'::text,'lequel'::text,'dont'::text,'Bon alors, apparemment le mec qui a glissé en premier est le plus courageux.'::text),
(388124,43125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, görünüşe göre ... ilk kayan çocuk en cesur olanmış.'::text,''::text,NULL::text,NULL::text,'Tamam yani, görünüşe göre ilk kayan çocuk en cesur olanmış.'::text),
(388125,43125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Na szóval, állítólag az a srác, ... elsőként csúszott le, a legbátrabb.'::text,'aki'::text,'ami'::text,'akinek'::text,'Na szóval, állítólag az a srác, aki elsőként csúszott le, a legbátrabb.'::text),
(388128,43126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, sie ... auch am Vortag schon die Mauer runtergerutscht.'::text,'waren'::text,'sind'::text,'rutschen'::text,'Hör zu, er hat mir erzählt, sie waren auch am Vortag schon die Mauer runtergerutscht.'::text),
(388132,43126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що вони ... з тієї стіни й напередодні.'::text,'з''їжджали'::text,'з''їжджали'::text,'з''їжджають'::text,'Слухай, він сказав мені, що вони з''їжджали з тієї стіни й напередодні.'::text),
(388131,43126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que el día anterior también ... por ese muro.'::text,'se habían deslizado'::text,'se han deslizado'::text,'se deslizan'::text,'Escucha, me dijo que el día anterior también se habían deslizado por ese muro.'::text),
(388130,43126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''ils ... le long de ce mur la veille aussi.'::text,'avaient glissé'::text,'ont glissé'::text,'glissent'::text,'Écoute, il m''a dit qu''ils avaient glissé le long de ce mur la veille aussi.'::text),
(388133,43126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana bir gün önce de o duvardan ... söyledi.'::text,'kaydıklarını'::text,'kaydıklarını'::text,'kaydıklarını'::text,'Dinle, bana bir gün önce de o duvardan kaydıklarını söyledi.'::text),
(388134,43126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy előző nap is ... azon a falon.'::text,'lecsúsztak'::text,'lecsúsztak'::text,'lecsúsznak'::text,'Figyelj, azt mondta, hogy előző nap is lecsúsztak azon a falon.'::text),
(388146,43128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, es macht dir nichts aus, eine nasse Mauer ..., und das ist echt cool.'::text,'runterzurutschen'::text,'runterzurutschen'::text,'runterrutschen'::text,'Ehrlich, es macht dir nichts aus, eine nasse Mauer runterzurutschen, und das ist echt cool.'::text),
(388150,43128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти не проти ... мокрою стіною, і це реально круто.'::text,'з''їжджати'::text,'з''їжджати'::text,'з''їжджаєш'::text,'Чесно, ти не проти з''їжджати мокрою стіною, і це реально круто.'::text),
(388149,43128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, no te importa ... por un muro mojado, y eso es muy guay.'::text,'deslizarte'::text,'deslizarte'::text,'te deslizas'::text,'Sinceramente, no te importa deslizarte por un muro mojado, y eso es muy guay.'::text),
(388148,43128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ça ne te dérange pas de ... le long d''un mur mouillé, et c''est trop cool.'::text,'glisser'::text,'glisser'::text,'glisses'::text,'Franchement, ça ne te dérange pas de glisser le long d''un mur mouillé, et c''est trop cool.'::text),
(388151,43128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası ıslak bir duvardan aşağı ... sorun etmiyorsun ve bu gerçekten havalı.'::text,'kaymayı'::text,'kaymayı'::text,'kay'::text,'Açıkçası ıslak bir duvardan aşağı kaymayı sorun etmiyorsun ve bu gerçekten havalı.'::text),
(388152,43128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, nem zavar, hogy ... egy nedves falon, és ez tényleg menő.'::text,'lecsúszol'::text,'lecsúszni'::text,'lecsússz'::text,'Őszintén, nem zavar, hogy lecsúszol egy nedves falon, és ez tényleg menő.'::text),
(401691,44633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Chihuahua ist kein Gabelstapler, also fährt er im Lager keinen, und ...'::text,'der andere kleine Hund auch nicht.'::text,'der andere kleine Hund auch nicht.'::text,'der andere kleine Hund schon.'::text,'Der Chihuahua ist kein Gabelstapler, also fährt er im Lager keinen, und der andere kleine Hund auch nicht.'::text),
(401695,44633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чихуахуа не навантажувач, тож не водить його на складі, і ...'::text,'інший маленький пес теж ні.'::text,'інший маленький пес теж ні.'::text,'інший маленький пес теж.'::text,'Чихуахуа не навантажувач, тож не водить його на складі, і інший маленький пес теж ні.'::text),
(401694,44633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chihuahua no es una carretilla elevadora, así que no conduce ninguna en el almacén, y ...'::text,'el otro perrito tampoco.'::text,'el otro perrito tampoco.'::text,'el otro perrito también.'::text,'El chihuahua no es una carretilla elevadora, así que no conduce ninguna en el almacén, y el otro perrito tampoco.'::text),
(401693,44633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chihuahua n''est pas un chariot élévateur, donc il n''en conduit pas dans l''entrepôt, et ...'::text,'l''autre petit chien non plus.'::text,'l''autre petit chien non plus.'::text,'l''autre petit chien aussi.'::text,'Le chihuahua n''est pas un chariot élévateur, donc il n''en conduit pas dans l''entrepôt, et l''autre petit chien non plus.'::text),
(401696,44633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chihuahua forklift değil, bu yüzden depoda forklift sürmüyor ve ...'::text,'diğer küçük köpek de sürmüyor.'::text,'diğer küçük köpek de değil.'::text,'diğer küçük köpek de sürüyor.'::text,'Chihuahua forklift değil, bu yüzden depoda forklift sürmüyor ve diğer küçük köpek de sürmüyor.'::text),
(401697,44633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csivava nem targonca, ezért nem vezet targoncát a raktárban, és ...'::text,'a másik kis kutya sem.'::text,'a másik kis kutya sem.'::text,'a másik kis kutya is.'::text,'A csivava nem targonca, ezért nem vezet targoncát a raktárban, és a másik kis kutya sem.'::text),
(401709,44635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, dass die Hunde bis Freitag jede Flasche vom Lagerboden ...'::text,'aufgehoben haben werden'::text,'aufheben werden'::text,'am Aufheben sein werden'::text,'Hör zu, ich hab gehört, dass die Hunde bis Freitag jede Flasche vom Lagerboden aufgehoben haben werden.'::text),
(401713,44635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що до п''ятниці собаки ... кожну пляшку з підлоги складу.'::text,'позбирають'::text,'позбирають'::text,'збиратимуть'::text,'Слухай, я чула, що до п''ятниці собаки позбирають кожну пляшку з підлоги складу.'::text),
(401712,44635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, oí que para el viernes los perros ... todas las botellas del suelo del almacén.'::text,'habrán recogido'::text,'recogerán'::text,'estarán recogiendo'::text,'Escucha, oí que para el viernes los perros habrán recogido todas las botellas del suelo del almacén.'::text),
(401711,44635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que d''ici vendredi les chiens ... toutes les bouteilles du sol de l''entrepôt.'::text,'auront ramassé'::text,'ramasseront'::text,'seront en train de ramasser'::text,'Écoute, j''ai entendu dire que d''ici vendredi les chiens auront ramassé toutes les bouteilles du sol de l''entrepôt.'::text),
(401714,44635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki cumaya kadar köpekler deponun zeminindeki her şişeyi ...'::text,'toplamış olacak'::text,'toplayacak'::text,'topluyor olacak'::text,'Dinle, duydum ki cumaya kadar köpekler deponun zeminindeki her şişeyi toplamış olacak.'::text),
(401715,44635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy péntekre a kutyák ... az összes üveget a raktár padlójáról.'::text,'felszedik'::text,'fel fogják szedni'::text,'szedni fogják'::text,'Figyelj, azt hallottam, hogy péntekre a kutyák felszedik az összes üveget a raktár padlójáról.'::text),
(401718,44636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super Arbeit, Team: Um Mitternacht ... die Hunde seit sechs Stunden Flaschen vom Lagerboden.'::text,'sammeln schon'::text,'sammeln gerade'::text,'haben gesammelt'::text,'Super Arbeit, Team: Um Mitternacht sammeln schon die Hunde seit sechs Stunden Flaschen vom Lagerboden.'::text),
(401722,44636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, команда: опівночі собаки вже шість годин ... пляшки з підлоги складу.'::text,'збиратимуть'::text,'збиратимуть'::text,'позбирають'::text,'Чудова робота, команда: опівночі собаки вже шість годин збиратимуть пляшки з підлоги складу.'::text),
(401721,44636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran trabajo, equipo: a medianoche los perros ... botellas del suelo del almacén durante seis horas.'::text,'habrán estado recogiendo'::text,'estarán recogiendo'::text,'habrán recogido'::text,'Gran trabajo, equipo: a medianoche los perros habrán estado recogiendo botellas del suelo del almacén durante seis horas.'::text),
(401720,44636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super boulot, l''équipe : à minuit, les chiens ... des bouteilles sur le sol de l''entrepôt depuis six heures.'::text,'ramasseront'::text,'seront en train de ramasser'::text,'auront ramassé'::text,'Super boulot, l''équipe : à minuit, les chiens ramasseront des bouteilles sur le sol de l''entrepôt depuis six heures.'::text),
(401723,44636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, ekip: gece yarısına kadar köpekler altı saattir deponun zemininden şişe ...'::text,'topluyor olacak'::text,'topluyor olacak'::text,'toplamış olacak'::text,'Harika iş, ekip: gece yarısına kadar köpekler altı saattir deponun zemininden şişe topluyor olacak.'::text),
(401724,44636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, csapat: éjfélre a kutyák már hat órája ... az üvegeket a raktár padlójáról.'::text,'szedegetik'::text,'szedegetni fogják'::text,'felszedték'::text,'Szép munka, csapat: éjfélre a kutyák már hat órája szedegetik az üvegeket a raktár padlójáról.'::text),
(401727,44637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolles Fahren, natürlich. Wäre der Hund langsamer gefahren, ... das Lager nicht so viel Wasser verloren.'::text,'hätte'::text,'wird'::text,'hat'::text,'Tolles Fahren, natürlich. Wäre der Hund langsamer gefahren, hätte das Lager nicht so viel Wasser verloren.'::text),
(401731,44637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудове водіння, звісно. Якби пес їхав повільніше, склад ... стільки води.'::text,'не втратив би'::text,'не втратить'::text,'не втратив'::text,'Чудове водіння, звісно. Якби пес їхав повільніше, склад не втратив би стільки води.'::text),
(401730,44637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué gran conducción, obvio. Si el perro hubiera ido más despacio, el almacén ... tanta agua.'::text,'no habría perdido'::text,'no perderá'::text,'no perdió'::text,'Qué gran conducción, obvio. Si el perro hubiera ido más despacio, el almacén no habría perdido tanta agua.'::text),
(401729,44637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super conduite, évidemment. Si le chien était allé moins vite, l''entrepôt ... autant d''eau.'::text,'n''aurait pas perdu'::text,'ne perdra pas'::text,'n''a pas perdu'::text,'Super conduite, évidemment. Si le chien était allé moins vite, l''entrepôt n''aurait pas perdu autant d''eau.'::text),
(401732,44637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika sürüş, belli. Köpek daha yavaş gitseydi depo bu kadar su ...'::text,'kaybetmezdi'::text,'kaybetmeyecek'::text,'kaybetmedi'::text,'Harika sürüş, belli. Köpek daha yavaş gitseydi depo bu kadar su kaybetmezdi.'::text),
(401733,44637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek vezetés, nyilván. Ha a kutya lassabban ment volna, a raktár ... ennyi vizet.'::text,'nem vesztett volna'::text,'nem fog veszíteni'::text,'nem vesztett'::text,'Remek vezetés, nyilván. Ha a kutya lassabban ment volna, a raktár nem vesztett volna ennyi vizet.'::text),
(401736,44638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, wenn der Stapler nicht gecrasht wäre, ... der Lagerboden jetzt trocken, ohne Witz.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Nee, wenn der Stapler nicht gecrasht wäre, wäre der Lagerboden jetzt trocken, ohne Witz.'::text),
(401740,44638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, якби той навантажувач не врізався, підлога складу зараз ... суха, чесне слово.'::text,'була б'::text,'була б'::text,'буде'::text,'Не, якби той навантажувач не врізався, підлога складу зараз була б суха, чесне слово.'::text),
(401739,44638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, si esa carretilla no hubiera chocado, el suelo del almacén ... seco ahora mismo, en serio.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Nah, si esa carretilla no hubiera chocado, el suelo del almacén estaría seco ahora mismo, en serio.'::text),
(401738,44638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, si ce chariot ne s''était pas crashé, le sol de l''entrepôt ... sec en ce moment, sans mentir.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Nan, si ce chariot ne s''était pas crashé, le sol de l''entrepôt serait sec en ce moment, sans mentir.'::text),
(401741,44638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, o forklift çarpmasaydı deponun zemini şu an kuru ..., yemin ederim.'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Yok, o forklift çarpmasaydı deponun zemini şu an kuru olurdu, yemin ederim.'::text),
(401742,44638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, ha az a targonca nem ütközik neki, a raktár padlója most ... száraz, komolyan.'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Nem, ha az a targonca nem ütközik neki, a raktár padlója most lenne száraz, komolyan.'::text),
(401745,44639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Golden Retriever soll den Gabelstapler in diesem Lager jahrelang ...'::text,'gefahren haben'::text,'fahren'::text,'fahrend'::text,'Der Golden Retriever soll den Gabelstapler in diesem Lager jahrelang gefahren haben.'::text),
(401749,44639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що золотистий ретривер ... навантажувач на цьому складі роками.'::text,'водив'::text,'водить'::text,'водячи'::text,'Кажуть, що золотистий ретривер водив навантажувач на цьому складі роками.'::text),
(401748,44639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el golden retriever ... la carretilla en este almacén durante años.'::text,'ha conducido'::text,'conduce'::text,'conduciendo'::text,'Se dice que el golden retriever ha conducido la carretilla en este almacén durante años.'::text),
(401747,44639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que le golden retriever ... le chariot dans cet entrepôt pendant des années.'::text,'a conduit'::text,'conduit'::text,'conduisant'::text,'On dit que le golden retriever a conduit le chariot dans cet entrepôt pendant des années.'::text),
(401750,44639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Golden retrieverın yıllardır bu depoda forklift ... söyleniyor.'::text,'kullandığı'::text,'kullanmak'::text,'kullanarak'::text,'Golden retrieverın yıllardır bu depoda forklift kullandığı söyleniyor.'::text),
(401751,44639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a golden retriever évekig ... a targoncát ebben a raktárban.'::text,'vezette'::text,'vezeti'::text,'vezetve'::text,'Azt mondják, a golden retriever évekig vezette a targoncát ebben a raktárban.'::text),
(401754,44640,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Chihuahua warf dem Retriever vor, den ganzen Stapel im Lager ...'::text,'umgeworfen zu haben'::text,'umzuwerfen'::text,'umgeworfen'::text,'Der Chihuahua warf dem Retriever vor, den ganzen Stapel im Lager umgeworfen zu haben.'::text),
(401758,44640,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чихуахуа звинуватив ретривера в тому, що той ... весь штабель на складі.'::text,'перекинув'::text,'перекинути'::text,'перекинутий'::text,'Чихуахуа звинуватив ретривера в тому, що той перекинув весь штабель на складі.'::text),
(401757,44640,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chihuahua acusó al retriever de ... toda la pila del almacén.'::text,'derribar'::text,'derribar'::text,'derribó'::text,'El chihuahua acusó al retriever de derribar toda la pila del almacén.'::text),
(401756,44640,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chihuahua a accusé le retriever ... toute la pile de l''entrepôt.'::text,'d''avoir renversé'::text,'de renverser'::text,'renversé'::text,'Le chihuahua a accusé le retriever d''avoir renversé toute la pile de l''entrepôt.'::text),
(401759,44640,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chihuahua, retrieverı depodaki bütün yığını ... suçladı.'::text,'devirmekle'::text,'devirmek'::text,'devirdi'::text,'Chihuahua, retrieverı depodaki bütün yığını devirmekle suçladı.'::text),
(401760,44640,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csivava azzal vádolta a retrievert, hogy ... az egész rakást a raktárban.'::text,'feldöntötte'::text,'feldönteni'::text,'feldöntött'::text,'A csivava azzal vádolta a retrievert, hogy feldöntötte az egész rakást a raktárban.'::text),
(401763,44641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Retriever hätte den Stapler nicht so nah an den Lagerregalen ...; jetzt ist überall Wasser.'::text,'fahren sollen'::text,'fahren dürfen'::text,'fahren können'::text,'Der Retriever hätte den Stapler nicht so nah an den Lagerregalen fahren sollen; jetzt ist überall Wasser.'::text),
(401767,44641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ретривер ... навантажувачем так близько до стелажів складу; тепер усюди вода.'::text,'не мав би їздити'::text,'не мав права їздити'::text,'не міг їздити'::text,'Ретривер не мав би їздити навантажувачем так близько до стелажів складу; тепер усюди вода.'::text),
(401766,44641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El retriever ... la carretilla tan cerca de las estanterías del almacén; ahora hay agua por todas partes.'::text,'no debería haber conducido'::text,'no debe haber conducido'::text,'no podía conducir'::text,'El retriever no debería haber conducido la carretilla tan cerca de las estanterías del almacén; ahora hay agua por todas partes.'::text),
(401765,44641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le retriever ... le chariot si près des rayonnages de l''entrepôt ; maintenant il y a de l''eau partout.'::text,'n''aurait pas dû conduire'::text,'n''a pas dû conduire'::text,'ne pouvait pas conduire'::text,'Le retriever n''aurait pas dû conduire le chariot si près des rayonnages de l''entrepôt ; maintenant il y a de l''eau partout.'::text),
(401768,44641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Retriever forklifti deponun raflarına bu kadar yakın ...; şimdi her yer su.'::text,'sürmemeliydi'::text,'sürmemiş olmalı'::text,'süremezdi'::text,'Retriever forklifti deponun raflarına bu kadar yakın sürmemeliydi; şimdi her yer su.'::text),
(401769,44641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A retrievernek ... ilyen közel vezetnie a targoncát a raktár polcaihoz; most mindenhol víz van.'::text,'nem kellett volna'::text,'nem szabadott volna'::text,'nem tudott'::text,'A retrievernek nem kellett volna ilyen közel vezetnie a targoncát a raktár polcaihoz; most mindenhol víz van.'::text),
(401772,44642,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In einem Lager wird ... typischerweise auf Paletten gelagert.'::text,'abgefülltes Wasser'::text,'ein abgefülltes Wasser'::text,'die abgefüllten Wasser'::text,'In einem Lager wird abgefülltes Wasser typischerweise auf Paletten gelagert.'::text),
(401776,44642,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На складі ... зазвичай зберігають на палетах.'::text,'бутильовану воду'::text,'бутильовану воду'::text,'бутильовані води'::text,'На складі бутильовану воду зазвичай зберігають на палетах.'::text),
(401775,44642,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En un almacén, ... se almacena normalmente en palés.'::text,'el agua embotellada'::text,'un agua embotellada'::text,'las aguas embotelladas'::text,'En un almacén, el agua embotellada se almacena normalmente en palés.'::text),
(401774,44642,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans un entrepôt, ... est généralement stockée sur des palettes.'::text,'l''eau en bouteille'::text,'une eau en bouteille'::text,'les eaux en bouteille'::text,'Dans un entrepôt, l''eau en bouteille est généralement stockée sur des palettes.'::text),
(401777,44642,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir depoda ... genellikle paletler üzerinde depolanır.'::text,'şişelenmiş su'::text,'bir şişelenmiş su'::text,'şişelenmiş sular'::text,'Bir depoda şişelenmiş su genellikle paletler üzerinde depolanır.'::text),
(401778,44642,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy raktárban ... általában raklapokon tárolják.'::text,'a palackozott vizet'::text,'egy palackozott vizet'::text,'a palackozott vizeket'::text,'Egy raktárban a palackozott vizet általában raklapokon tárolják.'::text),
(389613,43291,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... sie den ganzen Platz im Kleiderschrank ein, sondern sie bedeckte auch den Boden mit Klamotten.'::text,'nahm'::text,'nahm'::text,'nahm'::text,'Nicht nur nahm sie den ganzen Platz im Kleiderschrank ein, sondern sie bedeckte auch den Boden mit Klamotten.'::text),
(389617,43291,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не лише ... все місце в гардеробі, а й завалила підлогу одягом.'::text,'зайняла'::text,'зайняла'::text,'зайняла'::text,'Вона не лише зайняла все місце в гардеробі, а й завалила підлогу одягом.'::text),
(389616,43291,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... todo el espacio del armario, sino que también cubrió el suelo de ropa.'::text,'ocupó'::text,'ocupó'::text,'ocupó'::text,'No solo ocupó todo el espacio del armario, sino que también cubrió el suelo de ropa.'::text),
(389615,43291,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement ... tout l''espace de l''armoire, mais elle a aussi couvert le sol de vêtements.'::text,'a-t-elle pris'::text,'elle a pris'::text,'a pris'::text,'Non seulement a-t-elle pris tout l''espace de l''armoire, mais elle a aussi couvert le sol de vêtements.'::text),
(389618,43291,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolaptaki bütün yeri ... kalmadı, zemini de kıyafetlerle kapladı.'::text,'kaplamakla'::text,'kaplamakla'::text,'kaplamakla'::text,'Dolaptaki bütün yeri kaplamakla kalmadı, zemini de kıyafetlerle kapladı.'::text),
(389619,43291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak ... az összes helyet a gardróbban, hanem a padlót is beterítette ruhákkal.'::text,'elfoglalta'::text,'elfoglalta'::text,'elfoglalta'::text,'Nemcsak elfoglalta az összes helyet a gardróbban, hanem a padlót is beterítette ruhákkal.'::text),
(389622,43292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er lässt sie gleich etwas Platz für seine Jogginghosen ..., ohne Witz.'::text,'freiräumen'::text,'freiräumen'::text,'freigeräumt'::text,'Digga, er lässt sie gleich etwas Platz für seine Jogginghosen freiräumen, ohne Witz.'::text),
(389626,43292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він змусить її ... трохи місця для своїх джогерів, чесне слово.'::text,'звільнити'::text,'звільнити'::text,'звільнене'::text,'Бро, він змусить її звільнити трохи місця для своїх джогерів, чесне слово.'::text),
(389625,43292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, va a hacer que ella ... algo de espacio para sus joggers, en serio.'::text,'libere'::text,'libere'::text,'liberado'::text,'Bro, va a hacer que ella libere algo de espacio para sus joggers, en serio.'::text),
(389624,43292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il va lui faire ... un peu de place pour ses joggings, sans mentir.'::text,'libérer'::text,'libérer'::text,'libéré'::text,'Frérot, il va lui faire libérer un peu de place pour ses joggings, sans mentir.'::text),
(389627,43292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eşofmanları için ona biraz yer ..., yemin ederim.'::text,'açtıracak'::text,'açtıracak'::text,'açılmış'::text,'Kanka, eşofmanları için ona biraz yer açtıracak, yemin ederim.'::text),
(389628,43292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő tuti ... vele egy kis helyet a melegítőinek, komolyan.'::text,'csináltat'::text,'csináltat'::text,'csinált'::text,'Tesó, ő tuti csináltat vele egy kis helyet a melegítőinek, komolyan.'::text),
(389640,43294,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kleiderschrank, ... Platz im Meeting 50/50 aufgeteilt wurde, ist jetzt voll mit ihren Klamotten.'::text,'dessen'::text,'der'::text,'das'::text,'Der Kleiderschrank, dessen Platz im Meeting 50/50 aufgeteilt wurde, ist jetzt voll mit ihren Klamotten.'::text),
(389644,43294,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гардероб, ... простір на нараді поділили 50/50, тепер повний її одягу.'::text,'чий'::text,'який'::text,'що'::text,'Гардероб, чий простір на нараді поділили 50/50, тепер повний її одягу.'::text),
(389643,43294,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El armario, ... espacio se repartió 50/50 en la reunión, ahora está lleno de su ropa.'::text,'cuyo'::text,'el cual'::text,'que'::text,'El armario, cuyo espacio se repartió 50/50 en la reunión, ahora está lleno de su ropa.'::text),
(389642,43294,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''armoire, ... l''espace a été partagé 50/50 en réunion, est maintenant pleine de ses vêtements.'::text,'dont'::text,'laquelle'::text,'que'::text,'L''armoire, dont l''espace a été partagé 50/50 en réunion, est maintenant pleine de ses vêtements.'::text),
(389645,43294,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toplantıda ... alanı 50/50 bölünen gardırop şimdi onun kıyafetleriyle dolu.'::text,''::text,NULL::text,NULL::text,'Toplantıda alanı 50/50 bölünen gardırop şimdi onun kıyafetleriyle dolu.'::text),
(389646,43294,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gardrób, ... helyét a megbeszélésen 50/50 arányban felosztották, most tele van a ruháival.'::text,'amelynek'::text,'amely'::text,'ami'::text,'A gardrób, amelynek helyét a megbeszélésen 50/50 arányban felosztották, most tele van a ruháival.'::text),
(389649,43295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Kleiderschrank ist kaum noch ... für seine Klamotten übrig.'::text,'Platz'::text,'ein Platz'::text,'die Plätze'::text,'Im Kleiderschrank ist kaum noch Platz für seine Klamotten übrig.'::text),
(389653,43295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У гардеробі майже не залишилося ... для його одягу.'::text,'місця'::text,'місця'::text,'місць'::text,'У гардеробі майже не залишилося місця для його одягу.'::text),
(389652,43295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apenas queda ... en el armario para su ropa.'::text,'espacio'::text,'un espacio'::text,'los espacios'::text,'Apenas queda espacio en el armario para su ropa.'::text),
(389651,43295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ne reste presque plus ... dans l''armoire pour ses vêtements.'::text,'de place'::text,'une place'::text,'les places'::text,'Il ne reste presque plus de place dans l''armoire pour ses vêtements.'::text),
(389654,43295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolapta onun kıyafetleri için neredeyse hiç ... kalmadı.'::text,'yer'::text,'bir yer'::text,'yerler'::text,'Dolapta onun kıyafetleri için neredeyse hiç yer kalmadı.'::text),
(389655,43295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alig maradt ... a gardróbban a ruháinak.'::text,'hely'::text,'egy hely'::text,'a helyek'::text,'Alig maradt hely a gardróbban a ruháinak.'::text),
(389658,43296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Ansage, seine Klamotten hierhin zu legen, fand er keinen Platz.'::text,'Trotz'::text,'Obwohl'::text,'Trotz'::text,'Trotz der Ansage, seine Klamotten hierhin zu legen, fand er keinen Platz.'::text),
(389662,43296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... те, що йому сказали покласти сюди свій одяг, він не знайшов жодного місця.'::text,'Попри'::text,'Хоча'::text,'Попри'::text,'Попри те, що йому сказали покласти сюди свій одяг, він не знайшов жодного місця.'::text),
(389661,43296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... que le dijeron que pusiera aquí su ropa, no encontró nada de espacio.'::text,'A pesar de'::text,'Aunque'::text,'A pesar de'::text,'A pesar de que le dijeron que pusiera aquí su ropa, no encontró nada de espacio.'::text),
(389660,43296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la consigne de mettre ses vêtements ici, il n''a trouvé aucune place.'::text,'Malgré'::text,'Bien que'::text,'Malgré'::text,'Malgré la consigne de mettre ses vêtements ici, il n''a trouvé aucune place.'::text),
(389663,43296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıyafetlerini buraya koyması söylenmesine ..., hiç yer bulamadı.'::text,'rağmen'::text,'rağmen'::text,'rağmen'::text,'Kıyafetlerini buraya koyması söylenmesine rağmen, hiç yer bulamadı.'::text),
(389664,43296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hogy azt mondták neki, ide tegye a ruháit, nem talált semmi helyet.'::text,'Annak ellenére,'::text,'Bár'::text,'Annak ellenére,'::text,'Annak ellenére, hogy azt mondták neki, ide tegye a ruháit, nem talált semmi helyet.'::text),
(389667,43297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie eingezogen sind, dachte er, er ... die Hälfte des Platzes im Kleiderschrank.'::text,'bekäme'::text,'bekommt'::text,'bekommt gerade'::text,'Als sie eingezogen sind, dachte er, er bekäme die Hälfte des Platzes im Kleiderschrank.'::text),
(389671,43297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони заїхали, він думав, що ... половину місця в гардеробі.'::text,'отримає'::text,'отримає'::text,'отримує'::text,'Коли вони заїхали, він думав, що отримає половину місця в гардеробі.'::text),
(389670,43297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando se mudaron, pensó que ... la mitad del espacio del armario.'::text,'tendría'::text,'tendrá'::text,'está teniendo'::text,'Cuando se mudaron, pensó que tendría la mitad del espacio del armario.'::text),
(389669,43297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils ont emménagé, il pensait qu''il ... la moitié de la place dans l''armoire.'::text,'aurait'::text,'aura'::text,'a'::text,'Quand ils ont emménagé, il pensait qu''il aurait la moitié de la place dans l''armoire.'::text),
(389672,43297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taşındıklarında dolaptaki yerin yarısını ... düşünmüştü.'::text,'alacağını'::text,'alacağını'::text,'aldığını'::text,'Taşındıklarında dolaptaki yerin yarısını alacağını düşünmüştü.'::text),
(389673,43297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor beköltöztek, azt hitte, hogy ... a gardrób felét.'::text,'megkapja'::text,'meg fogja kapni'::text,'kapja'::text,'Amikor beköltöztek, azt hitte, hogy megkapja a gardrób felét.'::text),
(389676,43298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit sie eingezogen sind, ... ihre Klamotten fast den ganzen Platz im Kleiderschrank ein.'::text,'nehmen'::text,'nehmen'::text,'nehmen gerade'::text,'Seit sie eingezogen sind, nehmen ihre Klamotten fast den ganzen Platz im Kleiderschrank ein.'::text),
(389680,43298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її одяг ... майже все місце в гардеробі відтоді, як вони заїхали.'::text,'займає'::text,'займає'::text,'займає'::text,'Її одяг займає майже все місце в гардеробі відтоді, як вони заїхали.'::text),
(389679,43298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su ropa ... casi todo el espacio del armario desde que se mudaron.'::text,'ha ocupado'::text,'ocupa'::text,'está ocupando'::text,'Su ropa ha ocupado casi todo el espacio del armario desde que se mudaron.'::text),
(389678,43298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses vêtements ... presque toute la place dans l''armoire depuis qu''ils ont emménagé.'::text,'occupent'::text,'occupent'::text,'sont en train d''occuper'::text,'Ses vêtements occupent presque toute la place dans l''armoire depuis qu''ils ont emménagé.'::text),
(389681,43298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Taşındıklarından beri kıyafetleri dolaptaki yerin neredeyse tamamını ...'::text,'kaplıyor'::text,'kaplar'::text,'kaplıyor'::text,'Taşındıklarından beri kıyafetleri dolaptaki yerin neredeyse tamamını kaplıyor.'::text),
(389682,43298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amióta beköltöztek, a ruhái szinte az összes helyet ... a gardróbban.'::text,'elfoglalják'::text,'elfoglalják'::text,'foglalják éppen'::text,'Amióta beköltöztek, a ruhái szinte az összes helyet elfoglalják a gardróbban.'::text),
(389685,43299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er reinkam, ... ihre Klamotten schon jeden Zentimeter Platz eingenommen. Aus und vorbei!'::text,'hatten'::text,'haben'::text,'nehmen'::text,'Als er reinkam, hatten ihre Klamotten schon jeden Zentimeter Platz eingenommen. Aus und vorbei!'::text),
(389689,43299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він зайшов, її одяг ... кожен сантиметр місця. Кінець!'::text,'уже зайняв'::text,'уже зайняв'::text,'уже займає'::text,'Коли він зайшов, її одяг уже зайняв кожен сантиметр місця. Кінець!'::text),
(389688,43299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando entró, su ropa ... cada centímetro de espacio. ¡Fin!'::text,'ya había ocupado'::text,'ya ha ocupado'::text,'ya ocupa'::text,'Para cuando entró, su ropa ya había ocupado cada centímetro de espacio. ¡Fin!'::text),
(389687,43299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il est entré, ses vêtements ... chaque centimètre d''espace. Fin !'::text,'avaient déjà pris'::text,'ont déjà pris'::text,'prennent déjà'::text,'Quand il est entré, ses vêtements avaient déjà pris chaque centimètre d''espace. Fin !'::text),
(389690,43299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O içeri girdiğinde, kıyafetleri her santimi çoktan ...; işte son!'::text,'kaplamıştı'::text,'kapladı'::text,'kaplıyor'::text,'O içeri girdiğinde, kıyafetleri her santimi çoktan kaplamıştı; işte son!'::text),
(389691,43299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire belépett, a ruhái ... minden centiméternyi helyet. Vége!'::text,'már elfoglalták'::text,'már elfoglalták'::text,'már elfoglalják'::text,'Mire belépett, a ruhái már elfoglalták minden centiméternyi helyet. Vége!'::text),
(389694,43300,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis morgen werden ihre Klamotten auch das letzte bisschen Platz ..., und er wird alles verlieren!'::text,'eingenommen haben'::text,'einnehmen'::text,'einnehmen'::text,'Bis morgen werden ihre Klamotten auch das letzte bisschen Platz eingenommen haben, und er wird alles verlieren!'::text),
(389698,43300,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До завтра її одяг ... і останній шматочок місця, і він втратить усе!'::text,'займе'::text,'займе'::text,'займає'::text,'До завтра її одяг займе і останній шматочок місця, і він втратить усе!'::text),
(389697,43300,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para mañana, su ropa ... también el último trocito de espacio y él lo perderá todo!'::text,'habrá ocupado'::text,'ocupará'::text,'ocupa'::text,'¡Para mañana, su ropa habrá ocupado también el último trocito de espacio y él lo perderá todo!'::text),
(389696,43300,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici demain, ses vêtements ... aussi le dernier bout de place, et il va tout perdre !'::text,'auront pris'::text,'prendront'::text,'prennent'::text,'D''ici demain, ses vêtements auront pris aussi le dernier bout de place, et il va tout perdre !'::text),
(389699,43300,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarına kadar kıyafetleri son kalan yeri de ... ve o her şeyini kaybedecek!'::text,'kaplamış olacak'::text,'kaplayacak'::text,'kaplıyor'::text,'Yarına kadar kıyafetleri son kalan yeri de kaplamış olacak ve o her şeyini kaybedecek!'::text),
(389700,43300,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnapra a ruhái az utolsó kis helyet is ..., és ő mindent elveszít!'::text,'elfoglalják'::text,'el fogják foglalni'::text,'elfoglalják'::text,'Holnapra a ruhái az utolsó kis helyet is elfoglalják, és ő mindent elveszít!'::text),
(341823,37981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er ... den Beton, als sein Kumpel noch einen Drink wollte, echt jetzt.'::text,'schrubbte gerade'::text,'schrubbte'::text,'hat geschrubbt'::text,'Digga, er schrubbte gerade den Beton, als sein Kumpel noch einen Drink wollte, echt jetzt.'::text),
(341827,37981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... бетон, коли його кореш попросив ще один напій, реально.'::text,'тер'::text,'потер'::text,'потер'::text,'Бро, він тер бетон, коли його кореш попросив ще один напій, реально.'::text),
(341826,37981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... el hormigón cuando su colega pidió otra bebida, en serio.'::text,'estaba fregando'::text,'fregó'::text,'ha fregado'::text,'Bro, él estaba fregando el hormigón cuando su colega pidió otra bebida, en serio.'::text),
(341825,37981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... le béton quand son pote a demandé un autre verre, sérieux.'::text,'frottait'::text,'a frotté'::text,'a frotté'::text,'Frérot, il frottait le béton quand son pote a demandé un autre verre, sérieux.'::text),
(341828,37981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, arkadaşı bir içecek daha istediğinde o betonu ..., cidden.'::text,'ovalıyordu'::text,'ovaladı'::text,'ovaladı'::text,'Kanka, arkadaşı bir içecek daha istediğinde o betonu ovalıyordu, cidden.'::text),
(341829,37981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a betont, amikor a haverja kért még egy italt, komolyan.'::text,'súrolta'::text,'lesúrolta'::text,'lesúrolta'::text,'Tesó, súrolta a betont, amikor a haverja kért még egy italt, komolyan.'::text),
(341832,37982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... den Beton schon seit einer Stunde, und sein Kumpel hat sich null bewegt.'::text,'schrubbt'::text,'schrubbt gerade'::text,'schrubbt'::text,'Alter, er schrubbt den Beton schon seit einer Stunde, und sein Kumpel hat sich null bewegt.'::text),
(341836,37982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він ... той бетон уже годину, а його кореш і не ворухнувся.'::text,'тре'::text,'тре'::text,'тре'::text,'Чувак, він тре той бетон уже годину, а його кореш і не ворухнувся.'::text),
(341835,37982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... ese hormigón desde hace una hora y su colega ni se ha movido.'::text,'ha estado fregando'::text,'está fregando'::text,'friega'::text,'Tío, él ha estado fregando ese hormigón desde hace una hora y su colega ni se ha movido.'::text),
(341834,37982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... ce béton depuis une heure, et son pote n''a pas bougé.'::text,'frotte'::text,'est en train de frotter'::text,'frotte'::text,'Mec, il frotte ce béton depuis une heure, et son pote n''a pas bougé.'::text),
(341837,37982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir saattir o betonu ... ve arkadaşı kılını bile kıpırdatmadı.'::text,'ovalıyor'::text,'ovalıyor'::text,'ovalar'::text,'Kanka, bir saattir o betonu ovalıyor ve arkadaşı kılını bile kıpırdatmadı.'::text),
(341838,37982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, már egy órája ... azt a betont, a haverja meg meg se mozdult.'::text,'súrolja'::text,'súrolja'::text,'súrolja'::text,'Haver, már egy órája súrolja azt a betont, a haverja meg meg se mozdult.'::text),
(341841,37983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... alle 40 Betonplatten und schickte dann die Rechnung.'::text,'schrubbte'::text,'schrubbte gerade'::text,'hat geschrubbt'::text,'Er schrubbte alle 40 Betonplatten und schickte dann die Rechnung.'::text),
(341845,37983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... всі 40 бетонних плит, а потім надіслав рахунок.'::text,'відтер'::text,'тер'::text,'відтер'::text,'Він відтер всі 40 бетонних плит, а потім надіслав рахунок.'::text),
(341844,37983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... las 40 losas de hormigón y luego envió la factura.'::text,'fregó'::text,'estaba fregando'::text,'ha fregado'::text,'Él fregó las 40 losas de hormigón y luego envió la factura.'::text),
(341843,37983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les 40 dalles de béton, puis il a envoyé la facture.'::text,'a frotté'::text,'frottait'::text,'a frotté'::text,'Il a frotté les 40 dalles de béton, puis il a envoyé la facture.'::text),
(341846,37983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O 40 beton plakanın hepsini ... ve sonra faturayı gönderdi.'::text,'ovaladı'::text,'ovalıyordu'::text,'ovaladı'::text,'O 40 beton plakanın hepsini ovaladı ve sonra faturayı gönderdi.'::text),
(341847,37983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mind a 40 betonlapot ..., aztán elküldte a számlát.'::text,'lesúrolta'::text,'súrolta'::text,'lesúrolta'::text,'Mind a 40 betonlapot lesúrolta, aztán elküldte a számlát.'::text),
(341850,37984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Beton heute zweimal geschrubbt, also ist er doppelt so sauber.'::text,'hat'::text,'hat'::text,'schrubbt'::text,'Er hat den Beton heute zweimal geschrubbt, also ist er doppelt so sauber.'::text),
(341854,37984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сьогодні двічі ... бетон, тож він удвічі чистіший.'::text,'відтер'::text,'тер'::text,'тре'::text,'Він сьогодні двічі відтер бетон, тож він удвічі чистіший.'::text),
(341853,37984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy él ... el hormigón dos veces, así que está el doble de limpio.'::text,'ha fregado'::text,'ha estado fregando'::text,'friega'::text,'Hoy él ha fregado el hormigón dos veces, así que está el doble de limpio.'::text),
(341852,37984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le béton deux fois aujourd''hui, donc il est deux fois plus propre.'::text,'a frotté'::text,'a frotté'::text,'frotte'::text,'Il a frotté le béton deux fois aujourd''hui, donc il est deux fois plus propre.'::text),
(341855,37984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün betonu iki kez ..., yani iki kat temiz.'::text,'ovaladı'::text,'ovalıyor'::text,'ovalar'::text,'Bugün betonu iki kez ovaladı, yani iki kat temiz.'::text),
(341856,37984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma kétszer ... a betont, szóval kétszer olyan tiszta.'::text,'lesúrolta'::text,'súrolta'::text,'súrolja'::text,'Ma kétszer lesúrolta a betont, szóval kétszer olyan tiszta.'::text),
(341859,37985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor das Schrubben begann, ... das Individuum mehrere Teppiche zum Trocknen auf dem Beton ausgelegt.'::text,'hatte'::text,'hat'::text,'legt'::text,'Bevor das Schrubben begann, hatte das Individuum mehrere Teppiche zum Trocknen auf dem Beton ausgelegt.'::text),
(341863,37985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перед початком чищення індивід ... кілька килимів на бетоні сушитися.'::text,'розклав'::text,'розклав'::text,'розкладає'::text,'Перед початком чищення індивід розклав кілька килимів на бетоні сушитися.'::text),
(341862,37985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que empezara el fregado, el individuo ... varias alfombras sobre el hormigón para que se secaran.'::text,'había extendido'::text,'ha extendido'::text,'extiende'::text,'Antes de que empezara el fregado, el individuo había extendido varias alfombras sobre el hormigón para que se secaran.'::text),
(341861,37985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant le début du frottage, l''individu ... plusieurs tapis sur le béton pour les faire sécher.'::text,'avait étendu'::text,'a étendu'::text,'étend'::text,'Avant le début du frottage, l''individu avait étendu plusieurs tapis sur le béton pour les faire sécher.'::text),
(341864,37985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ovalama başlamadan önce birey birkaç halıyı kurusun diye betonun üzerine ...'::text,'sermişti'::text,'serdi'::text,'seriyor'::text,'Ovalama başlamadan önce birey birkaç halıyı kurusun diye betonun üzerine sermişti.'::text),
(341865,37985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a súrolás elkezdődött, az egyed több szőnyeget ... a betonra száradni.'::text,'terített ki'::text,'terített ki'::text,'terít ki'::text,'Mielőtt a súrolás elkezdődött, az egyed több szőnyeget terített ki a betonra száradni.'::text),
(341868,37986,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... den Beton schrubbt, hat den ganzen Tag nichts getrunken.'::text,'der'::text,'was'::text,'dessen'::text,'Der Mann, der den Beton schrubbt, hat den ganzen Tag nichts getrunken.'::text),
(341872,37986,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... тре бетон, за весь день нічого не пив.'::text,'який'::text,'що'::text,'чий'::text,'Чоловік, який тре бетон, за весь день нічого не пив.'::text),
(341871,37986,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... está fregando el hormigón no ha bebido nada en todo el día.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El hombre que está fregando el hormigón no ha bebido nada en todo el día.'::text),
(341870,37986,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... frotte le béton n''a rien bu de la journée.'::text,'qui'::text,'lequel'::text,'dont'::text,'L''homme qui frotte le béton n''a rien bu de la journée.'::text),
(341873,37986,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... betonu ovalayan adam bütün gün hiçbir şey içmedi.'::text,''::text,NULL::text,NULL::text,'Betonu ovalayan adam bütün gün hiçbir şey içmedi.'::text),
(341874,37986,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... a betont súrolja, egész nap nem ivott semmit.'::text,'aki'::text,'ami'::text,'akinek'::text,'A férfi, aki a betont súrolja, egész nap nem ivott semmit.'::text),
(341877,37987,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann auf dem Teppich sagte, er ... den Beton am Vortag geputzt.'::text,'habe'::text,'hat'::text,'putzt'::text,'Der Mann auf dem Teppich sagte, er habe den Beton am Vortag geputzt.'::text),
(341881,37987,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік на килимі сказав, що ... бетон напередодні.'::text,'почистив'::text,'почистив'::text,'чистить'::text,'Чоловік на килимі сказав, що почистив бетон напередодні.'::text),
(341880,37987,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de la alfombra dijo que ... el hormigón el día anterior.'::text,'había limpiado'::text,'ha limpiado'::text,'limpia'::text,'El hombre de la alfombra dijo que había limpiado el hormigón el día anterior.'::text),
(341879,37987,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme sur le tapis a dit qu''il ... le béton la veille.'::text,'avait nettoyé'::text,'a nettoyé'::text,'nettoie'::text,'L''homme sur le tapis a dit qu''il avait nettoyé le béton la veille.'::text),
(341882,37987,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Halının üzerindeki adam, betonu bir gün önce ... söyledi.'::text,'temizlediğini'::text,'temizlediğini'::text,'temizlediğini'::text,'Halının üzerindeki adam, betonu bir gün önce temizlediğini söyledi.'::text),
(341883,37987,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szőnyegen fekvő férfi azt mondta, hogy előző nap ... a betont.'::text,'megtisztította'::text,'megtisztította'::text,'tisztítja'::text,'A szőnyegen fekvő férfi azt mondta, hogy előző nap megtisztította a betont.'::text),
(341895,37989,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, es macht dir nichts aus, die ganze Betonterrasse allein zu ...'::text,'schrubben'::text,'schrubben'::text,'schrubben'::text,'Ehrlich, es macht dir nichts aus, die ganze Betonterrasse allein zu schrubben.'::text),
(341899,37989,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти не проти сам ... всю цю бетонну терасу.'::text,'відтерти'::text,'відтерти'::text,'відтерти'::text,'Чесно, ти не проти сам відтерти всю цю бетонну терасу.'::text),
(341898,37989,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, no te importa ... tú solo todo ese patio de hormigón.'::text,'fregar'::text,'fregar'::text,'friegas'::text,'Sinceramente, no te importa fregar tú solo todo ese patio de hormigón.'::text),
(341897,37989,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ça ne te dérange pas de ... toute cette terrasse en béton tout seul.'::text,'frotter'::text,'frotter'::text,'frottes'::text,'Franchement, ça ne te dérange pas de frotter toute cette terrasse en béton tout seul.'::text),
(341900,37989,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o koca beton terası tek başına ... dert etmiyorsun.'::text,'ovalamayı'::text,'ovalamayı'::text,'ovala'::text,'Açıkçası o koca beton terası tek başına ovalamayı dert etmiyorsun.'::text),
(341901,37989,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, nem zavar, hogy egyedül ... az egész betonteraszt.'::text,'súrolod'::text,'súrolni'::text,'súrold'::text,'Őszintén, nem zavar, hogy egyedül súrolod az egész betonteraszt.'::text),
(341913,37991,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... eine Stunde auf dem Teppich, bevor er den nassen Beton bemerkte. Wirklich hilfreich.'::text,'lag schon'::text,'liegt schon'::text,'lag'::text,'Der Mann lag schon eine Stunde auf dem Teppich, bevor er den nassen Beton bemerkte. Wirklich hilfreich.'::text),
(341917,37991,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... на килимі годину, перш ніж помітив мокрий бетон. Справді корисний.'::text,'лежав'::text,'лежить'::text,'лежав'::text,'Чоловік лежав на килимі годину, перш ніж помітив мокрий бетон. Справді корисний.'::text),
(341916,37991,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... en la alfombra una hora antes de notar el hormigón mojado. Muy útil, de verdad.'::text,'había estado tumbado'::text,'ha estado tumbado'::text,'estaba tumbado'::text,'El hombre había estado tumbado en la alfombra una hora antes de notar el hormigón mojado. Muy útil, de verdad.'::text),
(341915,37991,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... sur le tapis depuis une heure quand il a remarqué le béton mouillé. Vraiment serviable.'::text,'était allongé'::text,'est allongé'::text,'était allongé'::text,'L''homme était allongé sur le tapis depuis une heure quand il a remarqué le béton mouillé. Vraiment serviable.'::text),
(341918,37991,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, ıslak betonu fark etmeden önce halının üzerinde bir saat ...; gerçekten çok yardımsever.'::text,'yatmıştı'::text,'yatıyor'::text,'yatıyordu'::text,'Adam, ıslak betonu fark etmeden önce halının üzerinde bir saat yatmıştı; gerçekten çok yardımsever.'::text),
(341919,37991,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi egy órán át ... a szőnyegen, mielőtt észrevette a nedves betont. Igazán segítőkész.'::text,'feküdt'::text,'fekszik'::text,'feküdt'::text,'A férfi egy órán át feküdt a szőnyegen, mielőtt észrevette a nedves betont. Igazán segítőkész.'::text),
(343425,38159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um 18 Uhr ... die Katze am Tresen Kundenbestellungen entgegen.'::text,'nimmt gerade'::text,'nimmt'::text,'nimmt'::text,'Morgen um 18 Uhr nimmt gerade die Katze am Tresen Kundenbestellungen entgegen.'::text),
(343429,38159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о 18:00 кіт ... замовлення клієнтів біля прилавка.'::text,'прийматиме'::text,'прийме'::text,'приймає'::text,'Завтра о 18:00 кіт прийматиме замовлення клієнтів біля прилавка.'::text),
(343428,38159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las 18:00, el gato ... pedidos de clientes en el mostrador.'::text,'estará tomando'::text,'tomará'::text,'toma'::text,'Mañana a las 18:00, el gato estará tomando pedidos de clientes en el mostrador.'::text),
(343427,38159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à 18 h, le chat ... les commandes des clients au comptoir.'::text,'sera en train de prendre'::text,'prendra'::text,'prend'::text,'Demain à 18 h, le chat sera en train de prendre les commandes des clients au comptoir.'::text),
(343430,38159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın saat 18.00''de kedi tezgâhta müşteri siparişlerini ...'::text,'alıyor olacak'::text,'alacak'::text,'alıyor'::text,'Yarın saat 18.00''de kedi tezgâhta müşteri siparişlerini alıyor olacak.'::text),
(343431,38159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap 18 órakor a macska ... a vendégek rendeléseit a pultnál.'::text,'épp veszi fel'::text,'fel fogja venni'::text,'felveszi'::text,'Holnap 18 órakor a macska épp veszi fel a vendégek rendeléseit a pultnál.'::text),
(343443,38161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Taube auf dem Tresen steht, ... die Katze wütend!'::text,'wird'::text,'wurde'::text,'wird'::text,'Wenn eine Taube auf dem Tresen steht, wird die Katze wütend!'::text),
(343447,38161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо голуб стоїть на прилавку, кіт ... в лють!'::text,'впадає'::text,'впав'::text,'впаде'::text,'Якщо голуб стоїть на прилавку, кіт впадає в лють!'::text),
(343446,38161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si una paloma se sube al mostrador, el gato se ... furioso!'::text,'pone'::text,'puso'::text,'pondrá'::text,'¡Si una paloma se sube al mostrador, el gato se pone furioso!'::text),
(343445,38161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un pigeon se pose sur le comptoir, le chat ... furieux !'::text,'devient'::text,'est devenu'::text,'deviendra'::text,'Si un pigeon se pose sur le comptoir, le chat devient furieux !'::text),
(343448,38161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir güvercin tezgâhta durursa kedi öfkeden ...!'::text,'çıldırır'::text,'çıldırdı'::text,'çıldıracak'::text,'Bir güvercin tezgâhta durursa kedi öfkeden çıldırır!'::text),
(343449,38161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy galamb a pulton áll, a macska ...!'::text,'dühbe gurul'::text,'dühbe gurult'::text,'dühbe fog gurulni'::text,'Ha egy galamb a pulton áll, a macska dühbe gurul!'::text),
(343452,38162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Taube am Tresen weiterstreitet, ... die Katze sie, zu gehen.'::text,'bittet'::text,'würde bitten'::text,'bat'::text,'Wenn die Taube am Tresen weiterstreitet, bittet die Katze sie, zu gehen.'::text),
(343456,38162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо голуб і далі сперечатиметься біля прилавка, кіт ... його піти.'::text,'попросить'::text,'попросив би'::text,'попросив'::text,'Якщо голуб і далі сперечатиметься біля прилавка, кіт попросить його піти.'::text),
(343455,38162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la paloma sigue discutiendo en el mostrador, el gato le ... que se vaya.'::text,'pedirá'::text,'pediría'::text,'pidió'::text,'Si la paloma sigue discutiendo en el mostrador, el gato le pedirá que se vaya.'::text),
(343454,38162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le pigeon continue de se disputer au comptoir, le chat lui ... de partir.'::text,'demandera'::text,'demanderait'::text,'a demandé'::text,'Si le pigeon continue de se disputer au comptoir, le chat lui demandera de partir.'::text),
(343457,38162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güvercin tezgâhta tartışmaya devam ederse kedi ondan gitmesini ...'::text,'isteyecek'::text,'isterdi'::text,'istedi'::text,'Güvercin tezgâhta tartışmaya devam ederse kedi ondan gitmesini isteyecek.'::text),
(343458,38162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a galamb tovább vitatkozik a pultnál, a macska ... tőle, hogy menjen el.'::text,'kérni fogja'::text,'kérné'::text,'kérte'::text,'Ha a galamb tovább vitatkozik a pultnál, a macska kérni fogja tőle, hogy menjen el.'::text),
(343461,38163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Laden Hafermilch verkaufen würde, ... die Taube am Tresen nicht streiten.'::text,'würde'::text,'wird'::text,'hat'::text,'Wenn der Laden Hafermilch verkaufen würde, würde die Taube am Tresen nicht streiten.'::text),
(343465,38163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби заклад продавав вівсяне молоко, голуб ... біля прилавка.'::text,'не сперечався б'::text,'не сперечатиметься'::text,'не сперечався'::text,'Якби заклад продавав вівсяне молоко, голуб не сперечався б біля прилавка.'::text),
(343464,38163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la tienda vendiera leche de avena, la paloma ... en el mostrador.'::text,'no discutiría'::text,'no discutirá'::text,'no discutió'::text,'Si la tienda vendiera leche de avena, la paloma no discutiría en el mostrador.'::text),
(343463,38163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la boutique vendait du lait d''avoine, le pigeon ... au comptoir.'::text,'ne se disputerait pas'::text,'ne se disputera pas'::text,'ne s''est pas disputé'::text,'Si la boutique vendait du lait d''avoine, le pigeon ne se disputerait pas au comptoir.'::text),
(343466,38163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dükkân yulaf sütü satsaydı güvercin tezgâhta ...'::text,'tartışmazdı'::text,'tartışmayacak'::text,'tartışmadı'::text,'Dükkân yulaf sütü satsaydı güvercin tezgâhta tartışmazdı.'::text),
(343467,38163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a bolt árulna zabtejet, a galamb ... a pultnál.'::text,'nem vitatkozna'::text,'nem fog vitatkozni'::text,'nem vitatkozott'::text,'Ha a bolt árulna zabtejet, a galamb nem vitatkozna a pultnál.'::text),
(343470,38164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Abend ... das Brathähnchen von der mürrischen Katze über den Tresen verkauft.'::text,'wird'::text,'verkauft'::text,'verkauft gerade'::text,'Jeden Abend wird das Brathähnchen von der mürrischen Katze über den Tresen verkauft.'::text),
(343474,38164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щовечора смажену курку ... через прилавок похмурий кіт.'::text,'продає'::text,'продає'::text,'продає'::text,'Щовечора смажену курку продає через прилавок похмурий кіт.'::text),
(343473,38164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada noche, el pollo frito ... en el mostrador por el gato gruñón.'::text,'es vendido'::text,'vende'::text,'está vendiendo'::text,'Cada noche, el pollo frito es vendido en el mostrador por el gato gruñón.'::text),
(343472,38164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque soir, le poulet frit ... au comptoir par le chat grincheux.'::text,'est vendu'::text,'vend'::text,'est en train de vendre'::text,'Chaque soir, le poulet frit est vendu au comptoir par le chat grincheux.'::text),
(343475,38164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her akşam kızarmış tavuk huysuz kedi tarafından tezgâhın üzerinden ...'::text,'satılır'::text,'satar'::text,'satıyor'::text,'Her akşam kızarmış tavuk huysuz kedi tarafından tezgâhın üzerinden satılır.'::text),
(343476,38164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden este a rántott csirkét a morcos macska ... a pulton át.'::text,'árulja'::text,'árulja'::text,'árulja'::text,'Minden este a rántott csirkét a morcos macska árulja a pulton át.'::text),
(343479,38165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, anscheinend ... die Taube einen Iced Latte an einer Brathähnchen-Theke.'::text,'bestellte'::text,'wurde bestellt'::text,'bestellend'::text,'Omg, anscheinend bestellte die Taube einen Iced Latte an einer Brathähnchen-Theke.'::text),
(343483,38165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, кажуть, голуб ... айс-лате біля прилавка зі смаженою куркою.'::text,'замовив'::text,'був замовлений'::text,'замовляючи'::text,'Боже, кажуть, голуб замовив айс-лате біля прилавка зі смаженою куркою.'::text),
(343482,38165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios mío, al parecer la paloma ... un latte helado en un mostrador de pollo frito.'::text,'pidió'::text,'fue pedida'::text,'pidiendo'::text,'Dios mío, al parecer la paloma pidió un latte helado en un mostrador de pollo frito.'::text),
(343481,38165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, apparemment le pigeon ... un latte glacé à un comptoir de poulet frit.'::text,'a commandé'::text,'a été commandé'::text,'commandant'::text,'Omg, apparemment le pigeon a commandé un latte glacé à un comptoir de poulet frit.'::text),
(343484,38165,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, güya güvercin kızarmış tavuk tezgâhında buzlu latte ...'::text,'sipariş etmiş'::text,'sipariş edilmiş'::text,'sipariş ederek'::text,'Aman tanrım, güya güvercin kızarmış tavuk tezgâhında buzlu latte sipariş etmiş.'::text),
(343485,38165,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, állítólag a galamb ... egy jeges lattét egy rántott csirkés pultnál.'::text,'rendelt'::text,'rendelve lett'::text,'rendelve'::text,'Úristen, állítólag a galamb rendelt egy jeges lattét egy rántott csirkés pultnál.'::text),
(343488,38166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Taube ... diesen Tresen gut kennen; sie hat Hafermilch bestellt. Eindeutig Stammkundin.'::text,'kann nicht'::text,'muss'::text,'darf nicht'::text,'Die Taube kann nicht diesen Tresen gut kennen; sie hat Hafermilch bestellt. Eindeutig Stammkundin.'::text),
(343492,38166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Голуб ... добре знати цей прилавок; він замовив вівсяне молоко. Явно постійний клієнт.'::text,'не може'::text,'мусить'::text,'не повинен'::text,'Голуб не може добре знати цей прилавок; він замовив вівсяне молоко. Явно постійний клієнт.'::text),
(343491,38166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La paloma ... conocer bien este mostrador; pidió leche de avena. Clarísimamente clienta fiel.'::text,'no puede'::text,'debe de'::text,'no debe'::text,'La paloma no puede conocer bien este mostrador; pidió leche de avena. Clarísimamente clienta fiel.'::text),
(343490,38166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pigeon ... bien connaître ce comptoir ; il a commandé du lait d''avoine. Clairement un client fidèle.'::text,'ne peut pas'::text,'doit'::text,'ne doit pas'::text,'Le pigeon ne peut pas bien connaître ce comptoir ; il a commandé du lait d''avoine. Clairement un client fidèle.'::text),
(343493,38166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güvercin bu tezgâhı iyi ...; yulaf sütü sipariş etti. Belli ki sadık bir müşteri.'::text,'tanıyor olamaz'::text,'tanıyor olmalı'::text,'tanımamalı'::text,'Güvercin bu tezgâhı iyi tanıyor olamaz; yulaf sütü sipariş etti. Belli ki sadık bir müşteri.'::text),
(343494,38166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A galamb ... ezt a pultot; zabtejet rendelt. Egyértelműen hűséges vendég.'::text,'nem ismerheti jól'::text,'biztos jól ismeri'::text,'nem szabad jól ismernie'::text,'A galamb nem ismerheti jól ezt a pultot; zabtejet rendelt. Egyértelműen hűséges vendég.'::text),
(343497,38167,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Tresen, ... die Fritteuse eingebaut ist, ist natürlich der perfekte Platz zum Stehen.'::text,'in den'::text,'der'::text,'wo'::text,'Der Tresen, in den die Fritteuse eingebaut ist, ist natürlich der perfekte Platz zum Stehen.'::text),
(343501,38167,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прилавок, ... вбудована фритюрниця, звісно, ідеальне місце, щоб стояти.'::text,'у який'::text,'хто'::text,'де'::text,'Прилавок, у який вбудована фритюрниця, звісно, ідеальне місце, щоб стояти.'::text),
(343500,38167,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mostrador, ... está empotrada la freidora, es obviamente el lugar perfecto para quedarse de pie.'::text,'en el que'::text,'quien'::text,'donde'::text,'El mostrador, en el que está empotrada la freidora, es obviamente el lugar perfecto para quedarse de pie.'::text),
(343499,38167,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le comptoir, ... la friteuse est encastrée, est évidemment l''endroit parfait pour se tenir debout.'::text,'dans lequel'::text,'qui'::text,'où'::text,'Le comptoir, dans lequel la friteuse est encastrée, est évidemment l''endroit parfait pour se tenir debout.'::text),
(343502,38167,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fritözün içine yerleştirildiği tezgâh, belli ki durmak için mükemmel yer.'::text,''::text,NULL::text,NULL::text,'Fritözün içine yerleştirildiği tezgâh, belli ki durmak için mükemmel yer.'::text),
(343503,38167,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pult, ... a fritőz be van építve, nyilvánvalóan a tökéletes hely az álldogáláshoz.'::text,'amelybe'::text,'aki'::text,'ahol'::text,'A pult, amelybe a fritőz be van építve, nyilvánvalóan a tökéletes hely az álldogáláshoz.'::text),
(343506,38168,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Taube meinte, sie ... am Tresen zweimal nach Hafermilch gefragt, echt jetzt.'::text,'habe'::text,'hat'::text,'fragt'::text,'Digga, die Taube meinte, sie habe am Tresen zweimal nach Hafermilch gefragt, echt jetzt.'::text),
(343510,38168,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, голуб сказав, що двічі ... вівсяне молоко біля прилавка, реально.'::text,'просив'::text,'просив'::text,'просить'::text,'Бро, голуб сказав, що двічі просив вівсяне молоко біля прилавка, реально.'::text),
(343509,38168,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la paloma dijo que ... leche de avena dos veces en el mostrador, en serio.'::text,'había pedido'::text,'ha pedido'::text,'pide'::text,'Bro, la paloma dijo que había pedido leche de avena dos veces en el mostrador, en serio.'::text),
(343508,38168,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le pigeon a dit qu''il ... du lait d''avoine deux fois au comptoir, sérieux.'::text,'avait demandé'::text,'a demandé'::text,'demande'::text,'Frérot, le pigeon a dit qu''il avait demandé du lait d''avoine deux fois au comptoir, sérieux.'::text),
(343511,38168,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güvercin tezgâhta iki kez yulaf sütü ... söyledi, cidden.'::text,'istediğini'::text,'istediğini'::text,'istediğini'::text,'Kanka, güvercin tezgâhta iki kez yulaf sütü istediğini söyledi, cidden.'::text),
(343512,38168,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a galamb azt mondta, hogy kétszer is ... zabtejet a pultnál, komolyan.'::text,'kért'::text,'kért'::text,'kér'::text,'Tesó, a galamb azt mondta, hogy kétszer is kért zabtejet a pultnál, komolyan.'::text),
(343515,38169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Digga, dieser Tresen ... eine Kaffee-Bar, deswegen ist die Taube verwirrt.'::text,'war früher'::text,'wäre'::text,'ist gewohnt'::text,'Nee Digga, dieser Tresen war früher eine Kaffee-Bar, deswegen ist die Taube verwirrt.'::text),
(343519,38169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, цей прилавок ... кавовим баром, тому голуб і розгублений.'::text,'раніше був'::text,'був би'::text,'звик бути'::text,'Не, бро, цей прилавок раніше був кавовим баром, тому голуб і розгублений.'::text),
(343518,38169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah bro, este mostrador ... ser un bar de café, por eso la paloma está confundida.'::text,'solía'::text,'solía'::text,'está acostumbrado a'::text,'Nah bro, este mostrador solía ser un bar de café, por eso la paloma está confundida.'::text),
(343517,38169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, ce comptoir ... un bar à café, c''est pour ça que le pigeon est perdu.'::text,'était avant'::text,'serait'::text,'a l''habitude d''être'::text,'Nan frérot, ce comptoir était avant un bar à café, c''est pour ça que le pigeon est perdu.'::text),
(343520,38169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bu tezgâh ... bir kahve barıydı, o yüzden güvercinin kafası karışık.'::text,'eskiden'::text,'eskiden'::text,'alışkın'::text,'Yok kanka, bu tezgâh eskiden bir kahve barıydı, o yüzden güvercinin kafası karışık.'::text),
(343521,38169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, ez a pult ..., ezért zavarodott össze a galamb.'::text,'régen kávébár volt'::text,'régen kávébár volt'::text,'hozzá van szokva, hogy kávébár legyen'::text,'Nem, tesó, ez a pult régen kávébár volt, ezért zavarodott össze a galamb.'::text),
(384033,42671,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise ... die Hand die Brust des Kängurus nun schon seit mehreren Minuten.'::text,'kratzt'::text,'kratzt gerade'::text,'kratzt'::text,'Bemerkenswerterweise kratzt die Hand die Brust des Kängurus nun schon seit mehreren Minuten.'::text),
(384037,42671,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивовижно, але рука ... груди кенгуру вже кілька хвилин.'::text,'чеше'::text,'чеше'::text,'чеше'::text,'Дивовижно, але рука чеше груди кенгуру вже кілька хвилин.'::text),
(384036,42671,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sorprendentemente, la mano ... el pecho del canguro desde hace varios minutos.'::text,'ha estado rascando'::text,'está rascando'::text,'rasca'::text,'Sorprendentemente, la mano ha estado rascando el pecho del canguro desde hace varios minutos.'::text),
(384035,42671,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, la main ... la poitrine du kangourou depuis plusieurs minutes.'::text,'gratte'::text,'est en train de gratter'::text,'gratte'::text,'Fait remarquable, la main gratte la poitrine du kangourou depuis plusieurs minutes.'::text),
(384038,42671,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde el, birkaç dakikadır kangurunun göğsünü ...'::text,'kaşıyor'::text,'kaşıyor'::text,'kaşır'::text,'Dikkat çekici biçimde el, birkaç dakikadır kangurunun göğsünü kaşıyor.'::text),
(384039,42671,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó módon a kéz már percek óta ... a kenguru mellkasát.'::text,'vakarja'::text,'vakarja'::text,'vakarja'::text,'Figyelemre méltó módon a kéz már percek óta vakarja a kenguru mellkasát.'::text),
(384042,42672,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Hand seinen Hals ..., legte sich das Känguru langsam ins Gras.'::text,'kratzte'::text,'kratzte'::text,'gekratzt hat'::text,'Während die Hand seinen Hals kratzte, legte sich das Känguru langsam ins Gras.'::text),
(384046,42672,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки рука ... йому шию, кенгуру повільно ліг на траву.'::text,'чесала'::text,'почесала'::text,'почесала'::text,'Поки рука чесала йому шию, кенгуру повільно ліг на траву.'::text),
(384045,42672,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras la mano le ... el cuello, el canguro se tumbó despacio en la hierba.'::text,'estaba rascando'::text,'rascó'::text,'ha rascado'::text,'Mientras la mano le estaba rascando el cuello, el canguro se tumbó despacio en la hierba.'::text),
(384044,42672,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que la main lui ... le cou, le kangourou s''est lentement allongé dans l''herbe.'::text,'grattait'::text,'a gratté'::text,'a gratté'::text,'Pendant que la main lui grattait le cou, le kangourou s''est lentement allongé dans l''herbe.'::text),
(384047,42672,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El boynunu ..., kanguru yavaşça çimenlere uzandı.'::text,'kaşırken'::text,'kaşıdığında'::text,'kaşımışken'::text,'El boynunu kaşırken, kanguru yavaşça çimenlere uzandı.'::text),
(384048,42672,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a kéz ... a nyakát, a kenguru lassan lefeküdt a fűbe.'::text,'vakarta'::text,'megvakarta'::text,'megvakarta'::text,'Miközben a kéz vakarta a nyakát, a kenguru lassan lefeküdt a fűbe.'::text),
(384060,42674,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sich das Känguru hinlegte, ... die Hand schon eine Weile seine Brust und seinen Hals gekratzt.'::text,'hatte'::text,'hat'::text,'kratzt'::text,'Als sich das Känguru hinlegte, hatte die Hand schon eine Weile seine Brust und seinen Hals gekratzt.'::text),
(384064,42674,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли кенгуру ліг, рука вже якийсь час ... йому груди й шию.'::text,'чесала'::text,'чесала'::text,'чеше'::text,'Коли кенгуру ліг, рука вже якийсь час чесала йому груди й шию.'::text),
(384063,42674,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el canguro se tumbó, la mano ya le ... el pecho y el cuello un buen rato.'::text,'había rascado'::text,'ha rascado'::text,'rasca'::text,'Para cuando el canguro se tumbó, la mano ya le había rascado el pecho y el cuello un buen rato.'::text),
(384062,42674,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le kangourou s''est allongé, la main lui ... la poitrine et le cou depuis un moment.'::text,'avait gratté'::text,'a gratté'::text,'gratte'::text,'Quand le kangourou s''est allongé, la main lui avait gratté la poitrine et le cou depuis un moment.'::text),
(384065,42674,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanguru uzandığında el bir süredir göğsünü ve boynunu ...'::text,'kaşımıştı'::text,'kaşıdı'::text,'kaşıyor'::text,'Kanguru uzandığında el bir süredir göğsünü ve boynunu kaşımıştı.'::text),
(384066,42674,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kenguru lefeküdt, a kéz már egy ideje ... a mellkasát és a nyakát.'::text,'vakarta'::text,'vakarta'::text,'vakarja'::text,'Mire a kenguru lefeküdt, a kéz már egy ideje vakarta a mellkasát és a nyakát.'::text),
(384069,42675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Echt Elite-Security, klar: Wenn jemand die Brust dieses Kängurus ..., schläft es ein.'::text,'kratzt'::text,'kratzen wird'::text,'kratzte'::text,'Echt Elite-Security, klar: Wenn jemand die Brust dieses Kängurus kratzt, schläft es ein.'::text),
(384073,42675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справді елітна охорона, звісно: якщо хтось ... цьому кенгуру груди, він засинає.'::text,'почухає'::text,'почухає'::text,'почухав'::text,'Справді елітна охорона, звісно: якщо хтось почухає цьому кенгуру груди, він засинає.'::text),
(384072,42675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seguridad de élite, obviamente: si alguien le ... el pecho a este canguro, se queda dormido.'::text,'rasca'::text,'rascará'::text,'rascó'::text,'Seguridad de élite, obviamente: si alguien le rasca el pecho a este canguro, se queda dormido.'::text),
(384071,42675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sécurité d''élite, évidemment : si quelqu''un ... la poitrine de ce kangourou, il s''endort.'::text,'gratte'::text,'grattera'::text,'a gratté'::text,'Sécurité d''élite, évidemment : si quelqu''un gratte la poitrine de ce kangourou, il s''endort.'::text),
(384074,42675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir elit güvenlik, belli: biri bu kangurunun göğsünü ... uyuyakalıyor.'::text,'kaşırsa'::text,'kaşıyacak olursa'::text,'kaşıdıysa'::text,'Tam bir elit güvenlik, belli: biri bu kangurunun göğsünü kaşırsa uyuyakalıyor.'::text),
(384075,42675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi elit biztonsági őr, nyilván: ha valaki ... ennek a kengurunak a mellkasát, elalszik.'::text,'megvakarja'::text,'meg fogja vakarni'::text,'megvakarta'::text,'Igazi elit biztonsági őr, nyilván: ha valaki megvakarja ennek a kengurunak a mellkasát, elalszik.'::text),
(384078,42676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn mir jemand so den Nacken ..., würde ich mich auch ins Gras legen, ohne Witz.'::text,'kratzte'::text,'kratzt'::text,'kratzen würde'::text,'Yo, wenn mir jemand so den Nacken kratzte, würde ich mich auch ins Gras legen, ohne Witz.'::text),
(384082,42676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, якби мені хтось так ... шию, я б теж ліг на траву, чесне слово.'::text,'почухав'::text,'почухає'::text,'почухав би'::text,'Йо, якби мені хтось так почухав шию, я б теж ліг на траву, чесне слово.'::text),
(384081,42676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, si alguien me ... el cuello así, yo también me tumbaría en la hierba, en serio.'::text,'rascara'::text,'rasca'::text,'rascaría'::text,'Oye, si alguien me rascara el cuello así, yo también me tumbaría en la hierba, en serio.'::text),
(384080,42676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si quelqu''un me ... le cou comme ça, je m''allongerais dans l''herbe aussi, sans mentir.'::text,'grattait'::text,'gratte'::text,'gratterait'::text,'Yo, si quelqu''un me grattait le cou comme ça, je m''allongerais dans l''herbe aussi, sans mentir.'::text),
(384083,42676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, biri boynumu öyle ... ben de çimlere uzanırdım, yemin ederim.'::text,'kaşısa'::text,'kaşırsa'::text,'kaşırdı'::text,'Yo, biri boynumu öyle kaşısa ben de çimlere uzanırdım, yemin ederim.'::text),
(384084,42676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ha valaki így ... a nyakamat, én is lefeküdnék a fűbe, komolyan.'::text,'vakarná'::text,'vakarja'::text,'vakarná'::text,'Figyu, ha valaki így vakarná a nyakamat, én is lefeküdnék a fűbe, komolyan.'::text),
(384087,42677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Brust des Kängurus ... sanft von einer Hand gekratzt, bevor es sich hinlegte.'::text,'wurde'::text,'kratzte'::text,'wird'::text,'Die Brust des Kängurus wurde sanft von einer Hand gekratzt, bevor es sich hinlegte.'::text),
(384091,42677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кенгуру ніжно ... груди рукою, перш ніж він ліг.'::text,'почухали'::text,'почухав'::text,'чешуть'::text,'Кенгуру ніжно почухали груди рукою, перш ніж він ліг.'::text),
(384090,42677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pecho del canguro ... suavemente por una mano antes de que se tumbara.'::text,'fue rascado'::text,'rascó'::text,'es rascado'::text,'El pecho del canguro fue rascado suavemente por una mano antes de que se tumbara.'::text),
(384089,42677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La poitrine du kangourou ... doucement par une main avant qu''il ne s''allonge.'::text,'a été grattée'::text,'a gratté'::text,'est grattée'::text,'La poitrine du kangourou a été grattée doucement par une main avant qu''il ne s''allonge.'::text),
(384092,42677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kangurunun göğsü, uzanmadan önce bir el tarafından nazikçe ...'::text,'kaşındı'::text,'kaşıdı'::text,'kaşınıyor'::text,'Kangurunun göğsü, uzanmadan önce bir el tarafından nazikçe kaşındı.'::text),
(384093,42677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kenguru mellkasát egy kéz gyengéden ..., mielőtt lefeküdt.'::text,'megvakarta'::text,'megvakarta'::text,'vakarja'::text,'A kenguru mellkasát egy kéz gyengéden megvakarta, mielőtt lefeküdt.'::text),
(384096,42678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Besucherin ... dem Känguru 10 Minuten lang den Hals, laut Agenda.'::text,'kratzte'::text,'wurde gekratzt'::text,'kratzend'::text,'Die Besucherin kratzte dem Känguru 10 Minuten lang den Hals, laut Agenda.'::text),
(384100,42678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відвідувачка ... кенгуру шию 10 хвилин, згідно з планом.'::text,'чесала'::text,'була почухана'::text,'чешучи'::text,'Відвідувачка чесала кенгуру шию 10 хвилин, згідно з планом.'::text),
(384099,42678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La visitante le ... el cuello al canguro durante 10 minutos, según la agenda.'::text,'rascó'::text,'fue rascada'::text,'rascando'::text,'La visitante le rascó el cuello al canguro durante 10 minutos, según la agenda.'::text),
(384098,42678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La visiteuse ... le cou du kangourou pendant 10 minutes, conformément à l''agenda.'::text,'a gratté'::text,'a été grattée'::text,'grattant'::text,'La visiteuse a gratté le cou du kangourou pendant 10 minutes, conformément à l''agenda.'::text),
(384101,42678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaretçi, programa uygun olarak kangurunun boynunu 10 dakika boyunca ...'::text,'kaşıdı'::text,'kaşındı'::text,'kaşıyarak'::text,'Ziyaretçi, programa uygun olarak kangurunun boynunu 10 dakika boyunca kaşıdı.'::text),
(384102,42678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogató 10 percig ... a kenguru nyakát, a napirend szerint.'::text,'vakarta'::text,'vakarva lett'::text,'vakarva'::text,'A látogató 10 percig vakarta a kenguru nyakát, a napirend szerint.'::text),
(384105,42679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es klappt in der Sekunde zusammen, in der man es kratzt! Das ... sich absolut unglaublich anfühlen!'::text,'muss'::text,'könnte'::text,'sollte'::text,'Es klappt in der Sekunde zusammen, in der man es kratzt! Das muss sich absolut unglaublich anfühlen!'::text),
(384109,42679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він падає тієї ж секунди, як його чешуть! Це ... абсолютно неймовірне відчуття!'::text,'мабуть'::text,'може'::text,'має бути'::text,'Він падає тієї ж секунди, як його чешуть! Це мабуть абсолютно неймовірне відчуття!'::text),
(384108,42679,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se desploma en cuanto lo rascan! ¡Eso ... sentirse absolutamente increíble!'::text,'debe de'::text,'podría'::text,'debería'::text,'¡Se desploma en cuanto lo rascan! ¡Eso debe de sentirse absolutamente increíble!'::text),
(384107,42679,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il s''effondre dès qu''on le gratte ! Ça ... être absolument incroyable !'::text,'doit'::text,'pourrait'::text,'devrait'::text,'Il s''effondre dès qu''on le gratte ! Ça doit être absolument incroyable !'::text),
(384110,42679,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaşıdıkları anda yığılıyor! Bu kesinlikle inanılmaz bir his ...!'::text,'olmalı'::text,'olabilir'::text,'olması gerek'::text,'Kaşıdıkları anda yığılıyor! Bu kesinlikle inanılmaz bir his olmalı!'::text),
(384111,42679,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abban a pillanatban összecsuklik, ahogy megvakarják! Ez ... hihetetlen érzés lehet!'::text,'biztosan'::text,'talán'::text,'elvileg'::text,'Abban a pillanatban összecsuklik, ahogy megvakarják! Ez biztosan hihetetlen érzés lehet!'::text),
(384114,42680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hand, ... ihm den Hals kratzt, hat den Willen dieses Kängurus zu stehen völlig zerstört!'::text,'die'::text,'wer'::text,'deren'::text,'Die Hand, die ihm den Hals kratzt, hat den Willen dieses Kängurus zu stehen völlig zerstört!'::text),
(384118,42680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рука, ... чеше йому шию, повністю знищила в цього кенгуру бажання стояти!'::text,'яка'::text,'хто'::text,'чия'::text,'Рука, яка чеше йому шию, повністю знищила в цього кенгуру бажання стояти!'::text),
(384117,42680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mano ... le rasca el cuello ha destruido por completo las ganas de este canguro de estar de pie!'::text,'que'::text,'quien'::text,'cuya'::text,'¡La mano que le rasca el cuello ha destruido por completo las ganas de este canguro de estar de pie!'::text),
(384116,42680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La main ... lui gratte le cou a complètement détruit la volonté de ce kangourou de rester debout !'::text,'qui'::text,'qui'::text,'dont'::text,'La main qui lui gratte le cou a complètement détruit la volonté de ce kangourou de rester debout !'::text),
(384119,42680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... boynunu kaşıyan el, bu kangurunun ayakta durma iradesini tamamen yok etti!'::text,''::text,NULL::text,NULL::text,'Boynunu kaşıyan el, bu kangurunun ayakta durma iradesini tamamen yok etti!'::text),
(384120,42680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kéz, ... a nyakát vakarja, teljesen megtörte ennek a kengurunak az akaratát, hogy álljon!'::text,'amely'::text,'aki'::text,'amelynek'::text,'A kéz, amely a nyakát vakarja, teljesen megtörte ennek a kengurunak az akaratát, hogy álljon!'::text),
(384123,42681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Besucherin schrie, das Känguru ... nie wieder aufstehen, wenn sie aufhöre zu kratzen!'::text,'würde'::text,'wird'::text,'kann'::text,'Die Besucherin schrie, das Känguru würde nie wieder aufstehen, wenn sie aufhöre zu kratzen!'::text),
(384127,42681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відвідувачка кричала, що кенгуру більше ніколи ..., якщо вона перестане чесати!'::text,'не встане'::text,'не встане'::text,'не зможе встати'::text,'Відвідувачка кричала, що кенгуру більше ніколи не встане, якщо вона перестане чесати!'::text),
(384126,42681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La visitante gritó que el canguro no ... a levantarse nunca si dejaba de rascarlo!'::text,'volvería'::text,'volverá'::text,'puede volver'::text,'¡La visitante gritó que el canguro no volvería a levantarse nunca si dejaba de rascarlo!'::text),
(384125,42681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La visiteuse a hurlé que le kangourou ne se ... plus jamais si elle arrêtait de le gratter !'::text,'relèverait'::text,'relèvera'::text,'peut relever'::text,'La visiteuse a hurlé que le kangourou ne se relèverait plus jamais si elle arrêtait de le gratter !'::text),
(384128,42681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaretçi, kaşımayı bırakırsa kangurunun bir daha asla ayağa ... bağırdı!'::text,'kalkmayacağını'::text,'kalkmayacağını'::text,'kalkamayacağını'::text,'Ziyaretçi, kaşımayı bırakırsa kangurunun bir daha asla ayağa kalkmayacağını bağırdı!'::text),
(384129,42681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogató azt sikította, hogy a kenguru soha többé ..., ha abbahagyja a vakarást!'::text,'nem állna fel'::text,'nem fog felállni'::text,'nem tud felállni'::text,'A látogató azt sikította, hogy a kenguru soha többé nem állna fel, ha abbahagyja a vakarást!'::text),
(391701,43523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... das Rehkitz wieder in der Stahlrinne.'::text,'liegt'::text,'liegt'::text,'liegt'::text,'Morgen um diese Zeit liegt das Rehkitz wieder in der Stahlrinne.'::text),
(391705,43523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час оленятко знову ... в сталевому жолобі.'::text,'лежатиме'::text,'ляже'::text,'лежить'::text,'Завтра в цей час оленятко знову лежатиме в сталевому жолобі.'::text),
(391704,43523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el cervatillo ... otra vez en el canal de acero.'::text,'estará tumbado'::text,'se tumbará'::text,'está tumbado'::text,'Mañana a esta hora, el cervatillo estará tumbado otra vez en el canal de acero.'::text),
(391703,43523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, le faon ... de nouveau dans la goulotte en acier.'::text,'sera allongé'::text,'s''allongera'::text,'est allongé'::text,'Demain à la même heure, le faon sera allongé de nouveau dans la goulotte en acier.'::text),
(391706,43523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte yavru geyik yine çelik olukta ...'::text,'yatıyor olacak'::text,'yatacak'::text,'yatıyor'::text,'Yarın bu saatte yavru geyik yine çelik olukta yatıyor olacak.'::text),
(391707,43523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor az őzgida újra az acélcsúszdában ...'::text,'fog feküdni'::text,'fog lefeküdni'::text,'fekszik'::text,'Holnap ilyenkor az őzgida újra az acélcsúszdában fog feküdni.'::text),
(391710,43524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, das Rehkitz ... bald die Stahlrutsche und geht zurück ins Gras.'::text,'verlässt'::text,'verlässt gerade'::text,'verlässt'::text,'Ich glaube, das Rehkitz verlässt bald die Stahlrutsche und geht zurück ins Gras.'::text),
(391714,43524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Думаю, оленятко скоро ... сталеву гірку й повернеться в траву.'::text,'покине'::text,'покидатиме'::text,'покидає'::text,'Думаю, оленятко скоро покине сталеву гірку й повернеться в траву.'::text),
(391713,43524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Creo que el cervatillo pronto ... el tobogán de acero y volverá a la hierba.'::text,'dejará'::text,'estará dejando'::text,'está dejando'::text,'Creo que el cervatillo pronto dejará el tobogán de acero y volverá a la hierba.'::text),
(391712,43524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense que le faon ... bientôt le toboggan en acier et retournera dans l''herbe.'::text,'quittera'::text,'sera en train de quitter'::text,'quitte'::text,'Je pense que le faon quittera bientôt le toboggan en acier et retournera dans l''herbe.'::text),
(391715,43524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence yavru geyik yakında çelik kaydıraktan ... ve çimenlere dönecek.'::text,'ayrılacak'::text,'ayrılıyor olacak'::text,'ayrılıyor'::text,'Bence yavru geyik yakında çelik kaydıraktan ayrılacak ve çimenlere dönecek.'::text),
(391716,43524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem az őzgida hamarosan ... az acélcsúszdát, és visszamegy a fűbe.'::text,'elhagyja'::text,'el fogja hagyni'::text,'hagyja el'::text,'Szerintem az őzgida hamarosan elhagyja az acélcsúszdát, és visszamegy a fűbe.'::text),
(391719,43525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn die Sonne den ganzen Tag auf eine Stahlrutsche ..., wird sie viel zu heiß zum Draufsitzen, ohne Witz.'::text,'scheint'::text,'schien'::text,'scheinen wird'::text,'Alter, wenn die Sonne den ganzen Tag auf eine Stahlrutsche scheint, wird sie viel zu heiß zum Draufsitzen, ohne Witz.'::text),
(391723,43525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якщо сонце ... на сталеву гірку весь день, вона так розжарюється, що на ній не сядеш, чесне слово.'::text,'світить'::text,'світило'::text,'світитиме'::text,'Чувак, якщо сонце світить на сталеву гірку весь день, вона так розжарюється, що на ній не сядеш, чесне слово.'::text),
(391722,43525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si el sol ... sobre un tobogán de acero todo el día, se pone demasiado caliente para sentarse, en serio.'::text,'brilla'::text,'brilló'::text,'brillará'::text,'Tío, si el sol brilla sobre un tobogán de acero todo el día, se pone demasiado caliente para sentarse, en serio.'::text),
(391721,43525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si le soleil ... sur un toboggan en acier toute la journée, il devient beaucoup trop chaud pour s''asseoir dessus, sans mentir.'::text,'tape'::text,'a tapé'::text,'tapera'::text,'Mec, si le soleil tape sur un toboggan en acier toute la journée, il devient beaucoup trop chaud pour s''asseoir dessus, sans mentir.'::text),
(391724,43525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güneş bütün gün çelik bir kaydırağa ..., üstüne oturulamayacak kadar ısınıyor, yemin ederim.'::text,'vurursa'::text,'vurduysa'::text,'vuracaksa'::text,'Kanka, güneş bütün gün çelik bir kaydırağa vurursa, üstüne oturulamayacak kadar ısınıyor, yemin ederim.'::text),
(391725,43525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha a nap egész nap ... egy acélcsúszdára, túl forró lesz ahhoz, hogy ráülj, komolyan.'::text,'süt'::text,'sütött'::text,'sütni fog'::text,'Haver, ha a nap egész nap süt egy acélcsúszdára, túl forró lesz ahhoz, hogy ráülj, komolyan.'::text),
(391728,43526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor den Budgetkürzungen ... diese Stahlrutsche die Top-Attraktion des Parks, mit 500 Fahrten pro Tag.'::text,'war früher'::text,'war'::text,'war gewohnt'::text,'Vor den Budgetkürzungen war früher diese Stahlrutsche die Top-Attraktion des Parks, mit 500 Fahrten pro Tag.'::text),
(391732,43526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До скорочення бюджету ця сталева гірка ... головним атракціоном парку, 500 відвідувачів на день.'::text,'була раніше'::text,'бувала'::text,'звикла бути'::text,'До скорочення бюджету ця сталева гірка була раніше головним атракціоном парку, 500 відвідувачів на день.'::text),
(391731,43526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de los recortes, este tobogán de acero ... ser la atracción estrella del parque, con 500 usuarios al día.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Antes de los recortes, este tobogán de acero solía ser la atracción estrella del parque, con 500 usuarios al día.'::text),
(391730,43526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant les coupes budgétaires, ce toboggan en acier ... l''attraction phare du parc, avec 500 passages par jour.'::text,'était autrefois'::text,'était'::text,'avait l''habitude d''être'::text,'Avant les coupes budgétaires, ce toboggan en acier était autrefois l''attraction phare du parc, avec 500 passages par jour.'::text),
(391733,43526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe kesintilerinden önce bu çelik kaydırak ... günde 500 kullanıcıyla parkın bir numaralı aletiydi.'::text,'eskiden'::text,'eskiden'::text,'alışkın olarak'::text,'Bütçe kesintilerinden önce bu çelik kaydırak eskiden günde 500 kullanıcıyla parkın bir numaralı aletiydi.'::text),
(391734,43526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A költségvetési megszorítások előtt ez az acélcsúszda ... a park legnépszerűbb játéka, napi 500 csúszóval.'::text,'volt régen'::text,'volt'::text,'hozzá volt szokva, hogy legyen'::text,'A költségvetési megszorítások előtt ez az acélcsúszda volt régen a park legnépszerűbb játéka, napi 500 csúszóval.'::text),
(391746,43528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh nein, die Stahlrutsche ist jetzt für immer das Bett des Rehkitzes, ...?'::text,'oder?'::text,'oder?'::text,'ja?'::text,'Oh nein, die Stahlrutsche ist jetzt für immer das Bett des Rehkitzes, oder?'::text),
(391750,43528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О ні, ця сталева гірка тепер назавжди ліжко оленятка, ...?'::text,'чи не так?'::text,'чи не так?'::text,'так?'::text,'О ні, ця сталева гірка тепер назавжди ліжко оленятка, чи не так?'::text),
(391749,43528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh no, ese tobogán de acero es ahora la cama del cervatillo para siempre, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿sí?'::text,'Oh no, ese tobogán de acero es ahora la cama del cervatillo para siempre, ¿verdad?'::text),
(391748,43528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oh non, ce toboggan en acier est le lit du faon pour toujours maintenant, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'c''est ça ?'::text,'Oh non, ce toboggan en acier est le lit du faon pour toujours maintenant, n''est-ce pas ?'::text),
(391751,43528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eyvah, o çelik kaydırak artık sonsuza dek yavru geyiğin yatağı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Eyvah, o çelik kaydırak artık sonsuza dek yavru geyiğin yatağı, değil mi?'::text),
(391752,43528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jaj ne, az acélcsúszda most már örökre az őzgida ágya, ...?'::text,'ugye?'::text,'ugye?'::text,'igen?'::text,'Jaj ne, az acélcsúszda most már örökre az őzgida ágya, ugye?'::text),
(391755,43529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neeein! Das Rehkitz hat es total geliebt, in der Stahlrutsche zu liegen, und ...'::text,'ich auch!'::text,'ich auch!'::text,'ich nicht!'::text,'Neeein! Das Rehkitz hat es total geliebt, in der Stahlrutsche zu liegen, und ich auch!'::text),
(391759,43529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніііі! Оленятко просто обожнювало лежати в сталевій гірці, і ...'::text,'я теж!'::text,'я теж!'::text,'я теж ні!'::text,'Ніііі! Оленятко просто обожнювало лежати в сталевій гірці, і я теж!'::text),
(391758,43529,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nooo! ¡Al cervatillo le encantaba tumbarse en el tobogán de acero, y ...'::text,'a mí también!'::text,'yo también!'::text,'a mí tampoco!'::text,'¡Nooo! ¡Al cervatillo le encantaba tumbarse en el tobogán de acero, y a mí también!'::text),
(391757,43529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nooon ! Le faon adorait s''allonger dans le toboggan en acier, et ...'::text,'moi aussi !'::text,'moi aussi !'::text,'moi non plus !'::text,'Nooon ! Le faon adorait s''allonger dans le toboggan en acier, et moi aussi !'::text),
(391760,43529,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayııır! Yavru geyik çelik kaydırakta yatmaya bayılıyordu, ...'::text,'ben de öyle!'::text,'ben de öyle!'::text,'ben de bayılmıyordum!'::text,'Hayııır! Yavru geyik çelik kaydırakta yatmaya bayılıyordu, ben de öyle!'::text),
(391761,43529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neee! Az őzgida imádott az acélcsúszdában feküdni, és ...'::text,'én is!'::text,'én is!'::text,'én sem!'::text,'Neee! Az őzgida imádott az acélcsúszdában feküdni, és én is!'::text),
(391764,43530,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur Dämmerung wird das Jungtier die Stahlrinne ... und ins hohe Gras zurückgekehrt sein.'::text,'verlassen haben'::text,'verlassen'::text,'verlässt'::text,'Bis zur Dämmerung wird das Jungtier die Stahlrinne verlassen haben und ins hohe Gras zurückgekehrt sein.'::text),
(391768,43530,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До сутінків дитинча ... сталевий жолоб і повернеться у високу траву.'::text,'покине'::text,'покине'::text,'покидає'::text,'До сутінків дитинча покине сталевий жолоб і повернеться у високу траву.'::text),
(391767,43530,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al anochecer, el ejemplar juvenil ... el canal de acero y habrá vuelto a la hierba alta.'::text,'habrá dejado'::text,'dejará'::text,'deja'::text,'Al anochecer, el ejemplar juvenil habrá dejado el canal de acero y habrá vuelto a la hierba alta.'::text),
(391766,43530,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le crépuscule, le jeune ... la goulotte en acier et sera retourné dans les hautes herbes.'::text,'aura quitté'::text,'quittera'::text,'quitte'::text,'D''ici le crépuscule, le jeune aura quitté la goulotte en acier et sera retourné dans les hautes herbes.'::text),
(391769,43530,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alacakaranlığa kadar yavru çelik oluktan ... ve uzun otlara dönmüş olacak.'::text,'ayrılmış'::text,'ayrılacak'::text,'ayrılıyor'::text,'Alacakaranlığa kadar yavru çelik oluktan ayrılmış ve uzun otlara dönmüş olacak.'::text),
(391770,43530,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szürkületre a fiatal egyed ... az acélcsatornát, és visszatér a magas fűbe.'::text,'elhagyja majd'::text,'el fogja hagyni'::text,'elhagyja'::text,'Szürkületre a fiatal egyed elhagyja majd az acélcsatornát, és visszatér a magas fűbe.'::text),
(391773,43531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre das Jungtier nicht aufgestanden, ... es den ganzen Nachmittag in der Stahlrinne geblieben.'::text,'wäre'::text,'würde'::text,'blieb'::text,'Wäre das Jungtier nicht aufgestanden, wäre es den ganzen Nachmittag in der Stahlrinne geblieben.'::text),
(391777,43531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби дитинча не встало, воно ... в сталевому жолобі до вечора.'::text,'залишилося б'::text,'залишилося б'::text,'залишилося'::text,'Якби дитинча не встало, воно залишилося б в сталевому жолобі до вечора.'::text),
(391776,43531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el ejemplar juvenil no se hubiera levantado, ... en el canal de acero toda la tarde.'::text,'habría permanecido'::text,'permanecería'::text,'permaneció'::text,'Si el ejemplar juvenil no se hubiera levantado, habría permanecido en el canal de acero toda la tarde.'::text),
(391775,43531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le jeune ne s''était pas levé, il ... dans la goulotte en acier tout l''après-midi.'::text,'serait resté'::text,'resterait'::text,'est resté'::text,'Si le jeune ne s''était pas levé, il serait resté dans la goulotte en acier tout l''après-midi.'::text),
(391778,43531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavru ayağa kalkmasaydı bütün öğleden sonra çelik olukta ...'::text,'kalmış olurdu'::text,'kalırdı'::text,'kaldı'::text,'Yavru ayağa kalkmasaydı bütün öğleden sonra çelik olukta kalmış olurdu.'::text),
(391779,43531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a fiatal egyed nem állt volna fel, egész délután ... az acélcsatornában.'::text,'maradt volna'::text,'maradna'::text,'maradt'::text,'Ha a fiatal egyed nem állt volna fel, egész délután maradt volna az acélcsatornában.'::text),
(391782,43532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswert: Stahl ... Wärme effizient, daher erwärmt sich eine Stahlrutsche in der Sonne schnell.'::text,'leitet'::text,'leitet gerade'::text,'hat geleitet'::text,'Bemerkenswert: Stahl leitet Wärme effizient, daher erwärmt sich eine Stahlrutsche in der Sonne schnell.'::text),
(391786,43532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Варто зазначити, що сталь ... тепло ефективно, тому сталева гірка швидко нагрівається на сонці.'::text,'проводить'::text,'проводить'::text,'провела'::text,'Варто зазначити, що сталь проводить тепло ефективно, тому сталева гірка швидко нагрівається на сонці.'::text)
