from (values
(391785,43532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cabe destacar que el acero ... el calor de forma eficiente, así que un tobogán de acero se calienta rápido al sol.'::text,'conduce'::text,'está conduciendo'::text,'ha conducido'::text,'Cabe destacar que el acero conduce el calor de forma eficiente, así que un tobogán de acero se calienta rápido al sol.'::text),
(391784,43532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait notable, l''acier ... efficacement la chaleur, donc un toboggan en acier chauffe vite au soleil.'::text,'conduit'::text,'est en train de conduire'::text,'a conduit'::text,'Fait notable, l''acier conduit efficacement la chaleur, donc un toboggan en acier chauffe vite au soleil.'::text),
(391787,43532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde çelik ısıyı verimli ..., bu yüzden çelik bir kaydırak güneşte hızla ısınır.'::text,'iletir'::text,'iletiyor'::text,'iletti'::text,'Dikkat çekici biçimde çelik ısıyı verimli iletir, bu yüzden çelik bir kaydırak güneşte hızla ısınır.'::text),
(391788,43532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó, hogy az acél hatékonyan ... a hőt, ezért egy acélcsúszda gyorsan felmelegszik a napon.'::text,'vezeti'::text,'vezeti'::text,'vezette'::text,'Figyelemre méltó, hogy az acél hatékonyan vezeti a hőt, ezért egy acélcsúszda gyorsan felmelegszik a napon.'::text),
(352884,39210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Diese Gestalt hat sich die ganze Nacht nicht von der Tür wegbewegt, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Albtraum! Diese Gestalt hat sich die ganze Nacht nicht von der Tür wegbewegt, oder?'::text),
(352888,39210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Ця постать усю ніч не рушала з дверного проходу, ...?'::text,'так?'::text,'чи не так?'::text,'так?'::text,'Жах! Ця постать усю ніч не рушала з дверного проходу, так?'::text),
(352887,39210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! Esa figura no se ha movido de la puerta en toda la noche, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'¡Pesadilla! Esa figura no se ha movido de la puerta en toda la noche, ¿verdad?'::text),
(352886,39210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Cette silhouette n''a pas bougé de l''embrasure de la porte de toute la nuit, ... ?'::text,'hein ?'::text,'n''est-ce pas ?'::text,'hein ?'::text,'Cauchemar ! Cette silhouette n''a pas bougé de l''embrasure de la porte de toute la nuit, hein ?'::text),
(352889,39210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! O figür bütün gece kapı eşiğinden hiç kıpırdamadı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Kâbus! O figür bütün gece kapı eşiğinden hiç kıpırdamadı, değil mi?'::text),
(352890,39210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Az az alak egész éjjel meg se mozdult az ajtóból, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Rémálom! Az az alak egész éjjel meg se mozdult az ajtóból, ugye?'::text),
(352893,39211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Der Mann bemerkte die Gestalt in der Tür nicht, und ...'::text,'der Hund auch nicht.'::text,'der Hund schon.'::text,'der Hund auch nicht.'::text,'Katastrophe! Der Mann bemerkte die Gestalt in der Tür nicht, und der Hund auch nicht.'::text),
(352897,39211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Чоловік не помітив постаті у дверях, і ...'::text,'пес теж ні.'::text,'пес теж.'::text,'пес теж ні.'::text,'Катастрофа! Чоловік не помітив постаті у дверях, і пес теж ні.'::text),
(352896,39211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! El hombre no se dio cuenta de la figura en la puerta, y ...'::text,'el perro tampoco.'::text,'el perro también.'::text,'el perro tampoco.'::text,'¡Desastre! El hombre no se dio cuenta de la figura en la puerta, y el perro tampoco.'::text),
(352895,39211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! L''homme n''a pas remarqué la silhouette dans l''embrasure, et ...'::text,'le chien non plus.'::text,'le chien aussi.'::text,'le chien non plus.'::text,'Catastrophe ! L''homme n''a pas remarqué la silhouette dans l''embrasure, et le chien non plus.'::text),
(352898,39211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Adam kapıdaki figürü fark etmedi, ...'::text,'köpek de etmedi.'::text,'köpek de etti.'::text,'köpek de değildi.'::text,'Felaket! Adam kapıdaki figürü fark etmedi, köpek de etmedi.'::text),
(352899,39211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A férfi nem vette észre az alakot az ajtóban, és ...'::text,'a kutya sem.'::text,'a kutya is.'::text,'a kutya sem.'::text,'Katasztrófa! A férfi nem vette észre az alakot az ajtóban, és a kutya sem.'::text),
(352902,39212,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, er ... stundenlang auf sein Tablet, bevor die Gestalt auftauchte.'::text,'guckte schon'::text,'guckt'::text,'guckte'::text,'Bestie, ich hab gehört, er guckte schon stundenlang auf sein Tablet, bevor die Gestalt auftauchte.'::text),
(352906,39212,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, я чула, що він ... в планшет годинами, перш ніж з''явилася постать.'::text,'дивився'::text,'дивиться'::text,'дивився'::text,'Подружко, я чула, що він дивився в планшет годинами, перш ніж з''явилася постать.'::text),
(352905,39212,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me enteré de que él ... la tableta durante horas antes de que apareciera la figura.'::text,'había estado mirando'::text,'ha estado mirando'::text,'estaba mirando'::text,'Amiga, me enteré de que él había estado mirando la tableta durante horas antes de que apareciera la figura.'::text),
(352904,39212,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire qu''il ... sa tablette pendant des heures avant que la silhouette n''apparaisse.'::text,'avait regardé'::text,'a regardé'::text,'regardait'::text,'Ma belle, j''ai entendu dire qu''il avait regardé sa tablette pendant des heures avant que la silhouette n''apparaisse.'::text),
(352907,39212,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki figür belirmeden önce saatlerdir tabletine ...'::text,'bakıyormuş'::text,'bakıyor'::text,'bakıyordu'::text,'Kanka, duydum ki figür belirmeden önce saatlerdir tabletine bakıyormuş.'::text),
(352908,39212,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy órák óta ... a tabletjét, mielőtt megjelent az alak.'::text,'nézte'::text,'nézi'::text,'nézte'::text,'Csajszi, azt hallottam, hogy órák óta nézte a tabletjét, mielőtt megjelent az alak.'::text),
(352911,39213,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend wird er bis Mitternacht die ganze Serie ..., Gestalt hin oder her.'::text,'beendet haben'::text,'beenden'::text,'am Beenden sein'::text,'Hör zu, anscheinend wird er bis Mitternacht die ganze Serie beendet haben, Gestalt hin oder her.'::text),
(352915,39213,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, до півночі він ... весь серіал, з постаттю чи без.'::text,'додивиться'::text,'додивиться'::text,'додивлятиметься'::text,'Слухай, кажуть, до півночі він додивиться весь серіал, з постаттю чи без.'::text),
(352914,39213,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer para medianoche ... toda la serie, con figura o sin ella.'::text,'habrá terminado'::text,'terminará'::text,'estará terminando'::text,'Escucha, al parecer para medianoche habrá terminado toda la serie, con figura o sin ella.'::text),
(352913,39213,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment d''ici minuit il ... toute la série, silhouette ou pas.'::text,'aura fini'::text,'finira'::text,'sera en train de finir'::text,'Écoute, apparemment d''ici minuit il aura fini toute la série, silhouette ou pas.'::text),
(352916,39213,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya gece yarısına kadar bütün diziyi ..., figür olsa da olmasa da.'::text,'bitirmiş olacak'::text,'bitirecek'::text,'bitiriyor olacak'::text,'Dinle, güya gece yarısına kadar bütün diziyi bitirmiş olacak, figür olsa da olmasa da.'::text),
(352917,39213,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag éjfélre ... az egész sorozatot, alak ide vagy oda.'::text,'befejezi'::text,'be fogja fejezni'::text,'fejezi be éppen'::text,'Figyelj, állítólag éjfélre befejezi az egész sorozatot, alak ide vagy oda.'::text),
(352920,39214,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, anscheinend ... diese Gestalt um 2 Uhr nachts schon drei Stunden in der Tür.'::text,'steht'::text,'steht'::text,'steht'::text,'Rate mal, anscheinend steht diese Gestalt um 2 Uhr nachts schon drei Stunden in der Tür.'::text),
(352924,39214,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, о 2 ночі та постать уже три години ... у дверях.'::text,'стоятиме'::text,'стоятиме'::text,'стоятиме'::text,'Уяви, кажуть, о 2 ночі та постать уже три години стоятиме у дверях.'::text),
(352923,39214,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, al parecer a las 2 de la madrugada esa figura ... en la puerta tres horas.'::text,'habrá estado de pie'::text,'estará de pie'::text,'estará'::text,'Adivina, al parecer a las 2 de la madrugada esa figura habrá estado de pie en la puerta tres horas.'::text),
(352922,39214,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment à 2 h du matin, cette silhouette ... dans l''embrasure depuis trois heures.'::text,'se tiendra'::text,'se tiendra'::text,'se tiendra'::text,'Devine quoi, apparemment à 2 h du matin, cette silhouette se tiendra dans l''embrasure depuis trois heures.'::text),
(352925,39214,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, güya gece 2''de o figür üç saattir kapı eşiğinde ...'::text,'duruyor olacak'::text,'duruyor olacak'::text,'duracak'::text,'Bil bakalım, güya gece 2''de o figür üç saattir kapı eşiğinde duruyor olacak.'::text),
(352926,39214,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag hajnali 2-re az az alak már három órája ... az ajtóban.'::text,'áll majd'::text,'áll majd'::text,'fog állni'::text,'Képzeld, állítólag hajnali 2-re az az alak már három órája áll majd az ajtóban.'::text),
(352929,39215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du diese Gestalt gesehen hättest, ... du nicht so entspannt eingeschlafen.'::text,'wärst'::text,'wirst'::text,'bist'::text,'Ehrlich, wenn du diese Gestalt gesehen hättest, wärst du nicht so entspannt eingeschlafen.'::text),
(352933,39215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти побачив ту постать, ... так спокійно.'::text,'не заснув би'::text,'не заснеш'::text,'не заснув'::text,'Чесно, якби ти побачив ту постать, не заснув би так спокійно.'::text),
(352932,39215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, si hubieras visto esa figura, ... tan tranquilo.'::text,'no te habrías dormido'::text,'no te dormirás'::text,'no te dormiste'::text,'No te voy a mentir, si hubieras visto esa figura, no te habrías dormido tan tranquilo.'::text),
(352931,39215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu avais vu cette silhouette, tu ... aussi tranquillement.'::text,'ne te serais pas endormi'::text,'ne t''endormiras pas'::text,'ne t''es pas endormi'::text,'Franchement, si tu avais vu cette silhouette, tu ne te serais pas endormi aussi tranquillement.'::text),
(352934,39215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o figürü görseydin bu kadar rahat uykuya ...'::text,'dalmazdın'::text,'dalmayacaksın'::text,'dalmadın'::text,'Yalan yok, o figürü görseydin bu kadar rahat uykuya dalmazdın.'::text),
(352935,39215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha láttad volna azt az alakot, ... ilyen nyugodtan.'::text,'nem aludtál volna el'::text,'nem fogsz elaludni'::text,'nem aludtál el'::text,'Nem hazudok, ha láttad volna azt az alakot, nem aludtál volna el ilyen nyugodtan.'::text),
(352938,39216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Hättest du die Gestalt letzte Nacht bemerkt, ... du jetzt nicht so entspannt.'::text,'wärst'::text,'wärst gewesen'::text,'wirst'::text,'Respekt: Hättest du die Gestalt letzte Nacht bemerkt, wärst du jetzt nicht so entspannt.'::text),
(352942,39216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: якби ти помітив постать минулої ночі, ти ... зараз таким розслабленим.'::text,'не був би'::text,'не був би'::text,'не будеш'::text,'Респект: якби ти помітив постать минулої ночі, ти не був би зараз таким розслабленим.'::text),
(352941,39216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: si hubieras notado la figura anoche, ahora ... tan relajado.'::text,'no estarías'::text,'no habrías estado'::text,'no estarás'::text,'Respeto: si hubieras notado la figura anoche, ahora no estarías tan relajado.'::text),
(352940,39216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : si tu avais remarqué la silhouette hier soir, tu ... pas aussi détendu maintenant.'::text,'ne serais'::text,'n''aurais été'::text,'ne seras'::text,'Respect : si tu avais remarqué la silhouette hier soir, tu ne serais pas aussi détendu maintenant.'::text),
(352943,39216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: dün gece figürü fark etseydin şimdi bu kadar rahat ...'::text,'olmazdın'::text,'olmamış olurdun'::text,'olmayacaksın'::text,'Saygılar: dün gece figürü fark etseydin şimdi bu kadar rahat olmazdın.'::text),
(352944,39216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: ha tegnap éjjel észrevetted volna az alakot, most ... ilyen nyugodt.'::text,'nem lennél'::text,'nem lettél volna'::text,'nem leszel'::text,'Respekt: ha tegnap éjjel észrevetted volna az alakot, most nem lennél ilyen nyugodt.'::text),
(352947,39217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gestalt soll den Großteil der letzten Nacht in der Tür ...'::text,'gestanden haben'::text,'stehen'::text,'stehend'::text,'Die Gestalt soll den Großteil der letzten Nacht in der Tür gestanden haben.'::text),
(352951,39217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважають, що постать ... у дверях більшу частину минулої ночі.'::text,'стояла'::text,'стоїть'::text,'стоявши'::text,'Вважають, що постать стояла у дверях більшу частину минулої ночі.'::text),
(352950,39217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la figura ... en la puerta la mayor parte de la noche anterior.'::text,'estuvo de pie'::text,'está de pie'::text,'habiendo estado'::text,'Se cree que la figura estuvo de pie en la puerta la mayor parte de la noche anterior.'::text),
(352949,39217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la silhouette ... dans l''embrasure la plus grande partie de la nuit dernière.'::text,'est restée'::text,'se tient'::text,'ayant été'::text,'On pense que la silhouette est restée dans l''embrasure la plus grande partie de la nuit dernière.'::text),
(352952,39217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figürün dün gecenin çoğunda kapı eşiğinde ... düşünülüyor.'::text,'durmakta olduğu'::text,'durduğu'::text,'durmuş'::text,'Figürün dün gecenin çoğunda kapı eşiğinde durmakta olduğu düşünülüyor.'::text),
(352953,39217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vélik, az alak az elmúlt éjszaka nagy részében ... az ajtóban.'::text,'állt'::text,'áll'::text,'állva'::text,'Úgy vélik, az alak az elmúlt éjszaka nagy részében állt az ajtóban.'::text),
(352956,39218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am nächsten Morgen bestritt der Mann, irgendeine Gestalt in der Tür ...'::text,'gesehen zu haben'::text,'gesehen zu haben'::text,'zu sehen'::text,'Am nächsten Morgen bestritt der Mann, irgendeine Gestalt in der Tür gesehen zu haben.'::text),
(352960,39218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного ранку чоловік заперечив, що ... якусь постать у дверях.'::text,'бачив'::text,'бачив'::text,'бачить'::text,'Наступного ранку чоловік заперечив, що бачив якусь постать у дверях.'::text),
(352959,39218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A la mañana siguiente, el hombre negó ... ninguna figura en la puerta.'::text,'haber visto'::text,'haber visto'::text,'ver'::text,'A la mañana siguiente, el hombre negó haber visto ninguna figura en la puerta.'::text),
(352958,39218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le lendemain matin, l''homme a nié ... une quelconque silhouette dans l''embrasure.'::text,'avoir vu'::text,'avoir vu'::text,'voir'::text,'Le lendemain matin, l''homme a nié avoir vu une quelconque silhouette dans l''embrasure.'::text),
(352961,39218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ertesi sabah adam kapı eşiğinde herhangi bir figür ... inkâr etti.'::text,'gördüğünü'::text,'gördüğünü'::text,'görmeyi'::text,'Ertesi sabah adam kapı eşiğinde herhangi bir figür gördüğünü inkâr etti.'::text),
(352962,39218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Másnap reggel a férfi tagadta, hogy ... bármilyen alakot az ajtóban.'::text,'látott'::text,'látott'::text,'lát'::text,'Másnap reggel a férfi tagadta, hogy látott bármilyen alakot az ajtóban.'::text),
(402681,44743,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit der Ebbe ... die heimische Tierwelt die freigelegten Sandflächen, insbesondere die Bären.'::text,'nutzt'::text,'nutzt gerade'::text,'nutzt'::text,'Seit der Ebbe nutzt die heimische Tierwelt die freigelegten Sandflächen, insbesondere die Bären.'::text),
(402685,44743,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Від часу відпливу місцева дика природа ... оголені піщані мілини, особливо ведмеді.'::text,'використовує'::text,'використовує'::text,'використовує'::text,'Від часу відпливу місцева дика природа використовує оголені піщані мілини, особливо ведмеді.'::text),
(402684,44743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde la marea baja, la fauna local ... los bancos de arena al descubierto, en especial los osos.'::text,'ha estado usando'::text,'está usando'::text,'usa'::text,'Desde la marea baja, la fauna local ha estado usando los bancos de arena al descubierto, en especial los osos.'::text),
(402683,44743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis la marée basse, la faune locale ... les bancs de sable découverts, notamment les ours.'::text,'utilise'::text,'est en train d''utiliser'::text,'utilise'::text,'Depuis la marée basse, la faune locale utilise les bancs de sable découverts, notamment les ours.'::text),
(402686,44743,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cezirden beri yerel yaban hayatı açığa çıkan kum düzlüklerini ..., özellikle de ayılar.'::text,'kullanıyor'::text,'kullanıyor'::text,'kullanır'::text,'Cezirden beri yerel yaban hayatı açığa çıkan kum düzlüklerini kullanıyor, özellikle de ayılar.'::text),
(402687,44743,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apály óta a helyi vadvilág ... a szabaddá vált homokpadokat, főleg a medvék.'::text,'használja'::text,'használja'::text,'használja'::text,'Apály óta a helyi vadvilág használja a szabaddá vált homokpadokat, főleg a medvék.'::text),
(402690,44744,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Jungen ... gerade am Raben vorbei, als er zur Seite hüpfte, weil Wildtiere es hassen, getreten zu werden.'::text,'liefen'::text,'liefen'::text,'sind gelaufen'::text,'Die Jungen liefen gerade am Raben vorbei, als er zur Seite hüpfte, weil Wildtiere es hassen, getreten zu werden.'::text),
(402694,44744,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ведмежата ... повз ворона, коли він відскочив убік, бо дика природа ненавидить, коли на неї наступають.'::text,'бігли'::text,'пробігли'::text,'пробігли'::text,'Ведмежата бігли повз ворона, коли він відскочив убік, бо дика природа ненавидить, коли на неї наступають.'::text),
(402693,44744,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los oseznos ... junto al cuervo cuando este saltó a un lado, porque la fauna salvaje odia que la pisen.'::text,'estaban corriendo'::text,'corrieron'::text,'han corrido'::text,'Los oseznos estaban corriendo junto al cuervo cuando este saltó a un lado, porque la fauna salvaje odia que la pisen.'::text),
(402692,44744,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les oursons ... devant le corbeau quand il a sauté sur le côté, parce que la faune déteste se faire marcher dessus.'::text,'couraient'::text,'ont couru'::text,'ont couru'::text,'Les oursons couraient devant le corbeau quand il a sauté sur le côté, parce que la faune déteste se faire marcher dessus.'::text),
(402695,44744,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuzgun yana sıçradığında yavrular yanından ..., çünkü yaban hayatı üzerine basılmaktan nefret eder.'::text,'koşuyordu'::text,'koştu'::text,'koştular'::text,'Kuzgun yana sıçradığında yavrular yanından koşuyordu, çünkü yaban hayatı üzerine basılmaktan nefret eder.'::text),
(402696,44744,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bocsok ... a holló mellett, amikor az félreugrott, mert a vadvilág utálja, ha rálépnek.'::text,'futottak el'::text,'elfutottak'::text,'elfutottak'::text,'A bocsok futottak el a holló mellett, amikor az félreugrott, mert a vadvilág utálja, ha rálépnek.'::text),
(402699,44745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Guide warnte uns, den Wildtieren am Strand nicht zu nahe ...'::text,'zu kommen'::text,'zu kommen'::text,'kommend'::text,'Der Guide warnte uns, den Wildtieren am Strand nicht zu nahe zu kommen.'::text),
(402703,44745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід попередив нас ... надто близько до диких тварин на пляжі.'::text,'не підходити'::text,'не підходити'::text,'не підходячи'::text,'Гід попередив нас не підходити надто близько до диких тварин на пляжі.'::text),
(402702,44745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El guía nos advirtió ... demasiado a la fauna de la playa.'::text,'que no nos acercáramos'::text,'no acercarnos'::text,'no acercándonos'::text,'El guía nos advirtió que no nos acercáramos demasiado a la fauna de la playa.'::text),
(402701,44745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le guide nous a prévenus ... trop près de la faune sur la plage.'::text,'de ne pas aller'::text,'de ne pas aller'::text,'en n''allant pas'::text,'Le guide nous a prévenus de ne pas aller trop près de la faune sur la plage.'::text),
(402704,44745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber bizi sahildeki yaban hayatına fazla ... uyardı.'::text,'yaklaşmamamız için'::text,'yaklaşmamamız için'::text,'yaklaşmadan'::text,'Rehber bizi sahildeki yaban hayatına fazla yaklaşmamamız için uyardı.'::text),
(402705,44745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túravezető figyelmeztetett minket, hogy ... túl közel a vadállatokhoz a parton.'::text,'ne menjünk'::text,'ne menjünk'::text,'nem menve'::text,'A túravezető figyelmeztetett minket, hogy ne menjünk túl közel a vadállatokhoz a parton.'::text),
(402717,44747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, der Park ließ ein Drohnenteam alle Wildtiere an diesem Strand ...'::text,'filmen'::text,'zu filmen'::text,'gefilmt'::text,'Hör zu, er hat mir erzählt, der Park ließ ein Drohnenteam alle Wildtiere an diesem Strand filmen.'::text),
(402721,44747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що парк доручив команді з дронами ... всіх диких тварин на тому пляжі.'::text,'зняти'::text,'зняти'::text,'знятих'::text,'Слухай, він сказав мені, що парк доручив команді з дронами зняти всіх диких тварин на тому пляжі.'::text),
(402720,44747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que el parque hizo que un equipo de drones ... toda la fauna de esa playa.'::text,'grabara'::text,'grabar'::text,'grabada'::text,'Escucha, me dijo que el parque hizo que un equipo de drones grabara toda la fauna de esa playa.'::text),
(402719,44747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que le parc avait fait ... toute la faune de cette plage à une équipe de drones.'::text,'filmer'::text,'filmer'::text,'filmée'::text,'Écoute, il m''a dit que le parc avait fait filmer toute la faune de cette plage à une équipe de drones.'::text),
(402722,44747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana parkın o sahildeki bütün yaban hayatını bir drone ekibine ... söyledi.'::text,'çektirdiğini'::text,'çektirdiğini'::text,'çekildiğini'::text,'Dinle, bana parkın o sahildeki bütün yaban hayatını bir drone ekibine çektirdiğini söyledi.'::text),
(402723,44747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a park egy drónos stábbal ... le az összes vadállatot azon a parton.'::text,'filmeztette'::text,'filmeztette'::text,'filmezte'::text,'Figyelj, azt mondta, hogy a park egy drónos stábbal filmeztette le az összes vadállatot azon a parton.'::text),
(402726,44748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, ich ... die Tiere an diesem Strand mit eigenen Augen sehen.'::text,'könnte'::text,'kann'::text,'werde'::text,'Ich wünschte, ich könnte die Tiere an diesem Strand mit eigenen Augen sehen.'::text),
(402730,44748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ж я ... тих диких тварин на тому пляжі на власні очі.'::text,'міг побачити'::text,'можу побачити'::text,'побачу'::text,'Якби ж я міг побачити тих диких тварин на тому пляжі на власні очі.'::text),
(402729,44748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ojalá ... ver la fauna de esa playa con mis propios ojos.'::text,'pudiera'::text,'puedo'::text,'podré'::text,'Ojalá pudiera ver la fauna de esa playa con mis propios ojos.'::text),
(402728,44748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement je ... voir la faune de cette plage de mes propres yeux.'::text,'pouvais'::text,'peux'::text,'pourrai'::text,'Si seulement je pouvais voir la faune de cette plage de mes propres yeux.'::text),
(402731,44748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke o sahildeki yaban hayatını kendi gözlerimle ...'::text,'görebilsem'::text,'görebilirim'::text,'göreceğim'::text,'Keşke o sahildeki yaban hayatını kendi gözlerimle görebilsem.'::text),
(402732,44748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak ... a saját szememmel azt a vadvilágot a parton.'::text,'láthatnám'::text,'láthatom'::text,'látni fogom'::text,'Bárcsak láthatnám a saját szememmel azt a vadvilágot a parton.'::text),
(402735,44749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Rabe, ... Flügel sich weit öffneten, hüpfte von den vorbeiziehenden Tieren weg.'::text,'dessen'::text,'der'::text,'das'::text,'Der Rabe, dessen Flügel sich weit öffneten, hüpfte von den vorbeiziehenden Tieren weg.'::text),
(402739,44749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ворон, ... крила широко розкрилися, відскочив від тварин, що проходили повз.'::text,'чиї'::text,'який'::text,'що'::text,'Ворон, чиї крила широко розкрилися, відскочив від тварин, що проходили повз.'::text),
(402738,44749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cuervo, ... alas se abrieron de par en par, se apartó dando saltitos de los animales que pasaban.'::text,'cuyas'::text,'el cual'::text,'que'::text,'El cuervo, cuyas alas se abrieron de par en par, se apartó dando saltitos de los animales que pasaban.'::text),
(402737,44749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le corbeau, ... les ailes se sont grandes ouvertes, s''est éloigné en sautillant des animaux qui passaient.'::text,'dont'::text,'lequel'::text,'que'::text,'Le corbeau, dont les ailes se sont grandes ouvertes, s''est éloigné en sautillant des animaux qui passaient.'::text),
(402740,44749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kanatlarını iki yana açan kuzgun, yanından geçen hayvanlardan sekerek uzaklaştı.'::text,''::text,NULL::text,NULL::text,'Kanatlarını iki yana açan kuzgun, yanından geçen hayvanlardan sekerek uzaklaştı.'::text),
(402741,44749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A holló, ... szárnya szélesre tárult, elugrált az arra haladó állatok elől.'::text,'amelynek'::text,'amely'::text,'ami'::text,'A holló, amelynek szárnya szélesre tárult, elugrált az arra haladó állatok elől.'::text),
(402744,44750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... an diesem Strand umfasst eine Bärenmutter, zwei Junge und einen Raben.'::text,'Die Tierwelt'::text,'Eine Tierwelt'::text,'Die Tierwelten'::text,'Die Tierwelt an diesem Strand umfasst eine Bärenmutter, zwei Junge und einen Raben.'::text),
(402748,44750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... на цьому пляжі включає ведмедицю, двох ведмежат і ворона.'::text,'Дика природа'::text,'Дика природа'::text,'Дикі природи'::text,'Дика природа на цьому пляжі включає ведмедицю, двох ведмежат і ворона.'::text),
(402747,44750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de esta playa incluye una osa, dos oseznos y un cuervo.'::text,'La fauna'::text,'Una fauna'::text,'Las faunas'::text,'La fauna de esta playa incluye una osa, dos oseznos y un cuervo.'::text),
(402746,44750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de cette plage comprend une mère ourse, deux oursons et un corbeau.'::text,'La faune'::text,'Une faune'::text,'Les faunes'::text,'La faune de cette plage comprend une mère ourse, deux oursons et un corbeau.'::text),
(402749,44750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sahildeki ... bir anne ayı, iki yavru ve bir kuzgundan oluşuyor.'::text,'yaban hayatı'::text,'bir yaban hayatı'::text,'yaban hayatları'::text,'Bu sahildeki yaban hayatı bir anne ayı, iki yavru ve bir kuzgundan oluşuyor.'::text),
(402750,44750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ezen a parton egy anyamedvéből, két bocsból és egy hollóból áll.'::text,'A vadvilág'::text,'Egy vadvilág'::text,'A vadvilágok'::text,'A vadvilág ezen a parton egy anyamedvéből, két bocsból és egy hollóból áll.'::text),
(402753,44751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der riesigen vorbeiziehenden Tiere hielt der Rabe bis zum schrecklichen Ende die Stellung!'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz der riesigen vorbeiziehenden Tiere hielt der Rabe bis zum schrecklichen Ende die Stellung!'::text),
(402757,44751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... величезних звірів, які проходили повз, ворон стояв на своєму до жахливого кінця!'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри величезних звірів, які проходили повз, ворон стояв на своєму до жахливого кінця!'::text),
(402756,44751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... la enorme fauna que pasaba, el cuervo aguantó en su sitio hasta el aterrador final!'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'¡A pesar de la enorme fauna que pasaba, el cuervo aguantó en su sitio hasta el aterrador final!'::text),
(402755,44751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... les énormes animaux qui passaient, le corbeau a tenu bon jusqu''à la fin terrifiante !'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré les énormes animaux qui passaient, le corbeau a tenu bon jusqu''à la fin terrifiante !'::text),
(402758,44751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanından geçen devasa hayvanlara ..., kuzgun korkunç sona kadar yerinden kıpırdamadı!'::text,'rağmen'::text,'rağmen'::text,'yüzünden'::text,'Yanından geçen devasa hayvanlara rağmen, kuzgun korkunç sona kadar yerinden kıpırdamadı!'::text),
(402759,44751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mellette elhaladó hatalmas állatok ..., a holló kitartott a rémisztő végéig!'::text,'ellenére'::text,'ellenére'::text,'miatt'::text,'A mellette elhaladó hatalmas állatok ellenére, a holló kitartott a rémisztő végéig!'::text),
(402762,44752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In etwa zwei Jahren ... die Jungen ihre Mutter verlassen und sich den erwachsenen Tieren angeschlossen haben.'::text,'werden'::text,'werden'::text,'verlassen'::text,'In etwa zwei Jahren werden die Jungen ihre Mutter verlassen und sich den erwachsenen Tieren angeschlossen haben.'::text),
(402766,44752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Приблизно через два роки ведмежата ... матір і приєднаються до дорослих тварин.'::text,'покинуть'::text,'покинуть'::text,'покидають'::text,'Приблизно через два роки ведмежата покинуть матір і приєднаються до дорослих тварин.'::text),
(402765,44752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dentro de unos dos años, los oseznos ... a su madre y se habrán unido a la fauna adulta.'::text,'habrán dejado'::text,'dejarán'::text,'dejan'::text,'Dentro de unos dos años, los oseznos habrán dejado a su madre y se habrán unido a la fauna adulta.'::text),
(402764,44752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici environ deux ans, les oursons ... leur mère et auront rejoint la faune adulte.'::text,'auront quitté'::text,'quitteront'::text,'quittent'::text,'D''ici environ deux ans, les oursons auront quitté leur mère et auront rejoint la faune adulte.'::text),
(402767,44752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaklaşık iki yıl sonra yavrular annelerinden ... ve yetişkin yaban hayatına katılmış olacaklar.'::text,'ayrılmış'::text,'ayrılacak'::text,'ayrılıyor'::text,'Yaklaşık iki yıl sonra yavrular annelerinden ayrılmış ve yetişkin yaban hayatına katılmış olacaklar.'::text),
(402768,44752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyjából két év múlva a bocsok ... az anyjukat, és csatlakoznak a felnőtt vadvilághoz.'::text,'elhagyják'::text,'el fogják hagyni'::text,'elhagyják'::text,'Nagyjából két év múlva a bocsok elhagyják az anyjukat, és csatlakoznak a felnőtt vadvilághoz.'::text),
(337701,37523,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der blaue Papagei ... ihn jetzt schon seit zehn Minuten. Schnelle Arbeit, ganz klar.'::text,'beruhigt'::text,'beruhigt gerade'::text,'beruhigt'::text,'Der blaue Papagei beruhigt ihn jetzt schon seit zehn Minuten. Schnelle Arbeit, ganz klar.'::text),
(337705,37523,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Синій папуга ... його вже десять хвилин. Швидка робота, звісно.'::text,'заспокоює'::text,'заспокоює'::text,'заспокоює'::text,'Синій папуга заспокоює його вже десять хвилин. Швидка робота, звісно.'::text),
(337704,37523,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El loro azul lo ... desde hace diez minutos. Trabajo rápido, está claro.'::text,'ha estado calmando'::text,'está calmando'::text,'calma'::text,'El loro azul lo ha estado calmando desde hace diez minutos. Trabajo rápido, está claro.'::text),
(337703,37523,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le perroquet bleu le ... depuis dix minutes. Un boulot rapide, clairement.'::text,'calme'::text,'est en train de calmer'::text,'calme'::text,'Le perroquet bleu le calme depuis dix minutes. Un boulot rapide, clairement.'::text),
(337706,37523,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mavi papağan on dakikadır onu ...; hızlı bir iş, belli.'::text,'sakinleştiriyor'::text,'sakinleştiriyor'::text,'sakinleştirir'::text,'Mavi papağan on dakikadır onu sakinleştiriyor; hızlı bir iş, belli.'::text),
(337707,37523,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kék papagáj már tíz perce ... őt. Gyors munka, nyilván.'::text,'nyugtatja'::text,'nyugtatja'::text,'nyugtatja'::text,'A kék papagáj már tíz perce nyugtatja őt. Gyors munka, nyilván.'::text),
(337710,37524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... beruhigt eine einzige Umarmung einen wütenden Papagei so schnell.'::text,''::text,NULL::text,NULL::text,'Selten beruhigt eine einzige Umarmung einen wütenden Papagei so schnell.'::text),
(337714,37524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... одні обійми так швидко заспокоюють розлюченого папугу.'::text,''::text,NULL::text,NULL::text,'Рідко одні обійми так швидко заспокоюють розлюченого папугу.'::text),
(337713,37524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... un solo abrazo calma a un loro enfadado tan rápido.'::text,''::text,NULL::text,NULL::text,'Rara vez un solo abrazo calma a un loro enfadado tan rápido.'::text),
(337712,37524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un seul câlin calme un perroquet en colère aussi vite.'::text,''::text,NULL::text,NULL::text,'Rarement un seul câlin calme un perroquet en colère aussi vite.'::text),
(337715,37524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... tek bir sarılma kızgın bir papağanı bu kadar çabuk sakinleştirir.'::text,''::text,NULL::text,NULL::text,'Nadiren tek bir sarılma kızgın bir papağanı bu kadar çabuk sakinleştirir.'::text),
(337716,37524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... nyugtat meg egyetlen ölelés ilyen gyorsan egy dühös papagájt.'::text,''::text,NULL::text,NULL::text,'Ritkán nyugtat meg egyetlen ölelés ilyen gyorsan egy dühös papagájt.'::text),
(337719,37525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der blaue Papagei brachte den wütenden Papagei mit einer einzigen Umarmung dazu, sich zu ...'::text,'beruhigen'::text,'beruhigen'::text,'beruhigt'::text,'Der blaue Papagei brachte den wütenden Papagei mit einer einzigen Umarmung dazu, sich zu beruhigen.'::text),
(337723,37525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Синій папуга одними обіймами змусив розлюченого папугу ...'::text,'заспокоїтися'::text,'заспокоїтися'::text,'заспокоюється'::text,'Синій папуга одними обіймами змусив розлюченого папугу заспокоїтися.'::text),
(337722,37525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El loro azul consiguió que el loro enfadado se ... con un solo abrazo.'::text,'calmara'::text,'calme'::text,'calma'::text,'El loro azul consiguió que el loro enfadado se calmara con un solo abrazo.'::text),
(337721,37525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le perroquet bleu a amené le perroquet en colère à se ... d''un seul câlin.'::text,'calmer'::text,'calmer'::text,'calme'::text,'Le perroquet bleu a amené le perroquet en colère à se calmer d''un seul câlin.'::text),
(337724,37525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mavi papağan tek bir sarılmayla kızgın papağanın ... sağladı.'::text,'sakinleşmesini'::text,'sakinleşmesini'::text,'sakinleşiyor'::text,'Mavi papağan tek bir sarılmayla kızgın papağanın sakinleşmesini sağladı.'::text),
(337725,37525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kék papagáj egyetlen öleléssel elérte, hogy a dühös papagáj ...'::text,'megnyugodjon'::text,'megnyugodjon'::text,'megnyugszik'::text,'A kék papagáj egyetlen öleléssel elérte, hogy a dühös papagáj megnyugodjon.'::text),
(337728,37526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der grüne Papagei wünschte jetzt, er ... ruhig geblieben, bevor er ins Zimmer stürmte.'::text,'wäre'::text,'bliebe'::text,'würde bleiben'::text,'Der grüne Papagei wünschte jetzt, er wäre ruhig geblieben, bevor er ins Zimmer stürmte.'::text),
(337732,37526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зелений папуга тепер хотів би, щоб він ... спокійним, перш ніж увірвався в кімнату.'::text,'залишився'::text,'залишався'::text,'залишався б'::text,'Зелений папуга тепер хотів би, щоб він залишився спокійним, перш ніж увірвався в кімнату.'::text),
(337731,37526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El loro verde ahora desearía que ... tranquilo antes de irrumpir en la sala.'::text,'se hubiera quedado'::text,'se quedara'::text,'se quedaría'::text,'El loro verde ahora desearía que se hubiera quedado tranquilo antes de irrumpir en la sala.'::text),
(337730,37526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le perroquet vert aimerait maintenant ... calme avant de débarquer dans la pièce.'::text,'être resté'::text,'rester'::text,'resterait'::text,'Le perroquet vert aimerait maintenant être resté calme avant de débarquer dans la pièce.'::text),
(337733,37526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeşil papağan şimdi keşke odaya dalmadan önce sakin ... diye düşünüyor.'::text,'kalsaydım'::text,'kalsam'::text,'kalacağım'::text,'Yeşil papağan şimdi keşke odaya dalmadan önce sakin kalsaydım diye düşünüyor.'::text),
(337734,37526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zöld papagáj most azt kívánja, bárcsak nyugodt ..., mielőtt berontott a szobába.'::text,'maradt volna'::text,'maradna'::text,'fog maradni'::text,'A zöld papagáj most azt kívánja, bárcsak nyugodt maradt volna, mielőtt berontott a szobába.'::text),
(337746,37528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des lauten Auftritts beruhigte der blaue Papagei das grüne Exemplar innerhalb von Sekunden.'::text,'Trotz'::text,'Obwohl'::text,'Im Falle'::text,'Trotz des lauten Auftritts beruhigte der blaue Papagei das grüne Exemplar innerhalb von Sekunden.'::text),
(337750,37528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... гучну появу, синій папуга заспокоїв зелену особину за лічені секунди.'::text,'Попри'::text,'Хоча'::text,'У разі'::text,'Попри гучну появу, синій папуга заспокоїв зелену особину за лічені секунди.'::text),
(337749,37528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la entrada ruidosa, el loro azul calmó al ejemplar verde en cuestión de segundos.'::text,'A pesar de'::text,'Aunque'::text,'En caso de'::text,'A pesar de la entrada ruidosa, el loro azul calmó al ejemplar verde en cuestión de segundos.'::text),
(337748,37528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''entrée bruyante, le perroquet bleu a calmé le spécimen vert en quelques secondes.'::text,'Malgré'::text,'Bien que'::text,'En cas de'::text,'Malgré l''entrée bruyante, le perroquet bleu a calmé le spécimen vert en quelques secondes.'::text),
(337751,37528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gürültülü girişe ..., mavi papağan yeşil örneği saniyeler içinde sakinleştirdi.'::text,'rağmen'::text,'rağmen'::text,'halinde'::text,'Gürültülü girişe rağmen, mavi papağan yeşil örneği saniyeler içinde sakinleştirdi.'::text),
(337752,37528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hangos belépés ... a kék papagáj másodpercek alatt megnyugtatta a zöld példányt.'::text,'ellenére'::text,'ellenére'::text,'esetén'::text,'A hangos belépés ellenére a kék papagáj másodpercek alatt megnyugtatta a zöld példányt.'::text),
(337755,37529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der blaue Papagei seine Flügel öffnete, wusste er, dass die Umarmung seinen Freund ...'::text,'beruhigen würde'::text,'beruhigen wird'::text,'beruhigt'::text,'Als der blaue Papagei seine Flügel öffnete, wusste er, dass die Umarmung seinen Freund beruhigen würde.'::text),
(337759,37529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли синій папуга розкрив крила, він знав, що обійми ... його друга.'::text,'заспокоять'::text,'заспокоять'::text,'заспокоюють'::text,'Коли синій папуга розкрив крила, він знав, що обійми заспокоять його друга.'::text),
(337758,37529,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el loro azul abrió las alas, sabía que el abrazo ... a su amigo.'::text,'calmaría'::text,'calmará'::text,'calma'::text,'Cuando el loro azul abrió las alas, sabía que el abrazo calmaría a su amigo.'::text),
(337757,37529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le perroquet bleu a ouvert ses ailes, il savait que le câlin ... son ami.'::text,'calmerait'::text,'calmera'::text,'calme'::text,'Quand le perroquet bleu a ouvert ses ailes, il savait que le câlin calmerait son ami.'::text),
(337760,37529,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mavi papağan kanatlarını açtığında sarılmanın arkadaşını ... biliyordu.'::text,'sakinleştireceğini'::text,'sakinleştireceğini'::text,'sakinleştirdiğini'::text,'Mavi papağan kanatlarını açtığında sarılmanın arkadaşını sakinleştireceğini biliyordu.'::text),
(337761,37529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor a kék papagáj kitárta a szárnyát, tudta, hogy az ölelés ... a barátját.'::text,'megnyugtatja'::text,'meg fogja nyugtatni'::text,'nyugtatja'::text,'Amikor a kék papagáj kitárta a szárnyát, tudta, hogy az ölelés megnyugtatja a barátját.'::text),
(337764,37530,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... der blaue Papagei seinen Freund mit einer langen, stillen Umarmung.'::text,'beruhigt'::text,'beruhigt'::text,'hat beruhigt'::text,'Gerade beruhigt der blaue Papagei seinen Freund mit einer langen, stillen Umarmung.'::text),
(337768,37530,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз синій папуга ... свого друга довгими тихими обіймами.'::text,'заспокоює'::text,'заспокоює'::text,'заспокоїв'::text,'Просто зараз синій папуга заспокоює свого друга довгими тихими обіймами.'::text),
(337767,37530,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo el loro azul ... a su amigo con un abrazo largo y tranquilo.'::text,'está calmando'::text,'calma'::text,'ha calmado'::text,'Ahora mismo el loro azul está calmando a su amigo con un abrazo largo y tranquilo.'::text),
(337766,37530,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, le perroquet bleu ... son ami avec un long câlin silencieux.'::text,'est en train de calmer'::text,'calme'::text,'a calmé'::text,'En ce moment, le perroquet bleu est en train de calmer son ami avec un long câlin silencieux.'::text),
(337769,37530,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda mavi papağan arkadaşını uzun, sessiz bir sarılmayla ...'::text,'sakinleştiriyor'::text,'sakinleştirir'::text,'sakinleştirdi'::text,'Şu anda mavi papağan arkadaşını uzun, sessiz bir sarılmayla sakinleştiriyor.'::text),
(337770,37530,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a kék papagáj egy hosszú, csendes öleléssel ... a barátját.'::text,'nyugtatja'::text,'nyugtatja'::text,'megnyugtatta'::text,'Épp most a kék papagáj egy hosszú, csendes öleléssel nyugtatja a barátját.'::text),
(337773,37531,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... er eine ganze Stunde lang geschrien, bevor der blaue Papagei ihn beruhigte.'::text,'hatte'::text,'hat'::text,'schreit'::text,'Mädel, anscheinend hatte er eine ganze Stunde lang geschrien, bevor der blaue Papagei ihn beruhigte.'::text),
(337777,37531,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... цілу годину, поки синій папуга його не заспокоїв.'::text,'кричав'::text,'кричить'::text,'кричить'::text,'Подруго, кажуть, він кричав цілу годину, поки синій папуга його не заспокоїв.'::text),
(337776,37531,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... una hora entera gritando antes de que el loro azul lo calmara.'::text,'había estado'::text,'ha estado'::text,'está'::text,'Tía, al parecer había estado una hora entera gritando antes de que el loro azul lo calmara.'::text),
(337775,37531,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment il ... pendant une heure entière avant que le perroquet bleu le calme.'::text,'avait crié'::text,'a crié'::text,'crie'::text,'Meuf, apparemment il avait crié pendant une heure entière avant que le perroquet bleu le calme.'::text),
(337778,37531,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya mavi papağan onu sakinleştirene kadar tam bir saat ...'::text,'bağırıp durmuş'::text,'bağırıyor'::text,'bağırıyor'::text,'Kızım, güya mavi papağan onu sakinleştirene kadar tam bir saat bağırıp durmuş.'::text),
(337779,37531,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egy teljes órán át ..., mielőtt a kék papagáj megnyugtatta.'::text,'kiabált'::text,'kiabál'::text,'kiabál'::text,'Csajszi, állítólag egy teljes órán át kiabált, mielőtt a kék papagáj megnyugtatta.'::text),
(337782,37532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, der blaue Papagei sagt, bis heute Abend ... ihn diese Umarmung endgültig beruhigt.'::text,'hat'::text,'wird'::text,'beruhigt'::text,'Rate mal, der blaue Papagei sagt, bis heute Abend hat ihn diese Umarmung endgültig beruhigt.'::text),
(337786,37532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, синій папуга каже, що до вечора ці обійми ... його остаточно.'::text,'заспокоять'::text,'заспокоюватимуть'::text,'заспокоюють'::text,'Уяви, синій папуга каже, що до вечора ці обійми заспокоять його остаточно.'::text),
(337785,37532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, el loro azul dice que para esta noche ese abrazo lo ... del todo.'::text,'habrá calmado'::text,'estará calmando'::text,'calma'::text,'Adivina, el loro azul dice que para esta noche ese abrazo lo habrá calmado del todo.'::text),
(337784,37532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, le perroquet bleu dit que d''ici ce soir ce câlin ... pour de bon.'::text,'l''aura calmé'::text,'sera en train de le calmer'::text,'le calme'::text,'Devine quoi, le perroquet bleu dit que d''ici ce soir ce câlin l''aura calmé pour de bon.'::text),
(337787,37532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, mavi papağan bu akşama kadar o sarılmanın onu tamamen ... söylüyor.'::text,'sakinleştirmiş olacağını'::text,'sakinleştiriyor olacağını'::text,'sakinleştirdiğini'::text,'Bil bakalım, mavi papağan bu akşama kadar o sarılmanın onu tamamen sakinleştirmiş olacağını söylüyor.'::text),
(337788,37532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, a kék papagáj azt mondja, estére az az ölelés végleg ... őt.'::text,'megnyugtatja'::text,'nyugtatni fogja'::text,'nyugtatja'::text,'Képzeld, a kék papagáj azt mondja, estére az az ölelés végleg megnyugtatja őt.'::text),
(370686,41188,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... die Hundefriseurin das Exemplar schon rund zwei Stunden lang, um ein gepflegtes Fell zu erreichen.'::text,'trimmt'::text,'trimmt gerade'::text,'wird trimmen'::text,'Bis Mittag trimmt die Hundefriseurin das Exemplar schon rund zwei Stunden lang, um ein gepflegtes Fell zu erreichen.'::text),
(370690,41188,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня грумерка ... особину приблизно дві години, щоб досягти охайної шерсті.'::text,'стригтиме'::text,'стригтиме'::text,'підстриже'::text,'До полудня грумерка стригтиме особину приблизно дві години, щоб досягти охайної шерсті.'::text),
(370689,41188,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, la peluquera canina ... al ejemplar durante unas dos horas para lograr un pelaje pulcro.'::text,'habrá estado recortando'::text,'estará recortando'::text,'recortará'::text,'Para el mediodía, la peluquera canina habrá estado recortando al ejemplar durante unas dos horas para lograr un pelaje pulcro.'::text),
(370688,41188,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, la toiletteuse ... le spécimen pendant environ deux heures pour obtenir un pelage net.'::text,'aura taillé'::text,'sera en train de tailler'::text,'taillera'::text,'D''ici midi, la toiletteuse aura taillé le spécimen pendant environ deux heures pour obtenir un pelage net.'::text),
(370691,41188,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar tımarcı düzgün bir tüy elde etmek için yaklaşık iki saattir örneği ...'::text,'kırpıyor olacak'::text,'kırpıyor olacak'::text,'kırpacak'::text,'Öğlene kadar tımarcı düzgün bir tüy elde etmek için yaklaşık iki saattir örneği kırpıyor olacak.'::text),
(370692,41188,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre a kutyakozmetikus már nagyjából két órája ... a példányt, hogy rendezett bundát érjen el.'::text,'nyírja majd'::text,'fogja nyírni'::text,'megnyírja'::text,'Délre a kutyakozmetikus már nagyjából két órája nyírja majd a példányt, hogy rendezett bundát érjen el.'::text),
(370695,41189,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte die Hundefriseurin keine Schere benutzt, ... das Fell des Hundes nicht so ordentlich ausgesehen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Hätte die Hundefriseurin keine Schere benutzt, hätte das Fell des Hundes nicht so ordentlich ausgesehen.'::text),
(370699,41189,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби грумерка не використала ножиці, шерсть собаки ... такою охайною.'::text,'не виглядала б'::text,'не виглядатиме'::text,'не виглядала'::text,'Якби грумерка не використала ножиці, шерсть собаки не виглядала б такою охайною.'::text),
(370698,41189,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la peluquera no hubiera usado tijeras, el pelaje del perro ... tan pulcro.'::text,'no habría quedado'::text,'no quedará'::text,'no quedó'::text,'Si la peluquera no hubiera usado tijeras, el pelaje del perro no habría quedado tan pulcro.'::text),
(370697,41189,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la toiletteuse n''avait pas utilisé de ciseaux, le pelage du chien ... aussi net.'::text,'n''aurait pas été'::text,'ne sera pas'::text,'n''a pas été'::text,'Si la toiletteuse n''avait pas utilisé de ciseaux, le pelage du chien n''aurait pas été aussi net.'::text),
(370700,41189,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tımarcı makas kullanmasaydı köpeğin tüyleri bu kadar düzgün ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmedi'::text,'Tımarcı makas kullanmasaydı köpeğin tüyleri bu kadar düzgün görünmezdi.'::text),
(370701,41189,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kutyakozmetikus nem használt volna ollót, a kutya bundája ... ilyen rendezett.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Ha a kutyakozmetikus nem használt volna ollót, a kutya bundája nem lett volna ilyen rendezett.'::text),
(370704,41190,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte die Hundefriseurin den Hund heute nicht getrimmt, ... er jetzt nicht so ordentlich aus.'::text,'sähe'::text,'hätte ausgesehen'::text,'wird aussehen'::text,'Hätte die Hundefriseurin den Hund heute nicht getrimmt, sähe er jetzt nicht so ordentlich aus.'::text),
(370708,41190,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби грумерка не підстригла собаку сьогодні, він зараз ... таким охайним.'::text,'не виглядав би'::text,'не виглядав би'::text,'не виглядатиме'::text,'Якби грумерка не підстригла собаку сьогодні, він зараз не виглядав би таким охайним.'::text),
(370707,41190,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la peluquera no hubiera recortado al perro hoy, ahora ... tan pulcro.'::text,'no estaría'::text,'no habría estado'::text,'no estará'::text,'Si la peluquera no hubiera recortado al perro hoy, ahora no estaría tan pulcro.'::text),
(370706,41190,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la toiletteuse n''avait pas taillé le chien aujourd''hui, il ... pas aussi net maintenant.'::text,'ne serait'::text,'n''aurait été'::text,'ne sera'::text,'Si la toiletteuse n''avait pas taillé le chien aujourd''hui, il ne serait pas aussi net maintenant.'::text),
(370709,41190,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tımarcı köpeği bugün kırpmasaydı şimdi bu kadar düzgün ...'::text,'görünmezdi'::text,'görünmemiş olurdu'::text,'görünmeyecek'::text,'Tımarcı köpeği bugün kırpmasaydı şimdi bu kadar düzgün görünmezdi.'::text),
(370710,41190,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kutyakozmetikus ma nem nyírta volna meg a kutyát, most ... ilyen rendezett.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha a kutyakozmetikus ma nem nyírta volna meg a kutyát, most nem lenne ilyen rendezett.'::text),
(370713,41191,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zwergspitz scheint kurz vor diesem Video ..., denn sein Fell ist ordentlich und sauber.'::text,'gewaschen worden zu sein'::text,'gewaschen zu werden'::text,'waschend'::text,'Der Zwergspitz scheint kurz vor diesem Video gewaschen worden zu sein, denn sein Fell ist ordentlich und sauber.'::text),
(370717,41191,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Схоже, шпіца ... якраз перед цим відео, бо його шерсть охайна й чиста.'::text,'помили'::text,'миють'::text,'миючи'::text,'Схоже, шпіца помили якраз перед цим відео, бо його шерсть охайна й чиста.'::text),
(370716,41191,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pomerania parece ... justo antes de este vídeo, porque tiene el pelaje pulcro y limpio.'::text,'haber sido lavado'::text,'ser lavado'::text,'lavando'::text,'El pomerania parece haber sido lavado justo antes de este vídeo, porque tiene el pelaje pulcro y limpio.'::text),
(370715,41191,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poméranien semble ... juste avant cette vidéo, car son pelage est net et propre.'::text,'avoir été lavé'::text,'être lavé'::text,'lavant'::text,'Le poméranien semble avoir été lavé juste avant cette vidéo, car son pelage est net et propre.'::text),
(370718,41191,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pomeranian bu videodan hemen önce ... görünüyor, çünkü tüyleri düzgün ve temiz.'::text,'yıkanmış gibi'::text,'yıkanıyor gibi'::text,'yıkayarak'::text,'Pomeranian bu videodan hemen önce yıkanmış gibi görünüyor, çünkü tüyleri düzgün ve temiz.'::text),
(370719,41191,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tűnik, a pomerániait közvetlenül a videó előtt ..., mert a bundája rendezett és tiszta.'::text,'megfürdették'::text,'fürdetik'::text,'fürdetve'::text,'Úgy tűnik, a pomerániait közvetlenül a videó előtt megfürdették, mert a bundája rendezett és tiszta.'::text),
(370722,41192,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast versprochen, das Fell ordentlich ..., und du hast voll geliefert.'::text,'zu halten'::text,'zu halten'::text,'gehalten zu haben'::text,'Ehrlich, du hast versprochen, das Fell ordentlich zu halten, und du hast voll geliefert.'::text),
(370726,41192,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти пообіцяла ... шерсть охайною, і повністю це виконала.'::text,'тримати'::text,'тримати'::text,'тримавши'::text,'Чесно, ти пообіцяла тримати шерсть охайною, і повністю це виконала.'::text),
(370725,41192,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, prometiste ... el pelaje pulcro y lo cumpliste totalmente.'::text,'mantener'::text,'mantener'::text,'haber mantenido'::text,'Sinceramente, prometiste mantener el pelaje pulcro y lo cumpliste totalmente.'::text),
(370724,41192,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu avais promis de ... le pelage net, et tu as carrément assuré.'::text,'garder'::text,'garder'::text,'avoir gardé'::text,'Franchement, tu avais promis de garder le pelage net, et tu as carrément assuré.'::text),
(370727,41192,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası tüyleri düzgün ... söz verdin ve tam anlamıyla başardın.'::text,'tutmaya'::text,'tutmaya'::text,'tutmuş olmaya'::text,'Açıkçası tüyleri düzgün tutmaya söz verdin ve tam anlamıyla başardın.'::text),
(370728,41192,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, megígérted, hogy rendezetten ... a bundát, és totál hoztad.'::text,'tartod'::text,'tartod'::text,'tartottad'::text,'Őszintén, megígérted, hogy rendezetten tartod a bundát, és totál hoztad.'::text),
(370731,41193,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jahrelang trainiert haben; ein so ordentlicher Schnitt ist natürlich reines Glück.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Sie muss jahrelang trainiert haben; ein so ordentlicher Schnitt ist natürlich reines Glück.'::text),
(370735,41193,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... роками; такий охайний підстриг, звісно, чисте везіння.'::text,'напевно тренувалася'::text,'мала б тренуватися'::text,'не могла тренуватися'::text,'Вона напевно тренувалася роками; такий охайний підстриг, звісно, чисте везіння.'::text),
(370734,41193,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... entrenado durante años; un corte tan pulcro es obviamente pura suerte.'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'Ella debe de haber entrenado durante años; un corte tan pulcro es obviamente pura suerte.'::text),
(370733,41193,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... s''entraîner pendant des années ; une coupe aussi nette, c''est évidemment de la pure chance.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Elle a dû s''entraîner pendant des années ; une coupe aussi nette, c''est évidemment de la pure chance.'::text),
(370736,41193,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllarca eğitim ...; bu kadar düzgün bir kesim belli ki tamamen şans.'::text,'almış olmalı'::text,'almalıydı'::text,'almış olamaz'::text,'Yıllarca eğitim almış olmalı; bu kadar düzgün bir kesim belli ki tamamen şans.'::text),
(370737,41193,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évekig ...; ilyen rendezett vágás nyilván csak szerencse.'::text,'biztosan gyakorolt'::text,'gyakorolnia kellett volna'::text,'nem gyakorolhatott'::text,'Évekig biztosan gyakorolt; ilyen rendezett vágás nyilván csak szerencse.'::text),
(370749,41195,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ich muss meinem Hund das Fell auch so ordentlich ... lassen, echt jetzt.'::text,'schneiden'::text,'schneiden'::text,'schneidend'::text,'Digga, ich muss meinem Hund das Fell auch so ordentlich schneiden lassen, echt jetzt.'::text),
(370753,41195,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, мені треба ... своєму псу шерсть отак охайно, реально.'::text,'підстригти'::text,'підстригти'::text,'підстригаючи'::text,'Бро, мені треба підстригти своєму псу шерсть отак охайно, реально.'::text),
(370752,41195,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, tengo que hacer que le ... el pelo a mi perro así de pulcro, en serio.'::text,'corten'::text,'corten'::text,'cortando'::text,'Bro, tengo que hacer que le corten el pelo a mi perro así de pulcro, en serio.'::text),
(370751,41195,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, je dois faire ... les poils de mon chien aussi nets, sérieux.'::text,'couper'::text,'couper'::text,'coupant'::text,'Frérot, je dois faire couper les poils de mon chien aussi nets, sérieux.'::text),
(370754,41195,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, köpeğimin tüylerini bu kadar düzgün ... lazım, cidden.'::text,'kestirmem'::text,'kestirmem'::text,'keserek'::text,'Kanka, köpeğimin tüylerini bu kadar düzgün kestirmem lazım, cidden.'::text),
(370755,41195,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nekem is ilyen rendesen le kell ... a kutyám szőrét, komolyan.'::text,'vágatnom'::text,'vágatnom'::text,'vágva'::text,'Tesó, nekem is ilyen rendesen le kell vágatnom a kutyám szőrét, komolyan.'::text),
(370758,41196,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, ich wünschte, mein Zimmer ... so ordentlich wie das Fell von diesem Hund, echt jetzt.'::text,'wäre'::text,'ist'::text,'wird'::text,'Nee, ich wünschte, mein Zimmer wäre so ordentlich wie das Fell von diesem Hund, echt jetzt.'::text),
(370762,41196,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, хотів би я, щоб моя кімната ... така охайна, як шерсть цього пса, реально.'::text,'була'::text,'є'::text,'буде'::text,'Не, хотів би я, щоб моя кімната була така охайна, як шерсть цього пса, реально.'::text),
(370761,41196,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, ojalá mi cuarto ... tan ordenado como el pelaje de este perro, en serio.'::text,'estuviera'::text,'está'::text,'estará'::text,'Nah, ojalá mi cuarto estuviera tan ordenado como el pelaje de este perro, en serio.'::text),
(370760,41196,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, j''aimerais que ma chambre ... aussi nickel que le pelage de ce chien, sérieux.'::text,'soit'::text,'est'::text,'sera'::text,'Nan, j''aimerais que ma chambre soit aussi nickel que le pelage de ce chien, sérieux.'::text),
(370763,41196,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, keşke odam da bu köpeğin tüyleri kadar düzenli ..., cidden.'::text,'olsa'::text,NULL::text,'olacak'::text,'Yok, keşke odam da bu köpeğin tüyleri kadar düzenli olsa, cidden.'::text),
(370764,41196,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, bárcsak a szobám ... olyan rendezett, mint ennek a kutyának a bundája, komolyan.'::text,'lenne'::text,NULL::text,'lesz'::text,'Nem, bárcsak a szobám lenne olyan rendezett, mint ennek a kutyának a bundája, komolyan.'::text),
(370767,41197,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hundefriseurin, ... ordentliche Schnitte 40 Kunden pro Woche bringen, arbeitet am Fenster.'::text,'deren'::text,'die'::text,'welche'::text,'Die Hundefriseurin, deren ordentliche Schnitte 40 Kunden pro Woche bringen, arbeitet am Fenster.'::text),
(370771,41197,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Грумерка, ... охайні стрижки приводять 40 клієнтів на тиждень, працює біля вікна.'::text,'чиї'::text,'яка'::text,'що'::text,'Грумерка, чиї охайні стрижки приводять 40 клієнтів на тиждень, працює біля вікна.'::text),
(370770,41197,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La peluquera canina, ... cortes pulcros atraen a 40 clientes a la semana, trabaja junto a la ventana.'::text,'cuyos'::text,'quien'::text,'la cual'::text,'La peluquera canina, cuyos cortes pulcros atraen a 40 clientes a la semana, trabaja junto a la ventana.'::text),
(370769,41197,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La toiletteuse, ... les coupes nettes attirent 40 clients par semaine, travaille près de la fenêtre.'::text,'dont'::text,'qui'::text,'laquelle'::text,'La toiletteuse, dont les coupes nettes attirent 40 clients par semaine, travaille près de la fenêtre.'::text),
(370772,41197,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... düzgün kesimleri haftada 40 müşteri getiren tımarcı, pencerenin yanında çalışıyor.'::text,''::text,NULL::text,NULL::text,'Düzgün kesimleri haftada 40 müşteri getiren tımarcı, pencerenin yanında çalışıyor.'::text),
(370773,41197,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutyakozmetikus, ... rendezett vágásai heti 40 ügyfelet hoznak, az ablaknál dolgozik.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A kutyakozmetikus, akinek a rendezett vágásai heti 40 ügyfelet hoznak, az ablaknál dolgozik.'::text),
(370776,41198,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des Hechelns des Hundes beendete die Hundefriseurin einen ordentlichen Rundschnitt.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des Hechelns des Hundes beendete die Hundefriseurin einen ordentlichen Rundschnitt.'::text),
(370780,41198,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... те, що собака важко дихала, грумерка завершила охайну круглу стрижку.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри те, що собака важко дихала, грумерка завершила охайну круглу стрижку.'::text),
(370779,41198,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los jadeos del perro, la peluquera terminó un corte redondo y pulcro.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de los jadeos del perro, la peluquera terminó un corte redondo y pulcro.'::text),
(370778,41198,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le halètement du chien, la toiletteuse a terminé une coupe ronde et nette.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré le halètement du chien, la toiletteuse a terminé une coupe ronde et nette.'::text),
(370781,41198,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpeğin soluk soluğa kalmasına ..., tımarcı düzgün, yuvarlak bir kesimi bitirdi.'::text,'rağmen'::text,'rağmen'::text,'yüzünden'::text,'Köpeğin soluk soluğa kalmasına rağmen, tımarcı düzgün, yuvarlak bir kesimi bitirdi.'::text),
(370782,41198,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya lihegése ... a kutyakozmetikus befejezett egy rendezett, kerek vágást.'::text,'ellenére'::text,'ellenére'::text,'miatt'::text,'A kutya lihegése ellenére a kutyakozmetikus befejezett egy rendezett, kerek vágást.'::text),
(388290,43144,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer ... heute wegen dieser Ente zweimal abgebremst.'::text,'hat'::text,'hat'::text,'bremst'::text,'Der Fahrer hat heute wegen dieser Ente zweimal abgebremst.'::text),
(388294,43144,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гонщик сьогодні двічі ... через ту качку.'::text,'пригальмував'::text,'пригальмовував'::text,'пригальмовує'::text,'Гонщик сьогодні двічі пригальмував через ту качку.'::text),
(388293,43144,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piloto ... dos veces hoy por culpa de ese pato.'::text,'ha frenado'::text,'ha estado frenando'::text,'está frenando'::text,'El piloto ha frenado dos veces hoy por culpa de ese pato.'::text),
(388292,43144,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pilote ... deux fois aujourd''hui à cause de ce canard.'::text,'a ralenti'::text,'a ralenti'::text,'est en train de ralentir'::text,'Le pilote a ralenti deux fois aujourd''hui à cause de ce canard.'::text),
(388295,43144,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürücü bugün o ördek yüzünden iki kez ...'::text,'yavaşladı'::text,'yavaşlıyordu'::text,'yavaşlıyor'::text,'Sürücü bugün o ördek yüzünden iki kez yavaşladı.'::text),
(388296,43144,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sofőr ma kétszer ... amiatt a kacsa miatt.'::text,'lassított'::text,'lassított'::text,'lassít'::text,'A sofőr ma kétszer lassított amiatt a kacsa miatt.'::text),
(388299,43145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, als die Ente drüben war, ... das Kart schon praktisch auf null abgebremst, ohne Witz.'::text,'hatte'::text,'hat'::text,'bremst'::text,'Alter, als die Ente drüben war, hatte das Kart schon praktisch auf null abgebremst, ohne Witz.'::text),
(388303,43145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, поки качка перейшла, карт ... практично до нуля, чесне слово.'::text,'сповільнився'::text,'сповільнився'::text,'сповільнюється'::text,'Чувак, поки качка перейшла, карт сповільнився практично до нуля, чесне слово.'::text),
(388302,43145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para cuando el pato cruzó, el kart ... prácticamente a cero, en serio.'::text,'había frenado'::text,'ha frenado'::text,'frena'::text,'Tío, para cuando el pato cruzó, el kart había frenado prácticamente a cero, en serio.'::text),
(388301,43145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, le temps que le canard traverse, le kart ... quasiment à zéro, sans mentir.'::text,'avait ralenti'::text,'a ralenti'::text,'ralentit'::text,'Mec, le temps que le canard traverse, le kart avait ralenti quasiment à zéro, sans mentir.'::text),
(388304,43145,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ördek karşıya geçtiğinde kart neredeyse sıfıra ..., yemin ederim.'::text,'yavaşlamıştı'::text,'yavaşladı'::text,'yavaşlıyor'::text,'Kanka, ördek karşıya geçtiğinde kart neredeyse sıfıra yavaşlamıştı, yemin ederim.'::text),
(388305,43145,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, mire a kacsa átért, a gokart gyakorlatilag nullára ..., komolyan.'::text,'lassult'::text,'lassult'::text,'lassul'::text,'Haver, mire a kacsa átért, a gokart gyakorlatilag nullára lassult, komolyan.'::text),
(388308,43146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn wieder eine Ente rausläuft, ..., ohne Witz.'::text,'bremse ich ab'::text,'würde ich abbremsen'::text,'bremste ich ab'::text,'Alter, wenn wieder eine Ente rausläuft, bremse ich ab, ohne Witz.'::text),
(388312,43146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якщо качка знову вийде, я ..., чесне слово.'::text,'пригальмую'::text,'пригальмував би'::text,'пригальмував'::text,'Чувак, якщо качка знову вийде, я пригальмую, чесне слово.'::text),
(388311,43146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si otro pato sale a la pista, ..., en serio.'::text,'frenaré'::text,'frenaría'::text,'frené'::text,'Tío, si otro pato sale a la pista, frenaré, en serio.'::text),
(388310,43146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, si un canard sort encore, je ..., sans mentir.'::text,'ralentirai'::text,'ralentirais'::text,'ai ralenti'::text,'Mec, si un canard sort encore, je ralentirai, sans mentir.'::text),
(388313,43146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yine bir ördek çıkarsa ..., yemin ederim.'::text,'yavaşlayacağım'::text,'yavaşlardım'::text,'yavaşladım'::text,'Kanka, yine bir ördek çıkarsa yavaşlayacağım, yemin ederim.'::text),
(388314,43146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha megint kijön egy kacsa, ..., komolyan.'::text,'lassítani fogok'::text,'lassítanék'::text,'lassítottam'::text,'Haver, ha megint kijön egy kacsa, lassítani fogok, komolyan.'::text),
(388317,43147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jedes Kart wegen Enten ..., würden wir das Rundenzeit-Ziel um 12 % verfehlen.'::text,'abbremste'::text,'abbremst'::text,'abbremsen würde'::text,'Wenn jedes Kart wegen Enten abbremste, würden wir das Rundenzeit-Ziel um 12 % verfehlen.'::text),
(388321,43147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби кожен карт ... через качок, ми б не виконали план за часом кола на 12 %.'::text,'гальмував'::text,'гальмує'::text,'гальмував би'::text,'Якби кожен карт гальмував через качок, ми б не виконали план за часом кола на 12 %.'::text),
(388320,43147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cada kart ... por los patos, no alcanzaríamos el objetivo de tiempo por vuelta por un 12 %.'::text,'frenara'::text,'frena'::text,'frenaría'::text,'Si cada kart frenara por los patos, no alcanzaríamos el objetivo de tiempo por vuelta por un 12 %.'::text),
(388319,43147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si chaque kart ... pour les canards, on raterait l''objectif de temps au tour de 12 %.'::text,'ralentissait'::text,'ralentit'::text,'ralentirait'::text,'Si chaque kart ralentissait pour les canards, on raterait l''objectif de temps au tour de 12 %.'::text),
(388322,43147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kart ördekler için ..., tur süresi hedefini %12 farkla kaçırırdık.'::text,'yavaşlasa'::text,'yavaşlıyorsa'::text,'yavaşlardı'::text,'Her kart ördekler için yavaşlasa, tur süresi hedefini %12 farkla kaçırırdık.'::text),
(388323,43147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha minden gokart ... a kacsák miatt, 12 %-kal elmaradnánk a köridő-céltól.'::text,'lassítana'::text,'lassít'::text,'lassítana'::text,'Ha minden gokart lassítana a kacsák miatt, 12 %-kal elmaradnánk a köridő-céltól.'::text),
(388326,43148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kart ... von der Ente ausgebremst, weil die Ente vor ihm war.'::text,'wurde'::text,'bremste'::text,'wird'::text,'Das Kart wurde von der Ente ausgebremst, weil die Ente vor ihm war.'::text),
(388330,43148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Карт ... качкою, бо качка була перед ним.'::text,'був загальмований'::text,'пригальмував'::text,'гальмується'::text,'Карт був загальмований качкою, бо качка була перед ним.'::text),
(388329,43148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El kart ... por el pato, porque el pato estaba delante de él.'::text,'fue frenado'::text,'frenó'::text,'es frenado'::text,'El kart fue frenado por el pato, porque el pato estaba delante de él.'::text),
(388328,43148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le kart ... par le canard, parce que le canard était devant lui.'::text,'a été ralenti'::text,'a ralenti'::text,'est ralenti'::text,'Le kart a été ralenti par le canard, parce que le canard était devant lui.'::text),
(388331,43148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kart ördek tarafından ..., çünkü ördek önündeydi.'::text,'yavaşlatıldı'::text,'yavaşladı'::text,'yavaşlatılıyor'::text,'Kart ördek tarafından yavaşlatıldı, çünkü ördek önündeydi.'::text),
(388332,43148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gokartot ... a kacsa, mert a kacsa előtte volt.'::text,'lelassította'::text,'lelassította'::text,'lassítja'::text,'A gokartot lelassította a kacsa, mert a kacsa előtte volt.'::text),
(388335,43149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer ... das Fahrzeug fast bis zum Stillstand ab, als die Ente die Strecke überquerte.'::text,'bremste'::text,'wurde gebremst'::text,'bremsend'::text,'Der Fahrer bremste das Fahrzeug fast bis zum Stillstand ab, als die Ente die Strecke überquerte.'::text),
(388339,43149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гонщик ... транспортний засіб майже до зупинки, поки качка перетинала трасу.'::text,'сповільнив'::text,'був сповільнений'::text,'сповільнюючи'::text,'Гонщик сповільнив транспортний засіб майже до зупинки, поки качка перетинала трасу.'::text),
(388338,43149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piloto ... el vehículo casi hasta detenerlo mientras el pato cruzaba el circuito.'::text,'frenó'::text,'fue frenado'::text,'frenando'::text,'El piloto frenó el vehículo casi hasta detenerlo mientras el pato cruzaba el circuito.'::text),
(388337,43149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pilote ... le véhicule presque jusqu''à l''arrêt pendant que le canard traversait le circuit.'::text,'a ralenti'::text,'a été ralenti'::text,'ralentissant'::text,'Le pilote a ralenti le véhicule presque jusqu''à l''arrêt pendant que le canard traversait le circuit.'::text),
(388340,43149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ördek pisti geçerken sürücü aracı neredeyse durma noktasına kadar ...'::text,'yavaşlattı'::text,'yavaşlatıldı'::text,'yavaşlatarak'::text,'Ördek pisti geçerken sürücü aracı neredeyse durma noktasına kadar yavaşlattı.'::text),
(388341,43149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pilóta szinte teljes megállásig ... a járművet, miközben a kacsa átkelt a pályán.'::text,'lelassította'::text,'lelassíttatott'::text,'lassítva'::text,'A pilóta szinte teljes megállásig lelassította a járművet, miközben a kacsa átkelt a pályán.'::text),
(388344,43150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kart kroch hinter ihr nur noch im Schneckentempo! Diese Ente ... völlig furchtlos sein!'::text,'muss'::text,'könnte'::text,'kann'::text,'Das Kart kroch hinter ihr nur noch im Schneckentempo! Diese Ente muss völlig furchtlos sein!'::text),
(388348,43150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Карт за нею поповз зі швидкістю равлика! Ця качка ... бути абсолютно безстрашною!'::text,'мусить'::text,'може'::text,'здатна'::text,'Карт за нею поповз зі швидкістю равлика! Ця качка мусить бути абсолютно безстрашною!'::text),
(388347,43150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El kart se quedó a paso de tortuga detrás de él! ¡Ese pato ... ser totalmente intrépido!'::text,'debe de'::text,'podría'::text,'puede'::text,'¡El kart se quedó a paso de tortuga detrás de él! ¡Ese pato debe de ser totalmente intrépido!'::text),
(388346,43150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le kart a ralenti au pas derrière lui ! Ce canard ... être complètement intrépide !'::text,'doit'::text,'pourrait'::text,'peut'::text,'Le kart a ralenti au pas derrière lui ! Ce canard doit être complètement intrépide !'::text),
(388349,43150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kart arkasında kaplumbağa hızına düştü! O ördek tamamen korkusuz ...!'::text,'olmalı'::text,'olabilir'::text,'olabilir'::text,'Kart arkasında kaplumbağa hızına düştü! O ördek tamamen korkusuz olmalı!'::text),
(388350,43150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gokart csigatempóra lassult mögötte! Ez a kacsa ... teljesen rettenthetetlen!'::text,'biztosan'::text,'talán'::text,'lehet'::text,'A gokart csigatempóra lassult mögötte! Ez a kacsa biztosan teljesen rettenthetetlen!'::text),
(388362,43152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mein Coach schrie, ich ... abbremsen, sonst verliere ich alles!'::text,'müsse'::text,'muss'::text,'muss'::text,'Mein Coach schrie, ich müsse abbremsen, sonst verliere ich alles!'::text),
(388366,43152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мій тренер кричав, що я ... пригальмувати, інакше втрачу все!'::text,'мушу'::text,'мушу'::text,'мушу'::text,'Мій тренер кричав, що я мушу пригальмувати, інакше втрачу все!'::text),
(388365,43152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mi entrenador gritó que ... frenar o lo perdería todo!'::text,'tenía que'::text,'tengo que'::text,'debo'::text,'¡Mi entrenador gritó que tenía que frenar o lo perdería todo!'::text),
(388364,43152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mon coach a hurlé que je ... ralentir ou que j''allais tout perdre !'::text,'devais'::text,'dois'::text,'dois'::text,'Mon coach a hurlé que je devais ralentir ou que j''allais tout perdre !'::text),
(388367,43152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koçum yavaşlamak ... olduğumu, yoksa her şeyi kaybedeceğimi bağırdı!'::text,'zorunda'::text,'zorunda'::text,'zorunda'::text,'Koçum yavaşlamak zorunda olduğumu, yoksa her şeyi kaybedeceğimi bağırdı!'::text),
(388368,43152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edzőm azt üvöltötte, hogy ... lassítanom, különben mindent elveszítek!'::text,'kellett'::text,'kell'::text,'kell'::text,'Az edzőm azt üvöltötte, hogy kellett lassítanom, különben mindent elveszítek!'::text),
(388371,43153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als ich mit dem Kartfahren anfing, ... ich vor jeder Kurve.'::text,'bremste immer'::text,'war gewohnt zu bremsen'::text,'bremste immer'::text,'Als ich mit dem Kartfahren anfing, bremste immer ich vor jeder Kurve.'::text),
(388375,43153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли я тільки почав кататися на картингу, я ... перед кожним поворотом.'::text,'завжди гальмував'::text,'звик гальмувати'::text,'завжди гальмував'::text,'Коли я тільки почав кататися на картингу, я завжди гальмував перед кожним поворотом.'::text),
(388374,43153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando empecé con el karting, ... frenar en cada curva.'::text,'solía'::text,'estaba acostumbrado a'::text,'solía'::text,'Cuando empecé con el karting, solía frenar en cada curva.'::text),
(388373,43153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand j''ai commencé le karting, je ... à chaque virage.'::text,'ralentissais'::text,'avais l''habitude de ralentir'::text,'ralentissais'::text,'Quand j''ai commencé le karting, je ralentissais à chaque virage.'::text),
(388376,43153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karta ilk başladığımda her virajda ...'::text,'yavaşlardım'::text,'yavaşlamaya alışkındım'::text,'yavaşlardım'::text,'Karta ilk başladığımda her virajda yavaşlardım.'::text),
(388377,43153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor elkezdtem gokartozni, minden kanyar előtt ... lassítani.'::text,'szoktam'::text,'hozzá voltam szokva'::text,'szoktam'::text,'Amikor elkezdtem gokartozni, minden kanyar előtt szoktam lassítani.'::text),
(388380,43154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer beschloss, ..., als die Ente auf die Strecke lief.'::text,'abzubremsen'::text,'abbremsend'::text,'abbremsen'::text,'Der Fahrer beschloss, abzubremsen, als die Ente auf die Strecke lief.'::text),
(388384,43154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гонщик вирішив ..., коли качка вийшла на трасу.'::text,'пригальмувати'::text,'пригальмовуючи'::text,'пригальмувати'::text,'Гонщик вирішив пригальмувати, коли качка вийшла на трасу.'::text),
(388383,43154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piloto decidió ... cuando el pato entró en la pista.'::text,'frenar'::text,'frenando'::text,'frenar'::text,'El piloto decidió frenar cuando el pato entró en la pista.'::text),
(388382,43154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pilote a décidé de ... quand le canard est arrivé sur la piste.'::text,'ralentir'::text,'ralentissant'::text,'ralentir'::text,'Le pilote a décidé de ralentir quand le canard est arrivé sur la piste.'::text),
(388385,43154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ördek piste çıkınca sürücü ... karar verdi.'::text,'yavaşlamaya'::text,'yavaşlayarak'::text,'yavaşla'::text,'Ördek piste çıkınca sürücü yavaşlamaya karar verdi.'::text),
(388386,43154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pilóta úgy döntött, hogy ..., amikor a kacsa a pályára lépett.'::text,'lassít'::text,'lassítva'::text,'lassít'::text,'A pilóta úgy döntött, hogy lassít, amikor a kacsa a pályára lépett.'::text),
(345612,38402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ein Fahrer hat mir erzählt, sie ... bis jetzt 40 Fotos von dem Schaden gemacht.'::text,'haben'::text,'haben'::text,'machen'::text,'Mädel, ein Fahrer hat mir erzählt, sie haben bis jetzt 40 Fotos von dem Schaden gemacht.'::text),
(345616,38402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, один водій сказав мені, що вони вже ... 40 фото пошкоджень.'::text,'зробили'::text,'робили'::text,'роблять'::text,'Подруго, один водій сказав мені, що вони вже зробили 40 фото пошкоджень.'::text),
(345615,38402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, un conductor me dijo que hasta ahora ... 40 fotos de los daños.'::text,'han hecho'::text,'han estado haciendo'::text,'están haciendo'::text,'Tía, un conductor me dijo que hasta ahora han hecho 40 fotos de los daños.'::text),
(345614,38402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, un des conducteurs m''a dit qu''ils ... 40 photos des dégâts jusqu''ici.'::text,'ont pris'::text,'prennent depuis'::text,'sont en train de prendre'::text,'Meuf, un des conducteurs m''a dit qu''ils ont pris 40 photos des dégâts jusqu''ici.'::text),
(345617,38402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, şoförlerden biri bana şimdiye kadar hasarın 40 fotoğrafını ... söyledi.'::text,'çektiklerini'::text,'çekip durduklarını'::text,'çekmekte olduklarını'::text,'Kızım, şoförlerden biri bana şimdiye kadar hasarın 40 fotoğrafını çektiklerini söyledi.'::text),
(345618,38402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, az egyik sofőr azt mondta, hogy eddig 40 fotót ... a kárról.'::text,'csináltak'::text,'csináltak'::text,'csinálnak'::text,'Csajszi, az egyik sofőr azt mondta, hogy eddig 40 fotót csináltak a kárról.'::text),
(345621,38403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend ... der Transporter schon ernsthaften Schaden angerichtet, als sie ausstiegen.'::text,'hatte'::text,'hat'::text,'richtet'::text,'Hör zu, anscheinend hatte der Transporter schon ernsthaften Schaden angerichtet, als sie ausstiegen.'::text),
(345625,38403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, поки вони вийшли, фургон уже ... серйозної шкоди.'::text,'завдав'::text,'завдав'::text,'завдає'::text,'Слухай, кажуть, поки вони вийшли, фургон уже завдав серйозної шкоди.'::text),
(345624,38403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer para cuando bajaron, la furgoneta ya ... daños graves.'::text,'había causado'::text,'ha causado'::text,'causa'::text,'Escucha, al parecer para cuando bajaron, la furgoneta ya había causado daños graves.'::text),
(345623,38403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment quand ils sont sortis, la camionnette ... déjà de gros dégâts.'::text,'avait fait'::text,'a fait'::text,'fait'::text,'Écoute, apparemment quand ils sont sortis, la camionnette avait fait déjà de gros dégâts.'::text),
(345626,38403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya onlar indiğinde minibüs çoktan ciddi hasar ...'::text,'vermişti'::text,'verdi'::text,'veriyor'::text,'Dinle, güya onlar indiğinde minibüs çoktan ciddi hasar vermişti.'::text),
(345627,38403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag mire kiszálltak, a furgon már komoly kárt ...'::text,'okozott'::text,'okozott'::text,'okoz'::text,'Figyelj, állítólag mire kiszálltak, a furgon már komoly kárt okozott.'::text),
(345630,38404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Fahrer den Schaden fotografieren, ... die Versicherung die Reparatur.'::text,'bezahlt'::text,'würde bezahlen'::text,'bezahlte'::text,'Wenn die Fahrer den Schaden fotografieren, bezahlt die Versicherung die Reparatur.'::text),
(345634,38404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо водії сфотографують пошкодження, страхова ... ремонт.'::text,'оплатить'::text,'оплатила б'::text,'оплатила'::text,'Якщо водії сфотографують пошкодження, страхова оплатить ремонт.'::text),
(345633,38404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los conductores fotografían los daños, la aseguradora ... la reparación.'::text,'pagará'::text,'pagaría'::text,'pagó'::text,'Si los conductores fotografían los daños, la aseguradora pagará la reparación.'::text),
(345632,38404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les conducteurs photographient les dégâts, l''assurance ... la réparation.'::text,'paiera'::text,'paierait'::text,'a payé'::text,'Si les conducteurs photographient les dégâts, l''assurance paiera la réparation.'::text),
(345635,38404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şoförler hasarın fotoğrafını çekerse sigorta şirketi onarımı ...'::text,'ödeyecek'::text,'öderdi'::text,'ödedi'::text,'Şoförler hasarın fotoğrafını çekerse sigorta şirketi onarımı ödeyecek.'::text),
(345636,38404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sofőrök lefotózzák a kárt, a biztosító ... a javítást.'::text,'ki fogja fizetni'::text,'kifizetné'::text,'kifizette'::text,'Ha a sofőrök lefotózzák a kárt, a biztosító ki fogja fizetni a javítást.'::text),
(345639,38405,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du so smooth fahren würdest, wie du Formulare ausfüllst, ... es keinen Schaden.'::text,'gäbe'::text,'gibt'::text,'gibt'::text,'Ehrlich, wenn du so smooth fahren würdest, wie du Formulare ausfüllst, gäbe es keinen Schaden.'::text),
(345643,38405,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти їздив так само плавно, як заповнюєш бланки, ... жодної шкоди.'::text,'не було б'::text,'не буде'::text,'немає'::text,'Чесно, якби ти їздив так само плавно, як заповнюєш бланки, не було б жодної шкоди.'::text),
(345642,38405,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si condujeras con la misma soltura con la que rellenas formularios, no ... ningún daño.'::text,'habría'::text,'habrá'::text,'hay'::text,'Sinceramente, si condujeras con la misma soltura con la que rellenas formularios, no habría ningún daño.'::text),
(345641,38405,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu conduisais aussi bien que tu remplis les formulaires, il n''y ... aucun dégât.'::text,'aurait'::text,'aura'::text,'a'::text,'Franchement, si tu conduisais aussi bien que tu remplis les formulaires, il n''y aurait aucun dégât.'::text),
(345644,38405,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası form doldurduğun kadar akıcı araba kullansaydın hiç hasar ...'::text,'olmazdı'::text,'olmayacak'::text,'yok'::text,'Açıkçası form doldurduğun kadar akıcı araba kullansaydın hiç hasar olmazdı.'::text),
(345645,38405,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha olyan simán vezetnél, ahogy a papírokat kitöltöd, ... semmi kár.'::text,'nem lenne'::text,'nem lesz'::text,'nincs'::text,'Őszintén, ha olyan simán vezetnél, ahogy a papírokat kitöltöd, nem lenne semmi kár.'::text),
(345648,38406,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schaden am hinteren Kotflügel des Autos ... von dem Lieferwagen verursacht.'::text,'wurde'::text,'verursachte'::text,'verursacht gerade'::text,'Der Schaden am hinteren Kotflügel des Autos wurde von dem Lieferwagen verursacht.'::text),
(345652,38406,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пошкодження задньому крилу машини ... фургоном доставки.'::text,'було завдано'::text,'завдав'::text,'завдає'::text,'Пошкодження задньому крилу машини було завдано фургоном доставки.'::text),
(345651,38406,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El daño en la aleta trasera del coche ... por la furgoneta de reparto.'::text,'fue causado'::text,'causó'::text,'está causando'::text,'El daño en la aleta trasera del coche fue causado por la furgoneta de reparto.'::text),
(345650,38406,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les dégâts à l''aile arrière de la voiture ... par la camionnette de livraison.'::text,'ont été causés'::text,'ont causé'::text,'sont en train de causer'::text,'Les dégâts à l''aile arrière de la voiture ont été causés par la camionnette de livraison.'::text),
(345653,38406,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabanın arka çamurluğundaki hasar teslimat minibüsü tarafından ...'::text,'verildi'::text,'verdi'::text,'veriyor'::text,'Arabanın arka çamurluğundaki hasar teslimat minibüsü tarafından verildi.'::text),
(345654,38406,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó hátsó sárvédőjén a kárt a szállítófurgon ...'::text,'okozta'::text,'okozta'::text,'okozza'::text,'Az autó hátsó sárvédőjén a kárt a szállítófurgon okozta.'::text),
(345657,38407,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der weiße Transporter ... ernsthaften Schaden am hinteren Kotflügel des grauen Autos.'::text,'verursachte'::text,'wurde verursacht'::text,'verursachend'::text,'Der weiße Transporter verursachte ernsthaften Schaden am hinteren Kotflügel des grauen Autos.'::text),
(345661,38407,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Білий фургон ... серйозне пошкодження задньому крилу сірої машини.'::text,'завдав'::text,'був завданий'::text,'завдаючи'::text,'Білий фургон завдав серйозне пошкодження задньому крилу сірої машини.'::text),
(345660,38407,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La furgoneta blanca ... daños graves en la aleta trasera del coche gris.'::text,'causó'::text,'fue causada'::text,'causando'::text,'La furgoneta blanca causó daños graves en la aleta trasera del coche gris.'::text),
(345659,38407,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La camionnette blanche ... de gros dégâts à l''aile arrière de la voiture grise.'::text,'a causé'::text,'a été causée'::text,'causant'::text,'La camionnette blanche a causé de gros dégâts à l''aile arrière de la voiture grise.'::text),
(345662,38407,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz minibüs gri arabanın arka çamurluğuna ciddi hasar ...'::text,'verdi'::text,'verildi'::text,'vererek'::text,'Beyaz minibüs gri arabanın arka çamurluğuna ciddi hasar verdi.'::text),
(345663,38407,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér furgon komoly kárt ... a szürke autó hátsó sárvédőjén.'::text,'okozott'::text,'okozva lett'::text,'okozva'::text,'A fehér furgon komoly kárt okozott a szürke autó hátsó sárvédőjén.'::text),
(345666,38408,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schaden ... mehr kosten als der Transporter selbst, aber noch weiß es niemand.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Der Schaden könnte mehr kosten als der Transporter selbst, aber noch weiß es niemand.'::text),
(345670,38408,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пошкодження ... коштувати більше, ніж сам фургон, але поки ніхто не знає.'::text,'може'::text,'мусить'::text,'не може'::text,'Пошкодження може коштувати більше, ніж сам фургон, але поки ніхто не знає.'::text),
(345669,38408,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El daño ... costar más que la propia furgoneta, pero nadie lo sabe todavía.'::text,'podría'::text,'debe de'::text,'no puede'::text,'El daño podría costar más que la propia furgoneta, pero nadie lo sabe todavía.'::text),
(345668,38408,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les dégâts ... coûter plus cher que la camionnette elle-même, mais personne ne le sait encore.'::text,'pourraient'::text,'doivent'::text,'ne peuvent pas'::text,'Les dégâts pourraient coûter plus cher que la camionnette elle-même, mais personne ne le sait encore.'::text),
(345671,38408,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasar minibüsün kendisinden daha pahalıya ..., ama henüz kimse bilmiyor.'::text,'mal olabilir'::text,'mal olmalı'::text,'mal olamaz'::text,'Hasar minibüsün kendisinden daha pahalıya mal olabilir, ama henüz kimse bilmiyor.'::text),
(345672,38408,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kár ... többe, mint maga a furgon, de még senki sem tudja.'::text,'kerülhet'::text,'biztosan kerül'::text,'nem kerülhet'::text,'A kár kerülhet többe, mint maga a furgon, de még senki sem tudja.'::text),
(345675,38409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der hintere Kotflügel ist das Teil, ... bei solchen Kollisionen typischerweise den Schaden abbekommt.'::text,'das'::text,'wer'::text,'wo'::text,'Der hintere Kotflügel ist das Teil, das bei solchen Kollisionen typischerweise den Schaden abbekommt.'::text),
(345679,38409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Заднє крило є тією частиною, ... зазвичай отримує пошкодження в таких зіткненнях.'::text,'яка'::text,'хто'::text,'де'::text,'Заднє крило є тією частиною, яка зазвичай отримує пошкодження в таких зіткненнях.'::text),
(345678,38409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La aleta trasera es la parte ... normalmente recibe el daño en este tipo de colisiones.'::text,'que'::text,'quien'::text,'donde'::text,'La aleta trasera es la parte que normalmente recibe el daño en este tipo de colisiones.'::text),
(345677,38409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''aile arrière est la partie ... reçoit généralement les dégâts dans ce genre de collisions.'::text,'qui'::text,'qui'::text,'où'::text,'L''aile arrière est la partie qui reçoit généralement les dégâts dans ce genre de collisions.'::text),
(345680,38409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arka çamurluk, ... bu tür çarpışmalarda hasarı genellikle alan parçadır.'::text,''::text,NULL::text,NULL::text,'Arka çamurluk, bu tür çarpışmalarda hasarı genellikle alan parçadır.'::text),
(345681,38409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hátsó sárvédő az a rész, ... az ilyen ütközéseknél jellemzően a kárt kapja.'::text,'amely'::text,'aki'::text,'ahol'::text,'A hátsó sárvédő az a rész, amely az ilyen ütközéseknél jellemzően a kárt kapja.'::text),
(345684,38410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schrie, er ... den Schaden in dem Moment gesehen, als er ausstieg. Totale Katastrophe!'::text,'habe'::text,'hat'::text,'sieht'::text,'Er schrie, er habe den Schaden in dem Moment gesehen, als er ausstieg. Totale Katastrophe!'::text),
(345688,38410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він кричав, що ... пошкодження, щойно вийшов. Повна катастрофа!'::text,'побачив'::text,'побачив'::text,'бачить'::text,'Він кричав, що побачив пошкодження, щойно вийшов. Повна катастрофа!'::text),
(345687,38410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gritó que ... el daño nada más bajarse. ¡Desastre total!'::text,'había visto'::text,'ha visto'::text,'ve'::text,'Gritó que había visto el daño nada más bajarse. ¡Desastre total!'::text),
(345686,38410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a hurlé qu''il ... les dégâts dès qu''il était sorti. Désastre total !'::text,'avait vu'::text,'a vu'::text,'voit'::text,'Il a hurlé qu''il avait vu les dégâts dès qu''il était sorti. Désastre total !'::text),
(345689,38410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arabadan indiği anda hasarı ... bağırdı. Tam bir felaket!'::text,'gördüğünü'::text,'gördüğünü'::text,'gördüğünü'::text,'Arabadan indiği anda hasarı gördüğünü bağırdı. Tam bir felaket!'::text),
(345690,38410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt üvöltötte, hogy abban a pillanatban ... a kárt, ahogy kiszállt. Totális katasztrófa!'::text,'meglátta'::text,'meglátta'::text,'látja'::text,'Azt üvöltötte, hogy abban a pillanatban meglátta a kárt, ahogy kiszállt. Totális katasztrófa!'::text),
(328953,36551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend verspricht die Buchhalterin, dass sie die fehlende Zahl heute Abend ...'::text,'finden wird'::text,'am Finden sein wird'::text,'gerade findet'::text,'Hör zu, anscheinend verspricht die Buchhalterin, dass sie die fehlende Zahl heute Abend finden wird.'::text),
(328957,36551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, бухгалтерка обіцяє, що ... відсутнє число сьогодні ввечері.'::text,'знайде'::text,'шукатиме'::text,'знаходить'::text,'Слухай, кажуть, бухгалтерка обіцяє, що знайде відсутнє число сьогодні ввечері.'::text),
(328956,36551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer la contable promete que ... el número que falta esta noche.'::text,'encontrará'::text,'estará encontrando'::text,'está encontrando'::text,'Escucha, al parecer la contable promete que encontrará el número que falta esta noche.'::text),
(328955,36551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la comptable promet qu''elle ... le chiffre manquant ce soir.'::text,'trouvera'::text,'sera en train de trouver'::text,'est en train de trouver'::text,'Écoute, apparemment la comptable promet qu''elle trouvera le chiffre manquant ce soir.'::text),
(328958,36551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya muhasebeci eksik sayıyı bu akşam ... söz veriyor.'::text,'bulacağına'::text,'buluyor olacağına'::text,'bulmakta olduğuna'::text,'Dinle, güya muhasebeci eksik sayıyı bu akşam bulacağına söz veriyor.'::text),
(328959,36551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a könyvelő megígéri, hogy ma este ... a hiányzó számot.'::text,'megtalálja'::text,'keresni fogja'::text,'épp megtalálja'::text,'Figyelj, állítólag a könyvelő megígéri, hogy ma este megtalálja a hiányzó számot.'::text),
(328962,36552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Buchhalterin eine falsche Zahl ..., kreist sie sie rot ein.'::text,'findet'::text,'fand'::text,'finden wird'::text,'Wenn eine Buchhalterin eine falsche Zahl findet, kreist sie sie rot ein.'::text),
(328966,36552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо бухгалтерка ... неправильну цифру, вона обводить її червоним.'::text,'знаходить'::text,'знайшла'::text,'знайде'::text,'Якщо бухгалтерка знаходить неправильну цифру, вона обводить її червоним.'::text),
(328965,36552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una contable ... una cifra incorrecta, la rodea en rojo.'::text,'encuentra'::text,'encontró'::text,'encontrará'::text,'Si una contable encuentra una cifra incorrecta, la rodea en rojo.'::text),
(328964,36552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une comptable ... un chiffre erroné, elle l''entoure en rouge.'::text,'trouve'::text,'a trouvé'::text,'trouvera'::text,'Si une comptable trouve un chiffre erroné, elle l''entoure en rouge.'::text),
(328967,36552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir muhasebeci yanlış bir rakam ..., onu kırmızıyla daire içine alır.'::text,'bulursa'::text,'bulduysa'::text,'bulacaksa'::text,'Bir muhasebeci yanlış bir rakam bulursa, onu kırmızıyla daire içine alır.'::text),
(328968,36552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy könyvelő hibás számot ..., bekarikázza pirossal.'::text,'talál'::text,'talált'::text,'fog találni'::text,'Ha egy könyvelő hibás számot talál, bekarikázza pirossal.'::text),
(328971,36553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Buchhalterin ... einen winzigen Taschenrechner, bevor sie diesen großen kaufte.'::text,'hatte früher'::text,'hatte'::text,'war gewohnt an'::text,'Die Buchhalterin hatte früher einen winzigen Taschenrechner, bevor sie diesen großen kaufte.'::text),
(328975,36553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бухгалтерка ... крихітний калькулятор, поки не купила цей великий.'::text,'раніше мала'::text,'мала'::text,'звикла мати'::text,'Бухгалтерка раніше мала крихітний калькулятор, поки не купила цей великий.'::text),
(328974,36553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La contable ... tener una calculadora diminuta antes de comprarse esta tan grande.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'La contable solía tener una calculadora diminuta antes de comprarse esta tan grande.'::text),
(328973,36553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comptable ... une toute petite calculatrice avant d''acheter cette grande.'::text,'avait avant'::text,'avait'::text,'avait l''habitude d''avoir'::text,'La comptable avait avant une toute petite calculatrice avant d''acheter cette grande.'::text),
(328976,36553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhasebecinin bu büyüğünü almadan önce ... minicik bir hesap makinesi vardı.'::text,'eskiden'::text,'eskiden'::text,'alışkın olduğu'::text,'Muhasebecinin bu büyüğünü almadan önce eskiden minicik bir hesap makinesi vardı.'::text),
(328977,36553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvelőnek ... egy apró számológépe, mielőtt megvette ezt a nagyot.'::text,'régen volt'::text,'volt'::text,'hozzá volt szokva'::text,'A könyvelőnek régen volt egy apró számológépe, mielőtt megvette ezt a nagyot.'::text),
(328980,36554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Buchhalterin weigert sich, ..., bevor jede Quittung geprüft ist.'::text,'nach Hause zu gehen'::text,'nach Hause gehend'::text,'nach Hause gehen'::text,'Die Buchhalterin weigert sich, nach Hause zu gehen, bevor jede Quittung geprüft ist.'::text),
(328984,36554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бухгалтерка відмовляється ... додому, поки не перевірить кожен чек.'::text,'йти'::text,'йдучи'::text,'іти'::text,'Бухгалтерка відмовляється йти додому, поки не перевірить кожен чек.'::text),
(328983,36554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La contable se niega a ... a casa antes de revisar cada recibo.'::text,'ir'::text,'yendo'::text,'ir'::text,'La contable se niega a ir a casa antes de revisar cada recibo.'::text),
(328982,36554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comptable refuse de ... chez elle avant que chaque reçu soit vérifié.'::text,'rentrer'::text,'rentrer'::text,'rentre'::text,'La comptable refuse de rentrer chez elle avant que chaque reçu soit vérifié.'::text),
(328985,36554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhasebeci her fiş kontrol edilmeden eve ... reddediyor.'::text,'gitmeyi'::text,'gitmeyi'::text,'git'::text,'Muhasebeci her fiş kontrol edilmeden eve gitmeyi reddediyor.'::text),
(328986,36554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvelő nem hajlandó ... haza, amíg minden blokkot át nem nézett.'::text,'menni'::text,'menve'::text,'megy'::text,'A könyvelő nem hajlandó menni haza, amíg minden blokkot át nem nézett.'::text),
(328989,36555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist die Art Buchhalterin, die nie aufgibt, ...? Respekt.'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Du bist die Art Buchhalterin, die nie aufgibt, oder? Respekt.'::text),
(328993,36555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти з тих бухгалтерок, які ніколи не здаються, ...? Респект.'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Ти з тих бухгалтерок, які ніколи не здаються, правда? Респект.'::text),
(328992,36555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eres el tipo de contable que nunca se rinde, ... Respeto.'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Eres el tipo de contable que nunca se rinde, ¿verdad? Respeto.'::text),
(328991,36555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu es le genre de comptable qui n''abandonne jamais, ... ? Respect.'::text,'pas vrai ?'::text,'pas vrai ?'::text,'pas vrai ?'::text,'Tu es le genre de comptable qui n''abandonne jamais, pas vrai ? Respect.'::text),
(328994,36555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen asla pes etmeyen türden bir muhasebecisin, ...? Saygılar.'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Sen asla pes etmeyen türden bir muhasebecisin, değil mi? Saygılar.'::text),
(328995,36555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te az a fajta könyvelő vagy, aki sosem adja fel, ...? Respekt.'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Te az a fajta könyvelő vagy, aki sosem adja fel, ugye? Respekt.'::text),
(328998,36556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Buchhalterin ging nicht früh nach Hause, und ... Eindeutig ein entspannter Job.'::text,'ihr Chef auch nicht.'::text,'ihr Chef schon.'::text,'ihr Chef auch nicht.'::text,'Die Buchhalterin ging nicht früh nach Hause, und ihr Chef auch nicht. Eindeutig ein entspannter Job.'::text),
(329002,36556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бухгалтерка не пішла додому раніше, і ... Явно розслаблена робота.'::text,'її шеф теж ні.'::text,'її шеф теж.'::text,'її шеф теж ні.'::text,'Бухгалтерка не пішла додому раніше, і її шеф теж ні. Явно розслаблена робота.'::text),
(329001,36556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La contable no se fue a casa temprano, y ... Claramente un trabajo relajado.'::text,'su jefe tampoco.'::text,'su jefe también.'::text,'su jefe tampoco.'::text,'La contable no se fue a casa temprano, y su jefe tampoco. Claramente un trabajo relajado.'::text),
(329000,36556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comptable n''est pas rentrée tôt, et ... Clairement un job reposant.'::text,'son patron non plus.'::text,'son patron aussi.'::text,'son patron non plus.'::text,'La comptable n''est pas rentrée tôt, et son patron non plus. Clairement un job reposant.'::text),
(329003,36556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhasebeci eve erken gitmedi, ... Belli ki rahat bir iş.'::text,'patronu da gitmedi.'::text,'patronu da gitti.'::text,'patronu da değildi.'::text,'Muhasebeci eve erken gitmedi, patronu da gitmedi. Belli ki rahat bir iş.'::text),
(329004,36556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvelő nem ment haza korán, és ... Egyértelműen pihentető meló.'::text,'a főnöke sem.'::text,'a főnöke is.'::text,'a főnöke sem.'::text,'A könyvelő nem ment haza korán, és a főnöke sem. Egyértelműen pihentető meló.'::text),
(329016,36558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte die Buchhalterin die Quittungen ordentlich sortiert, ... sie nicht so lange geblieben. Keine Einwände.'::text,'wäre'::text,'wird'::text,'ist'::text,'Hätte die Buchhalterin die Quittungen ordentlich sortiert, wäre sie nicht so lange geblieben. Keine Einwände.'::text),
(329020,36558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби бухгалтерка тримала чеки в порядку, вона ... так довго. Без зауважень.'::text,'не сиділа б'::text,'не сидітиме'::text,'не сиділа'::text,'Якби бухгалтерка тримала чеки в порядку, вона не сиділа б так довго. Без зауважень.'::text),
(329019,36558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la contable hubiera tenido los recibos en orden, no ... hasta tan tarde. Sin comentarios.'::text,'se habría quedado'::text,'se quedará'::text,'se quedó'::text,'Si la contable hubiera tenido los recibos en orden, no se habría quedado hasta tan tarde. Sin comentarios.'::text),
(329018,36558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la comptable avait gardé les reçus en ordre, elle ... aussi tard. Rien à redire.'::text,'ne serait pas restée'::text,'ne restera pas'::text,'n''est pas restée'::text,'Si la comptable avait gardé les reçus en ordre, elle ne serait pas restée aussi tard. Rien à redire.'::text),
(329021,36558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhasebeci fişleri düzenli tutsaydı bu kadar geç saate kadar ...; söyleyecek söz yok.'::text,'kalmazdı'::text,'kalmayacak'::text,'kalmadı'::text,'Muhasebeci fişleri düzenli tutsaydı bu kadar geç saate kadar kalmazdı; söyleyecek söz yok.'::text),
(329022,36558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a könyvelő rendben tartotta volna a blokkokat, ... ilyen sokáig. Nincs hozzáfűznivaló.'::text,'nem maradt volna'::text,'nem fog maradni'::text,'nem maradt'::text,'Ha a könyvelő rendben tartotta volna a blokkokat, nem maradt volna ilyen sokáig. Nincs hozzáfűznivaló.'::text),
(329025,36559,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Buchhalterin ... seit fünf Stunden auf diesen Quittungsstapel, ein totaler Albtraum!'::text,'starrt'::text,'starrt gerade'::text,'starrt'::text,'Die Buchhalterin starrt seit fünf Stunden auf diesen Quittungsstapel, ein totaler Albtraum!'::text),
(329029,36559,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бухгалтерка ... на цю купу чеків уже п''ять годин, повний жах!'::text,'витріщається'::text,'витріщається'::text,'витріщається'::text,'Бухгалтерка витріщається на цю купу чеків уже п''ять годин, повний жах!'::text),
(329028,36559,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La contable ... este montón de recibos desde hace cinco horas, una pesadilla total!'::text,'ha estado mirando'::text,'está mirando'::text,'mira'::text,'¡La contable ha estado mirando este montón de recibos desde hace cinco horas, una pesadilla total!'::text),
(329027,36559,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comptable ... ce tas de reçus depuis cinq heures, un vrai cauchemar !'::text,'fixe'::text,'est en train de fixer'::text,'fixe'::text,'La comptable fixe ce tas de reçus depuis cinq heures, un vrai cauchemar !'::text),
(329030,36559,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhasebeci beş saattir bu fiş yığınına ..., tam bir kâbus!'::text,'bakıyor'::text,'bakıyor'::text,'bakar'::text,'Muhasebeci beş saattir bu fiş yığınına bakıyor, tam bir kâbus!'::text),
(329031,36559,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvelő már öt órája ... ezt a blokkhalmot, totális rémálom!'::text,'bámulja'::text,'bámulja'::text,'bámulja'::text,'A könyvelő már öt órája bámulja ezt a blokkhalmot, totális rémálom!'::text),
(329034,36560,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Buchhalterin ... schon stundenlang gesucht, als sie endlich den schrecklichen Fehler fand!'::text,'hatte'::text,'hat'::text,'sucht'::text,'Die Buchhalterin hatte schon stundenlang gesucht, als sie endlich den schrecklichen Fehler fand!'::text),
(329038,36560,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бухгалтерка ... годинами, коли нарешті знайшла жахливу помилку!'::text,'шукала'::text,'шукає'::text,'шукає'::text,'Бухгалтерка шукала годинами, коли нарешті знайшла жахливу помилку!'::text),
(329037,36560,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La contable ... durante horas cuando por fin encontró el terrible error!'::text,'había estado buscando'::text,'ha estado buscando'::text,'busca'::text,'¡La contable había estado buscando durante horas cuando por fin encontró el terrible error!'::text),
(329036,36560,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comptable ... depuis des heures quand elle a enfin trouvé la terrible erreur !'::text,'cherchait'::text,'cherche'::text,'cherche'::text,'La comptable cherchait depuis des heures quand elle a enfin trouvé la terrible erreur !'::text),
(329039,36560,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muhasebeci sonunda korkunç hatayı bulduğunda saatlerdir ...!'::text,'arıyordu'::text,'arıyor'::text,'arar'::text,'Muhasebeci sonunda korkunç hatayı bulduğunda saatlerdir arıyordu!'::text),
(329040,36560,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A könyvelő már órák óta ..., amikor végre megtalálta a szörnyű hibát!'::text,'keresett'::text,'keres'::text,'keres'::text,'A könyvelő már órák óta keresett, amikor végre megtalálta a szörnyű hibát!'::text),
(385788,42866,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig eine schwere Wahl: Dieser Hund ... seit Monaten im Tierheim, und sie haben ihn schnell ausgesucht.'::text,'wartet'::text,'wartet gerade'::text,'wartet'::text,'Eindeutig eine schwere Wahl: Dieser Hund wartet seit Monaten im Tierheim, und sie haben ihn schnell ausgesucht.'::text),
(385792,42866,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно важкий вибір: цей пес ... в притулку вже кілька місяців, а вони вибрали його швидко.'::text,'чекає'::text,'чекає'::text,'чекає'::text,'Явно важкий вибір: цей пес чекає в притулку вже кілька місяців, а вони вибрали його швидко.'::text),
(385791,42866,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clarísimo, una elección difícil: este perro ... en el refugio desde hace meses, y lo eligieron rápido.'::text,'ha estado esperando'::text,'está esperando'::text,'espera'::text,'Clarísimo, una elección difícil: este perro ha estado esperando en el refugio desde hace meses, y lo eligieron rápido.'::text),
(385790,42866,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un choix difficile : ce chien ... au refuge depuis des mois, et ils l''ont choisi vite.'::text,'attend'::text,'est en train d''attendre'::text,'attend'::text,'Clairement un choix difficile : ce chien attend au refuge depuis des mois, et ils l''ont choisi vite.'::text),
(385793,42866,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki zor bir seçim: bu köpek aylardır barınakta ... ve onu hemen seçtiler.'::text,'bekliyor'::text,'bekliyor'::text,'bekler'::text,'Belli ki zor bir seçim: bu köpek aylardır barınakta bekliyor ve onu hemen seçtiler.'::text),
(385794,42866,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen nehéz döntés: ez a kutya hónapok óta ... a menhelyen, és gyorsan kiválasztották.'::text,'vár'::text,'vár'::text,'vár'::text,'Egyértelműen nehéz döntés: ez a kutya hónapok óta vár a menhelyen, és gyorsan kiválasztották.'::text),
(385797,42867,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während das Personal die Adoptionsformulare ..., wartete der Hund am Tresen des Tierheims. Spannend.'::text,'stempelte'::text,'abstempelte'::text,'abgestempelt hat'::text,'Während das Personal die Adoptionsformulare stempelte, wartete der Hund am Tresen des Tierheims. Spannend.'::text),
(385801,42867,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки персонал ... документи на усиновлення, пес чекав біля стійки притулку. Захопливо.'::text,'штампував'::text,'проштампував'::text,'проштампував'::text,'Поки персонал штампував документи на усиновлення, пес чекав біля стійки притулку. Захопливо.'::text),
(385800,42867,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el personal ... los formularios de adopción, el perro esperaba en el mostrador del refugio. Apasionante.'::text,'estaba sellando'::text,'selló'::text,'ha sellado'::text,'Mientras el personal estaba sellando los formularios de adopción, el perro esperaba en el mostrador del refugio. Apasionante.'::text),
(385799,42867,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le personnel ... les formulaires d''adoption, le chien attendait à l''accueil du refuge. Palpitant.'::text,'tamponnait'::text,'a tamponné'::text,'a tamponné'::text,'Pendant que le personnel tamponnait les formulaires d''adoption, le chien attendait à l''accueil du refuge. Palpitant.'::text),
(385802,42867,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personel sahiplendirme formlarını ..., köpek barınağın bankosunda bekledi. Çok heyecanlı.'::text,'damgalarken'::text,'damgaladığında'::text,'damgalamışken'::text,'Personel sahiplendirme formlarını damgalarken, köpek barınağın bankosunda bekledi. Çok heyecanlı.'::text),
(385803,42867,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a személyzet ... az örökbefogadási papírokat, a kutya a menhely pultjánál várt. Izgalmas.'::text,'pecsételte'::text,'lepecsételte'::text,'lepecsételte'::text,'Miközben a személyzet pecsételte az örökbefogadási papírokat, a kutya a menhely pultjánál várt. Izgalmas.'::text),
(385806,42868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, sie ... dieses Tierheim diesen Monat dreimal besucht, sind irgendwie voll besessen von ihm, echt jetzt.'::text,'haben'::text,'haben'::text,'besuchen'::text,'Nee, sie haben dieses Tierheim diesen Monat dreimal besucht, sind irgendwie voll besessen von ihm, echt jetzt.'::text),
(385810,42868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, вони ... цей притулок тричі за цей місяць, типу реально залипли на нього.'::text,'відвідали'::text,'відвідували'::text,'відвідують'::text,'Не, вони відвідали цей притулок тричі за цей місяць, типу реально залипли на нього.'::text),
(385809,42868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, ... este refugio tres veces este mes, están medio obsesionados con él, en serio.'::text,'han visitado'::text,'han estado visitando'::text,'están visitando'::text,'Nah, han visitado este refugio tres veces este mes, están medio obsesionados con él, en serio.'::text),
(385808,42868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, ils ... ce refuge trois fois ce mois-ci, un peu obsédés par lui, sérieux.'::text,'ont visité'::text,'ont visité'::text,'visitent'::text,'Nan, ils ont visité ce refuge trois fois ce mois-ci, un peu obsédés par lui, sérieux.'::text),
(385811,42868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, bu ay bu barınağı üç kez ..., resmen ona takıntılılar, cidden.'::text,'ziyaret ettiler'::text,'ziyaret edip duruyorlar'::text,'ziyaret ediyorlar'::text,'Yok, bu ay bu barınağı üç kez ziyaret ettiler, resmen ona takıntılılar, cidden.'::text),
(385812,42868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, ebben a hónapban háromszor ... ezt a menhelyet, eléggé rá vannak kattanva, komolyan.'::text,'meglátogatták'::text,'látogatták'::text,'látogatják'::text,'Nem, ebben a hónapban háromszor meglátogatták ezt a menhelyet, eléggé rá vannak kattanva, komolyan.'::text),
(385815,42869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Hund ... monatelang in dem Tierheim gelebt, bevor sie aufgetaucht sind, ohne Witz.'::text,'hatte'::text,'hat'::text,'lebt'::text,'Digga, der Hund hatte monatelang in dem Tierheim gelebt, bevor sie aufgetaucht sind, ohne Witz.'::text),
(385819,42869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, пес ... в тому притулку місяцями, поки вони не з''явилися, чесне слово.'::text,'жив'::text,'живе'::text,'живе'::text,'Бро, пес жив в тому притулку місяцями, поки вони не з''явилися, чесне слово.'::text),
(385818,42869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el perro ... en ese refugio durante meses antes de que aparecieran, en serio.'::text,'había vivido'::text,'ha vivido'::text,'vive'::text,'Bro, el perro había vivido en ese refugio durante meses antes de que aparecieran, en serio.'::text),
(385817,42869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le chien ... dans ce refuge pendant des mois avant qu''ils débarquent, sans mentir.'::text,'avait vécu'::text,'a vécu'::text,'vit'::text,'Frérot, le chien avait vécu dans ce refuge pendant des mois avant qu''ils débarquent, sans mentir.'::text),
(385820,42869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onlar gelmeden önce köpek aylarca o barınakta ..., yemin ederim.'::text,'yaşamıştı'::text,'yaşadı'::text,'yaşıyor'::text,'Kanka, onlar gelmeden önce köpek aylarca o barınakta yaşamıştı, yemin ederim.'::text),
(385821,42869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a kutya hónapokig ... abban a menhelyen, mielőtt felbukkantak, komolyan.'::text,'élt'::text,'él'::text,'él'::text,'Tesó, a kutya hónapokig élt abban a menhelyen, mielőtt felbukkantak, komolyan.'::text),
(385824,42870,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... das Tierheim 3 weitere Adoptionstermine ab.'::text,'hält gerade'::text,'hält'::text,'hält'::text,'Morgen um diese Zeit hält gerade das Tierheim 3 weitere Adoptionstermine ab.'::text),
(385828,42870,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час притулок ... ще 3 зустрічі щодо усиновлення.'::text,'проводитиме'::text,'проведе'::text,'проводить'::text,'Завтра в цей час притулок проводитиме ще 3 зустрічі щодо усиновлення.'::text),
(385827,42870,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el refugio ... 3 reuniones de adopción más.'::text,'estará celebrando'::text,'celebrará'::text,'celebra'::text,'Mañana a esta hora, el refugio estará celebrando 3 reuniones de adopción más.'::text),
(385826,42870,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, le refuge ... 3 rendez-vous d''adoption de plus.'::text,'sera en train de tenir'::text,'tiendra'::text,'tient'::text,'Demain à la même heure, le refuge sera en train de tenir 3 rendez-vous d''adoption de plus.'::text),
(385829,42870,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte barınak 3 sahiplendirme görüşmesi daha ...'::text,'yapıyor olacak'::text,'yapacak'::text,'yapıyor'::text,'Yarın bu saatte barınak 3 sahiplendirme görüşmesi daha yapıyor olacak.'::text),
(385830,42870,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a menhely még 3 örökbefogadási megbeszélést ...'::text,'fog tartani'::text,'fog tartani'::text,'tart'::text,'Holnap ilyenkor a menhely még 3 örökbefogadási megbeszélést fog tartani.'::text),
(385833,42871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... der Hund auf ihrem Sofa, nicht im Tierheim, weil er dann zu Hause ist.'::text,'schläft'::text,'schläft'::text,'schläft gerade'::text,'Morgen um diese Zeit schläft der Hund auf ihrem Sofa, nicht im Tierheim, weil er dann zu Hause ist.'::text),
(385837,42871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час пес ... на їхньому дивані, а не в притулку, бо він буде вдома.'::text,'спатиме'::text,'спатиме'::text,'спить'::text,'Завтра в цей час пес спатиме на їхньому дивані, а не в притулку, бо він буде вдома.'::text),
(385836,42871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora el perro ... en su sofá, no en el refugio, porque estará en casa.'::text,'estará durmiendo'::text,'dormirá'::text,'está durmiendo'::text,'Mañana a esta hora el perro estará durmiendo en su sofá, no en el refugio, porque estará en casa.'::text),
(385835,42871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, le chien ... sur leur canapé, pas au refuge, parce qu''il sera à la maison.'::text,'sera en train de dormir'::text,'dormira'::text,'dort'::text,'Demain à la même heure, le chien sera en train de dormir sur leur canapé, pas au refuge, parce qu''il sera à la maison.'::text),
(385838,42871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte köpek barınakta değil, onların kanepesinde ..., çünkü evde olacak.'::text,'uyuyor olacak'::text,'uyuyacak'::text,'uyuyor'::text,'Yarın bu saatte köpek barınakta değil, onların kanepesinde uyuyor olacak, çünkü evde olacak.'::text),
(385839,42871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a kutya az ő kanapéjukon ..., nem a menhelyen, mert otthon lesz.'::text,'fog aludni'::text,'fog aludni'::text,'alszik'::text,'Holnap ilyenkor a kutya az ő kanapéjukon fog aludni, nem a menhelyen, mert otthon lesz.'::text),
(385842,42872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Tierheim ein Tier an eine neue Familie ..., erfordert der Prozess in der Regel unterschriebene Formulare.'::text,'abgibt'::text,'abgab'::text,'abgeben wird'::text,'Wenn ein Tierheim ein Tier an eine neue Familie abgibt, erfordert der Prozess in der Regel unterschriebene Formulare.'::text),
(385846,42872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли притулок ... тварину новій родині, процес зазвичай потребує підписаних документів.'::text,'передає'::text,'передав'::text,'передасть'::text,'Коли притулок передає тварину новій родині, процес зазвичай потребує підписаних документів.'::text),
(385845,42872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un refugio ... un animal a una nueva familia, el proceso suele requerir formularios firmados.'::text,'entrega'::text,'entregó'::text,'entregará'::text,'Si un refugio entrega un animal a una nueva familia, el proceso suele requerir formularios firmados.'::text),
(385844,42872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand un refuge ... un animal à une nouvelle famille, le processus exige généralement des formulaires signés.'::text,'confie'::text,'a confié'::text,'confiera'::text,'Quand un refuge confie un animal à une nouvelle famille, le processus exige généralement des formulaires signés.'::text),
(385847,42872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir barınak bir hayvanı yeni bir aileye ..., süreç genellikle imzalı formlar gerektirir.'::text,'verirse'::text,'verdiyse'::text,'verecekse'::text,'Bir barınak bir hayvanı yeni bir aileye verirse, süreç genellikle imzalı formlar gerektirir.'::text),
(385848,42872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy menhely egy állatot új családnak ..., a folyamat jellemzően aláírt papírokat igényel.'::text,'ad át'::text,'adott át'::text,'fog átadni'::text,'Ha egy menhely egy állatot új családnak ad át, a folyamat jellemzően aláírt papírokat igényel.'::text),
(385851,42873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Paar heute die Formulare unterschreibt, ... der Hund das Tierheim mit ihnen.'::text,'verlässt'::text,'würde verlassen'::text,'verließ'::text,'Wenn das Paar heute die Formulare unterschreibt, verlässt der Hund das Tierheim mit ihnen.'::text),
(385855,42873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо пара сьогодні підпише документи, пес ... притулок разом із ними.'::text,'покине'::text,'покинув би'::text,'покинув'::text,'Якщо пара сьогодні підпише документи, пес покине притулок разом із ними.'::text),
(385854,42873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pareja firma los formularios hoy, el perro ... el refugio con ellos.'::text,'dejará'::text,'dejaría'::text,'dejó'::text,'Si la pareja firma los formularios hoy, el perro dejará el refugio con ellos.'::text),
(385853,42873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le couple signe les formulaires aujourd''hui, le chien ... le refuge avec eux.'::text,'quittera'::text,'quitterait'::text,'a quitté'::text,'Si le couple signe les formulaires aujourd''hui, le chien quittera le refuge avec eux.'::text),
(385856,42873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çift formları bugün imzalarsa köpek barınaktan onlarla birlikte ...'::text,'ayrılacak'::text,'ayrılırdı'::text,'ayrıldı'::text,'Çift formları bugün imzalarsa köpek barınaktan onlarla birlikte ayrılacak.'::text),
(385857,42873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a pár ma aláírja a papírokat, a kutya velük együtt ... a menhelyet.'::text,'elhagyja'::text,'elhagyná'::text,'elhagyta'::text,'Ha a pár ma aláírja a papírokat, a kutya velük együtt elhagyja a menhelyet.'::text),
(385860,42874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... seit dem Frühling im Tierheim, aber heute geht er nach Hause.'::text,'lebt'::text,'lebt'::text,'lebt gerade'::text,'Der Hund lebt seit dem Frühling im Tierheim, aber heute geht er nach Hause.'::text),
(385864,42874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес ... в притулку з весни, але сьогодні він їде додому.'::text,'живе'::text,'живе'::text,'живе'::text,'Пес живе в притулку з весни, але сьогодні він їде додому.'::text),
(385863,42874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro ... en el refugio desde la primavera, pero hoy se va a casa.'::text,'ha vivido'::text,'vive'::text,'está viviendo'::text,'El perro ha vivido en el refugio desde la primavera, pero hoy se va a casa.'::text),
(385862,42874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... au refuge depuis le printemps, mais aujourd''hui il rentre à la maison.'::text,'vit'::text,'vit'::text,'est en train de vivre'::text,'Le chien vit au refuge depuis le printemps, mais aujourd''hui il rentre à la maison.'::text),
(385865,42874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek bahardan beri barınakta ..., ama bugün eve gidiyor.'::text,'yaşıyor'::text,'yaşar'::text,'yaşıyor'::text,'Köpek bahardan beri barınakta yaşıyor, ama bugün eve gidiyor.'::text),
(385866,42874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya tavasz óta ... a menhelyen, de ma hazamegy.'::text,'él'::text,'él'::text,'él'::text,'A kutya tavasz óta él a menhelyen, de ma hazamegy.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
